/**
 * ─── CollectionPickerDialog.tsx ─────────────────────────────────────
 *
 * A browsable collection picker dialog that lets the user select a
 * collection from the current project. Mirrors the FilePickerDialog
 * design with a scrollable list, selection highlighting, and
 * double-click to confirm.
 *
 * Used by EditNodeDialog to link a graph node to a collection.
 * ───────────────────────────────────────────────────────────────────
 */
import { useState, useMemo, useEffect } from "react";
import {
    Dialog,
    DialogContent,
    DialogHeader,
    DialogTitle,
    DialogFooter,
    DialogDescription,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { ScrollArea } from "@/components/ui/scroll-area";
import { useStore } from "@/store/useStore";
import { useShallow } from "@/lib/zustand-shallow";
import { Folder, FolderOpen } from "@phosphor-icons/react";
import { cn } from "@/lib/utils";
import { getIcon } from "@/utils/iconMap";
import { isLeafCollection } from "@/utils/collectionUtils";
import type { Collection } from "@/types";

interface CollectionPickerDialogProps {
    open: boolean;
    onOpenChange: (open: boolean) => void;
    onSelect: (collectionId: string) => void;
    initialCollectionId?: string;
}

export function CollectionPickerDialog({
    open,
    onOpenChange,
    onSelect,
    initialCollectionId,
}: CollectionPickerDialogProps) {
    const { collections, activeProjectId } = useStore(useShallow((state) => ({
        collections: state.collections,
        activeProjectId: state.activeProjectId,
    })));

    const [selectedId, setSelectedId] = useState<string>("");

    useEffect(() => {
        if (open) {
            setSelectedId(initialCollectionId || "");
        }
    }, [open, initialCollectionId]);

    const projectCollections = useMemo(
        () =>
            collections
                .filter(
                    (c: Collection) =>
                        c.projectId === activeProjectId &&
                        !c.deleted &&
                        isLeafCollection(c)
                )
                .sort((a: Collection, b: Collection) => a.name.localeCompare(b.name)),
        [collections, activeProjectId]
    );

    const handleConfirm = () => {
        if (selectedId) {
            onSelect(selectedId);
            onOpenChange(false);
        }
    };

    return (
        <Dialog open={open} onOpenChange={onOpenChange}>
            <DialogContent className="sm:max-w-[420px]">
                <DialogHeader>
                    <DialogTitle>Select Collection</DialogTitle>
                    <DialogDescription className="sr-only">
                        Choose a collection from this project.
                    </DialogDescription>
                </DialogHeader>

                <ScrollArea className="h-[280px] border rounded-none p-1">
                    {projectCollections.length === 0 ? (
                        <div className="flex flex-col items-center justify-center h-full text-muted-foreground gap-2">
                            <FolderOpen size={32} className="opacity-20" />
                            <span className="text-xs">No collections in this project</span>
                        </div>
                    ) : (
                        <div className="space-y-0.5">
                            {projectCollections.map((c: Collection) => {
                                const Icon = getIcon(c.icon);
                                return (
                                    <button
                                        key={c.id}
                                        className={cn(
                                            "w-full flex items-center gap-3 px-3 py-2 rounded-none text-sm text-left transition-colors",
                                            selectedId === c.id
                                                ? "bg-primary/20 text-primary"
                                                : "hover:bg-accent hover:text-accent-foreground text-muted-foreground"
                                        )}
                                        onClick={() => setSelectedId(c.id)}
                                        onDoubleClick={() => {
                                            setSelectedId(c.id);
                                            onSelect(c.id);
                                            onOpenChange(false);
                                        }}
                                    >
                                        <div
                                            className="w-5 h-5 rounded-none flex items-center justify-center shrink-0"
                                            style={{ backgroundColor: c.color || undefined }}
                                        >
                                            <Icon size={12} className="text-white" weight="bold" />
                                        </div>
                                        <span className="truncate">{c.name}</span>
                                    </button>
                                );
                            })}
                        </div>
                    )}
                </ScrollArea>

                <DialogFooter>
                    <Button variant="ghost" onClick={() => onOpenChange(false)}>Cancel</Button>
                    <Button
                        onClick={handleConfirm}
                        disabled={!selectedId}
                        data-sound-confirm
                    >
                        Select
                    </Button>
                </DialogFooter>
            </DialogContent>
        </Dialog>
    );
}

/**
 * ─── CreationDialogs.tsx ────────────────────────────────────────────
 *
 * Quick-creation dialogs for bootstrapping new top-level entities
 * (documents, graphs, and projects) inside a Whistler project.
 *
 * Features / Responsibilities:
 *   - NewDocDialog – create a new document with name, colour, and icon
 *   - NewGraphDialog – create a new graph with name, colour, and icon
 *   - NewProjectDialog – create a new project with a name
 *   - All dialogs delegate to the shared EntityForm component from
 *     StorageDialogs for consistent UX
 *   - Respects the user's accent-theme and default-colour preferences
 * ───────────────────────────────────────────────────────────────────
 */
import React, { useState, useEffect } from "react";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogDescription, DialogFooter } from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { EntityForm } from "@/components/dialogs/StorageDialogs";
import { useStore } from "@/store/useStore";
import { useShallow } from "@/lib/zustand-shallow";
import { PRESET_COLORS, ACCENT_COLOR_MAP } from "@/components/ui/ColorPicker";

interface NewDocDialogProps {
    open: boolean;
    onOpenChange: (open: boolean) => void;
    onSubmit: (name: string, color: string, icon: string) => void;
}

export function NewDocDialog({ open, onOpenChange, onSubmit }: NewDocDialogProps) {
    const { accentTheme, enableDefaultColorControls, defaultColors } = useStore(useShallow((state) => ({
        accentTheme: state.accentTheme,
        enableDefaultColorControls: state.enableDefaultColorControls,
        defaultColors: state.defaultColors,
    })));
    const accentColor = ACCENT_COLOR_MAP[(accentTheme as keyof typeof ACCENT_COLOR_MAP) || "orange"] ?? PRESET_COLORS[0];
    const docColor = enableDefaultColorControls && defaultColors?.file !== undefined
        ? defaultColors.file
        : accentColor;

    return (
        <Dialog open={open} onOpenChange={onOpenChange}>
            <DialogContent className="sm:max-w-md bg-zinc-950 border-zinc-800 text-white">
                <DialogHeader>
                    <DialogTitle>New Document</DialogTitle>
                    <DialogDescription className="text-zinc-400">
                        Customize your new document.
                    </DialogDescription>
                </DialogHeader>
                <EntityForm
                    label="Document Name"
                    placeholder="My Document"
                    submitLabel="Create"
                    defaultColor={docColor}
                    onSubmit={(name, description, color, icon) => {
                        onSubmit(name, color, icon);
                        onOpenChange(false);
                    }}
                    onCancel={() => onOpenChange(false)}
                />
            </DialogContent>
        </Dialog>
    );
}

interface NewGraphDialogProps {
    open: boolean;
    onOpenChange: (open: boolean) => void;
    onSubmit: (name: string, color: string, icon: string) => void;
}

export function NewGraphDialog({ open, onOpenChange, onSubmit }: NewGraphDialogProps) {
    const { accentTheme, enableDefaultColorControls, defaultColors } = useStore(useShallow((state) => ({
        accentTheme: state.accentTheme,
        enableDefaultColorControls: state.enableDefaultColorControls,
        defaultColors: state.defaultColors,
    })));
    const accentColor = ACCENT_COLOR_MAP[(accentTheme as keyof typeof ACCENT_COLOR_MAP) || "orange"] ?? PRESET_COLORS[0];
    const graphColor = enableDefaultColorControls && defaultColors?.graph !== undefined
        ? defaultColors.graph
        : accentColor;

    return (
        <Dialog open={open} onOpenChange={onOpenChange}>
            <DialogContent className="sm:max-w-md bg-zinc-950 border-zinc-800 text-white">
                <DialogHeader>
                    <DialogTitle>New Graph</DialogTitle>
                    <DialogDescription className="text-zinc-400">
                        Customize your new graph.
                    </DialogDescription>
                </DialogHeader>
                <EntityForm
                    label="Graph Name"
                    placeholder="My Graph"
                    submitLabel="Create"
                    defaultColor={graphColor}
                    onSubmit={(name, description, color, icon) => {
                        onSubmit(name, color, icon);
                        onOpenChange(false);
                    }}
                    onCancel={() => onOpenChange(false)}
                />
            </DialogContent>
        </Dialog>
    );
}

interface NewProjectDialogProps {
    open: boolean;
    onOpenChange: (open: boolean) => void;
    onSubmit: (name: string) => void;
}

export function NewProjectDialog({ open, onOpenChange, onSubmit }: NewProjectDialogProps) {
    const [name, setName] = useState("");

    const handleSubmit = () => {
        if (!name.trim()) return;
        onSubmit(name.trim());
        setName("");
        onOpenChange(false);
    };

    return (
        <Dialog open={open} onOpenChange={onOpenChange}>
            <DialogContent className="sm:max-w-md bg-zinc-950 border-zinc-800 text-white">
                <DialogHeader>
                    <DialogTitle>New Project</DialogTitle>
                    <DialogDescription className="text-zinc-400">
                        Name your new project.
                    </DialogDescription>
                </DialogHeader>
                <div className="space-y-4 py-4">
                    <div className="space-y-2">
                        <Label htmlFor="new-project-name" className="text-zinc-400">
                            Project Name
                        </Label>
                        <Input
                            id="new-project-name"
                            placeholder="My Project"
                            value={name}
                            onChange={(e: React.ChangeEvent<HTMLInputElement>) => setName(e.target.value)}
                            autoFocus
                            className="bg-zinc-900 border-zinc-800 text-white placeholder:text-zinc-500"
                            onKeyDown={(e: React.KeyboardEvent<HTMLInputElement>) => e.key === "Enter" && handleSubmit()}
                        />
                    </div>
                </div>
                <div className="flex justify-end gap-3 pt-4">
                    <Button 
                        variant="ghost" 
                        onClick={() => onOpenChange(false)} 
                        className="text-zinc-400 hover:text-white hover:bg-zinc-900"
                    >
                        Cancel
                    </Button>
                    <Button 
                        onClick={handleSubmit} 
                        disabled={!name.trim()} 
                        className="bg-primary text-primary-foreground hover:opacity-90"
                        data-sound-confirm
                    >
                        Create
                    </Button>
                </div>
            </DialogContent>
        </Dialog>
    );
}

