/**
 * ─── MoveFileDialog.tsx ─────────────────────────────────────────────
 *
 * Dialog for moving one or more files to a different storage or
 * folder within the active Whistler project.
 *
 * Features / Responsibilities:
 *   - Browsable storage and folder hierarchy with back navigation
 *   - Supports batch-moving multiple files at once
 *   - Prevents moving a folder into itself or its own descendants
 *   - Highlights the current location context and updates the store
 *     on confirmation
 * ───────────────────────────────────────────────────────────────────
 */
import { useState, useEffect, useMemo } from "react";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogDescription, DialogFooter } from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { ScrollArea } from "@/components/ui/scroll-area";
import { useStore } from "@/store/useStore";
import { useShallow } from "@/lib/zustand-shallow";
import type { File, Storage } from "@/types";
import { Folder, HardDrives, CaretLeft } from "@phosphor-icons/react";

interface MoveFileDialogProps {
    open: boolean;
    onOpenChange: (open: boolean) => void;
    fileIds: string[];
    container?: HTMLElement | null;
}

export function MoveFileDialog({ open, onOpenChange, fileIds, container }: MoveFileDialogProps) {
    const { 
        files, 
        storages, 
        updateFile, 
        activeProjectId, 
        activeStorageId: globalActiveStorageId 
    } = useStore(useShallow((state) => ({
        files: state.files,
        storages: state.storages,
        updateFile: state.updateFile,
        activeProjectId: state.activeProjectId,
        activeStorageId: state.activeStorageId,
    })));

    const [selectedStorageId, setSelectedStorageId] = useState<string | null>(null);
    const [currentFolderId, setCurrentFolderId] = useState<string | null>(null);

    // Names of files being moved (for description)
    const movingNames = useMemo(() =>
        fileIds
            .map(id => files.find((f: File) => f.id === id)?.name)
            .filter(Boolean)
            .join(", "),
        [fileIds, files]
    );

    // Filter storages for current project
    const projectStorages = useMemo(() => 
        storages.filter((s: Storage) => s.projectId === activeProjectId && !s.deleted),
        [storages, activeProjectId]
    );

    // Initialize state when dialog opens
    useEffect(() => {
        if (open) {
            // Default to the storage of the first file, or the active storage
            const firstFile = useStore.getState().files.find((f: File) => f.id === fileIds[0]);
            const initialStorageId = firstFile?.storageId || globalActiveStorageId || projectStorages[0]?.id || null;
            
            setSelectedStorageId(initialStorageId);
            setCurrentFolderId(null);
        }
    }, [open]); // Only run when open state changes

    // Filter folders to display in the list
    const displayedFolders = useMemo(() => {
        if (!activeProjectId || !selectedStorageId) return [];

        return files.filter((f: File) => 
            f.projectId === activeProjectId && 
            f.storageId === selectedStorageId &&
            // Handle null/undefined parentId consistently
            (currentFolderId ? f.parentId === currentFolderId : !f.parentId) &&
            !f.deleted &&
            f.type === 'folder' && 
            !fileIds.includes(f.id) // Don't show folders being moved to avoid circular dependency
        ).sort((a: File, b: File) => a.name.localeCompare(b.name));
    }, [files, activeProjectId, selectedStorageId, currentFolderId, fileIds]);

    const currentFolder = useMemo(() => 
        files.find((f: File) => f.id === currentFolderId),
        [files, currentFolderId]
    );

    const handleMove = () => {
        if (!selectedStorageId) return;

        fileIds.forEach(id => {
            // Prevent moving a folder into its own child (simplified check: prevent moving into self)
            if (id === currentFolderId) return;

            updateFile(id, {
                storageId: selectedStorageId,
                parentId: currentFolderId
            });
        });
        onOpenChange(false);
    };

    const handleBack = () => {
        if (currentFolder?.parentId) {
            setCurrentFolderId(currentFolder.parentId);
        } else {
            setCurrentFolderId(null);
        }
    };

    return (
        <Dialog open={open} onOpenChange={onOpenChange}>
            <DialogContent className="sm:max-w-[500px]" portalContainer={container}>
                <DialogHeader>
                    <DialogTitle>Move to...</DialogTitle>
                    <DialogDescription>
                        Choose a destination folder for{" "}
                        <span className="font-medium text-foreground">{movingNames || "selected items"}</span>.
                    </DialogDescription>
                </DialogHeader>
                
                {/* Storage Tabs */}
                {projectStorages.length > 0 ? (
                    <div className="flex items-center gap-2 overflow-x-auto pb-2 border-b border-border no-scrollbar">
                        {projectStorages.map((storage: Storage) => (
                            <Button
                                key={storage.id}
                                variant={selectedStorageId === storage.id ? "default" : "ghost"}
                                size="sm"
                                onClick={() => {
                                    setSelectedStorageId(storage.id);
                                    setCurrentFolderId(null);
                                }}
                                className="gap-2 shrink-0"
                            >
                                <HardDrives weight={selectedStorageId === storage.id ? "fill" : "regular"} />
                                {storage.name}
                            </Button>
                        ))}
                    </div>
                ) : (
                    <div className="text-sm text-muted-foreground text-center py-2">
                        No storages available.
                    </div>
                )}

                {/* Folder Navigation */}
                <div className="py-2">
                    <div className="flex items-center gap-2 mb-2 text-sm text-muted-foreground min-h-[32px] px-1">
                        {currentFolderId ? (
                            <div className="flex items-center gap-2">
                                <Button variant="ghost" size="icon" className="h-6 w-6" onClick={handleBack} data-sound-back>
                                    <CaretLeft />
                                </Button>
                                <span className="font-medium text-foreground flex items-center gap-2">
                                    <Folder weight="fill" className="text-amber-500" />
                                    {currentFolder?.name}
                                </span>
                            </div>
                        ) : (
                            <span className="px-2 flex items-center gap-2">
                                <HardDrives className="text-muted-foreground" />
                                Root
                            </span>
                        )}
                    </div>

                    <ScrollArea className="h-[250px] border rounded-md p-1">
                        {displayedFolders.length === 0 ? (
                            <div className="flex flex-col items-center justify-center h-full text-muted-foreground gap-2">
                                <Folder size={32} className="opacity-20" />
                                <span className="text-xs">No subfolders</span>
                            </div>
                        ) : (
                            <div className="space-y-1">
                                {displayedFolders.map((folder: File) => (
                                    <button
                                        key={folder.id}
                                        className="w-full flex items-center gap-3 px-3 py-2 rounded-md hover:bg-accent hover:text-accent-foreground text-sm text-left transition-colors"
                                        onClick={() => setCurrentFolderId(folder.id)}
                                    >
                                        <Folder className="text-amber-500 text-lg shrink-0" weight="fill" />
                                        <span className="truncate">{folder.name}</span>
                                    </button>
                                ))}
                            </div>
                        )}
                    </ScrollArea>
                </div>

                <DialogFooter>
                    <Button variant="ghost" onClick={() => onOpenChange(false)}>Cancel</Button>
                    <Button onClick={handleMove} disabled={!selectedStorageId} data-sound-confirm>
                        Move Here
                    </Button>
                </DialogFooter>
            </DialogContent>
        </Dialog>
    );
}

/**
 * ─── QuickAccessDialog.tsx ──────────────────────────────────────────
 *
 * A searchable quick-access dialog that surfaces project entities
 * (files, highlights, collections, docs, graphs, storages, and
 * projects) in a filterable, sortable list.
 *
 * Features / Responsibilities:
 *   - Type-scoped browsing with a dedicated QuickAccessType filter
 *   - Real-time fuzzy search across entity names
 *   - Ascending / descending sort by last-modified date
 *   - Single-click navigation: sets the active entity and routes to
 *     the appropriate view
 * ───────────────────────────────────────────────────────────────────
 */
import { useState, useMemo } from "react";
import { useStore } from "@/store/useStore";
import { useShallow } from "@/lib/zustand-shallow";
import { Dialog, DialogContent, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { 
    File, 
    FileText, 
    Tag, 
    Folder,
    Graph, 
    HardDrives, 
    Clock, 
    ProjectorScreenChart,
    MagnifyingGlass,
    SortAscending,
    SortDescending,
    CaretRight
} from "@phosphor-icons/react";
import { formatDistanceToNow } from "date-fns";
import { Button } from "@/components/ui/button";
import { useNavigate } from "react-router-dom";
import { findRootBucketId } from "@/utils/collectionUtils";
import type { Collection } from "@/types";

export type QuickAccessType = 'file' | 'highlight' | 'collection' | 'bucket' | 'doc' | 'graph' | 'storage' | 'project';

interface QuickAccessDialogProps {
    open: boolean;
    onOpenChange: (open: boolean) => void;
    type: QuickAccessType | null;
}

export function QuickAccessDialog({ open, onOpenChange, type }: QuickAccessDialogProps) {
    const { 
        files, 
        highlights, 
        collections, 
        docs, 
        graphs, 
        storages, 
        projects,
        activeProjectId,
        setActiveFile,
        setActiveDoc,
        setActiveCollection,
        setActiveGraph,
        setActiveProject
    } = useStore(useShallow((state) => ({
        files: state.files,
        highlights: state.highlights,
        collections: state.collections,
        docs: state.docs,
        graphs: state.graphs,
        storages: state.storages,
        projects: state.projects,
        activeProjectId: state.activeProjectId,
        setActiveFile: state.setActiveFile,
        setActiveDoc: state.setActiveDoc,
        setActiveCollection: state.setActiveCollection,
        setActiveGraph: state.setActiveGraph,
        setActiveProject: state.setActiveProject,
    })));
    
    const navigate = useNavigate();
    const [search, setSearch] = useState("");
    const [sortOrder, setSortOrder] = useState<'asc' | 'desc'>('desc');

    const items = useMemo(() => {
        if (!type) return [];
        
        let rawItems: Array<{ id: string; name?: string; title?: string; text?: string; note?: string; created?: number; lastModified?: number; fileId?: string; fileName?: string; type?: Collection['type'] }> = [];
        
        switch (type) {
            case 'file':
                rawItems = files.filter(f => f.projectId === activeProjectId && !f.deleted);
                break;
            case 'highlight':
                {
                    // Join highlights with files to filter by project
                    const projectFileIds = new Set(files.filter(f => f.projectId === activeProjectId).map(f => f.id));
                    rawItems = highlights.filter(h => projectFileIds.has(h.fileId)).map(h => {
                        const file = files.find(f => f.id === h.fileId);
                        return { ...h, name: h.note || h.text || "Untitled Highlight", fileName: file?.name };
                    });
                }
                break;
            case 'collection':
                rawItems = collections.filter(c => c.projectId === activeProjectId && !c.deleted && c.type !== 'bucket');
                break;
            case 'bucket':
                rawItems = collections.filter(c => c.projectId === activeProjectId && !c.deleted && c.type === 'bucket');
                break;
            case 'doc':
                rawItems = docs.filter(d => d.projectId === activeProjectId && !d.deleted);
                break;
            case 'graph':
                rawItems = graphs.filter(g => g.projectId === activeProjectId); // graphs don't have deleted flag yet?
                break;
            case 'storage':
                rawItems = storages.filter(s => s.projectId === activeProjectId && !s.deleted);
                break;
            case 'project':
                rawItems = projects; // Show all projects
                break;
        }

        return rawItems
            .filter(item => {
                const name = item.name || item.title || item.text || "";
                return name.toLowerCase().includes(search.toLowerCase());
            })
            .sort((a, b) => {
                const dateA = a.lastModified || a.created || 0;
                const dateB = b.lastModified || b.created || 0;
                return sortOrder === 'desc' ? dateB - dateA : dateA - dateB;
            });
    }, [type, files, highlights, collections, docs, graphs, storages, projects, activeProjectId, search, sortOrder]);

    const handleItemClick = (item: { id: string; fileId?: string; type?: Collection['type'] }) => {
        switch (type) {
            case 'file':
                setActiveFile(item.id);
                navigate(`/file/${item.id}`);
                break;
            case 'highlight':
                if (item.fileId) {
                    setActiveFile(item.fileId);
                    navigate(`/file/${item.fileId}`);
                }
                break;
            case 'collection':
                {
                    const bucketId = findRootBucketId(collections, item.id);
                    if (bucketId) {
                        setActiveCollection(bucketId);
                    }
                    if (item.type === 'folder') {
                        navigate(`/collections?folderId=${item.id}`);
                    } else {
                        navigate(`/collection/${item.id}`);
                    }
                }
                break;
            case 'bucket':
                setActiveCollection(item.id);
                navigate('/collections');
                break;
            case 'doc':
                setActiveDoc(item.id);
                navigate('/docs');
                break;
            case 'graph':
                setActiveGraph(item.id);
                navigate('/graphs');
                break;
            case 'storage':
                // Navigate to storage view
                navigate(`/storage?storageId=${item.id}`);
                break;
            case 'project':
                setActiveProject(item.id);
                navigate('/');
                break;
        }
        onOpenChange(false);
    };

    const getIcon = () => {
        switch (type) {
            case 'file': return File;
            case 'highlight': return Clock;
            case 'collection': return Tag;
            case 'bucket': return Folder;
            case 'doc': return FileText;
            case 'graph': return Graph;
            case 'storage': return HardDrives;
            case 'project': return ProjectorScreenChart;
            default: return File;
        }
    };

    const Icon = getIcon();

    const getTitle = () => {
        switch (type) {
            case 'file': return "All Files";
            case 'highlight': return "All Highlights";
            case 'collection': return "All Collections";
            case 'bucket': return "All Buckets";
            case 'doc': return "All Documents";
            case 'graph': return "All Graphs";
            case 'storage': return "All Storages";
            case 'project': return "All Projects";
            default: return "Items";
        }
    };

    return (
        <Dialog open={open} onOpenChange={onOpenChange}>
            <DialogContent className="max-w-2xl max-h-[80vh] flex flex-col p-0 gap-0 overflow-hidden bg-background/95 backdrop-blur-xl border-border/50">
                <DialogHeader className="p-4 border-b border-border/10">
                    <div className="flex items-center gap-2 text-muted-foreground mb-1">
                        <Icon weight="duotone" className="w-5 h-5" />
                        <span className="text-xs uppercase tracking-wider font-medium">Quick Access</span>
                    </div>
                    <DialogTitle className="text-xl">{getTitle()}</DialogTitle>
                </DialogHeader>

                <div className="p-4 border-b border-border/10 flex items-center gap-2">
                    <div className="relative flex-1">
                        <MagnifyingGlass className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
                        <Input 
                            value={search} 
                            onChange={(e) => setSearch(e.target.value)} 
                            placeholder="Search items..." 
                            className="pl-9 bg-muted/50 border-none focus-visible:ring-1"
                        />
                    </div>
                    <Button 
                        variant="ghost" 
                        size="icon" 
                        onClick={() => setSortOrder(prev => prev === 'asc' ? 'desc' : 'asc')}
                        title={`Sort by Date (${sortOrder === 'asc' ? 'Oldest' : 'Newest'})`}
                    >
                        {sortOrder === 'asc' ? <SortAscending size={20} /> : <SortDescending size={20} />}
                    </Button>
                </div>

                <div className="flex-1 overflow-y-auto p-2">
                    {items.length > 0 ? (
                        <div className="flex flex-col gap-1">
                            {items.map(item => (
                                <button
                                    key={item.id}
                                    onClick={() => handleItemClick(item)}
                                    className="flex items-center gap-3 p-3 rounded-lg hover:bg-muted/50 transition-colors text-left group"
                                >
                                    <div className="p-2 rounded-md bg-background border border-border/40 text-muted-foreground group-hover:text-primary group-hover:border-primary/20 transition-colors">
                                        <Icon weight="duotone" className="w-5 h-5" />
                                    </div>
                                    <div className="flex-1 min-w-0">
                                        <div className="font-medium truncate text-sm">
                                            {item.name || item.title || item.text}
                                        </div>
                                        <div className="flex items-center gap-2 text-xs text-muted-foreground/60 mt-0.5">
                                            <span>
                                                {formatDistanceToNow(item.lastModified || item.created || 0, { addSuffix: true })}
                                            </span>
                                            {type === 'highlight' && item.fileName && (
                                                <>
                                                    <span>•</span>
                                                    <span className="truncate max-w-[150px]">{item.fileName}</span>
                                                </>
                                            )}
                                        </div>
                                    </div>
                                    <CaretRight className="w-4 h-4 text-muted-foreground/20 group-hover:text-muted-foreground/50" />
                                </button>
                            ))}
                        </div>
                    ) : (
                        <div className="flex flex-col items-center justify-center py-12 text-muted-foreground/50">
                            <Icon weight="duotone" className="w-12 h-12 mb-2 opacity-20" />
                            <p className="text-sm">No items found</p>
                        </div>
                    )}
                </div>
                
                <div className="p-2 border-t border-border/10 bg-muted/20 text-[10px] text-muted-foreground text-center">
                    {items.length} {items.length === 1 ? 'item' : 'items'} found
                </div>
            </DialogContent>
        </Dialog>
    );
}

/**
 * ─── ScreenshotDialog.tsx ───────────────────────────────────────────
 *
 * A screenshot preview and crop dialog. Displays a captured image
 * and lets the user draw a rectangular crop region before
 * downloading the result.
 *
 * Features / Responsibilities:
 *   - Full-resolution image preview inside a scrollable dialog
 *   - Click-and-drag crop rectangle with visual overlay
 *   - One-click download of the original or cropped image as PNG
 *   - Supports custom portal containers for panel embedding
 * ───────────────────────────────────────────────────────────────────
 */
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter, DialogDescription } from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { useState, useRef, useEffect, type MouseEvent } from "react";
import { DownloadSimple, X, CornersIn } from "@phosphor-icons/react";
import { cn, clamp } from "@/lib/utils";

interface ScreenshotDialogProps {
    open: boolean;
    onOpenChange: (open: boolean) => void;
    imageUrl: string | null;
    container?: HTMLElement | null;
}

export function ScreenshotDialog({ open, onOpenChange, imageUrl, container }: ScreenshotDialogProps) {
    const [cropRect, setCropRect] = useState<{ x: number, y: number, width: number, height: number } | null>(null);
    const [isDragging, setIsDragging] = useState(false);
    const [startPos, setStartPos] = useState<{ x: number, y: number } | null>(null);
    const imageRef = useRef<HTMLImageElement>(null);
    const containerRef = useRef<HTMLDivElement>(null);
    const cropRectRef = useRef<{ x: number, y: number, width: number, height: number } | null>(null);

    // Sync ref with state
    useEffect(() => {
        cropRectRef.current = cropRect;
    }, [cropRect]);

    // Reset state when dialog opens/closes or image changes
    useEffect(() => {
        if (!open) {
            setCropRect(null);
            setIsDragging(false);
            setStartPos(null);
        }
    }, [open, imageUrl]);

    const handleMouseDown = (e: MouseEvent) => {
        if (!containerRef.current || !imageRef.current) return;
        // Prevent default drag behavior
        e.preventDefault();
        
        const containerRect = containerRef.current.getBoundingClientRect();
        const imageRect = imageRef.current.getBoundingClientRect();

        // Mouse X relative to container
        const mouseXInContainer = e.clientX - containerRect.left;
        const mouseYInContainer = e.clientY - containerRect.top;

        // Image bounds relative to container
        const imageLeftInContainer = imageRect.left - containerRect.left;
        const imageTopInContainer = imageRect.top - containerRect.top;
        const imageRightInContainer = imageLeftInContainer + imageRect.width;
        const imageBottomInContainer = imageTopInContainer + imageRect.height;

        // Clamp start position to image bounds
        const startX = Math.max(imageLeftInContainer, Math.min(mouseXInContainer, imageRightInContainer));
        const startY = Math.max(imageTopInContainer, Math.min(mouseYInContainer, imageBottomInContainer));
        
        setIsDragging(true);
        setStartPos({ x: startX, y: startY });
        setCropRect({ x: startX, y: startY, width: 0, height: 0 });
    };

    useEffect(() => {
        if (!isDragging) return;

        const handleGlobalMouseMove = (e: globalThis.MouseEvent) => {
            if (!startPos || !containerRef.current || !imageRef.current) return;
            
            // Use the image rect for boundaries, not the container
            // This ensures we can't select the black bars
            const imageRect = imageRef.current.getBoundingClientRect();
            const containerRect = containerRef.current.getBoundingClientRect();

            // Calculate mouse position relative to the container (for the cropRect state)
            // But clamped to the image bounds
            
            // Mouse X relative to container
            const mouseXInContainer = e.clientX - containerRect.left;
            const mouseYInContainer = e.clientY - containerRect.top;

            // Image bounds relative to container
            const imageLeftInContainer = imageRect.left - containerRect.left;
            const imageTopInContainer = imageRect.top - containerRect.top;
            const imageRightInContainer = imageLeftInContainer + imageRect.width;
            const imageBottomInContainer = imageTopInContainer + imageRect.height;

            // Clamp mouse position to image bounds
            const clampedX = clamp(mouseXInContainer, imageLeftInContainer, imageRightInContainer);
            const clampedY = clamp(mouseYInContainer, imageTopInContainer, imageBottomInContainer);

            // Calculate dimensions
            const width = Math.abs(clampedX - startPos.x);
            const height = Math.abs(clampedY - startPos.y);
            const x = Math.min(clampedX, startPos.x);
            const y = Math.min(clampedY, startPos.y);
            
            setCropRect({ x, y, width, height });
        };

        const handleGlobalMouseUp = () => {
            setIsDragging(false);
            // Clear tiny selections using the ref to get latest state
            const currentRect = cropRectRef.current;
            if (currentRect && (currentRect.width < 5 || currentRect.height < 5)) {
                setCropRect(null);
            }
        };

        window.addEventListener('mousemove', handleGlobalMouseMove);
        window.addEventListener('mouseup', handleGlobalMouseUp);

        return () => {
            window.removeEventListener('mousemove', handleGlobalMouseMove);
            window.removeEventListener('mouseup', handleGlobalMouseUp);
        };
    }, [isDragging, startPos]);

    const downloadImage = async (crop: boolean) => {
        if (!imageUrl) return;

        if (crop && cropRect && imageRef.current && containerRef.current) {
            // Crop Logic
            const canvas = document.createElement('canvas');
            const img = imageRef.current;
            const container = containerRef.current;
            
            // We need to calculate the crop rect relative to the image itself, not the container
            // Since cropRect is relative to container, we adjust it
            const imageRect = img.getBoundingClientRect();
            const containerRect = container.getBoundingClientRect();
            
            const imageLeftInContainer = imageRect.left - containerRect.left;
            const imageTopInContainer = imageRect.top - containerRect.top;

            // Adjust crop coordinates to be relative to the image
            const cropXOnImage = cropRect.x - imageLeftInContainer;
            const cropYOnImage = cropRect.y - imageTopInContainer;

            const scaleX = img.naturalWidth / imageRect.width;
            const scaleY = img.naturalHeight / imageRect.height;

            canvas.width = cropRect.width * scaleX;
            canvas.height = cropRect.height * scaleY;
            
            const ctx = canvas.getContext('2d');
            if (!ctx) return;

            ctx.drawImage(
                img,
                cropXOnImage * scaleX,
                cropYOnImage * scaleY,
                cropRect.width * scaleX,
                cropRect.height * scaleY,
                0,
                0,
                canvas.width,
                canvas.height
            );

            const link = document.createElement('a');
            link.download = `screenshot-crop-${Date.now()}.png`;
            try {
                link.href = canvas.toDataURL('image/png');
                link.click();
            } catch (e) {
                console.error("Crop failed", e);
                alert("Cannot crop this image due to browser security restrictions (CORS).");
            }
        } else {
            // Download Full
            const link = document.createElement('a');
            link.download = `screenshot-${Date.now()}.png`;
            link.href = imageUrl;
            link.click();
        }
        
        onOpenChange(false);
    };

    return (
        <Dialog open={open} onOpenChange={onOpenChange}>
            <DialogContent 
                className="!fixed !top-0 !left-0 !translate-x-0 !translate-y-0 !w-screen !h-screen !max-w-none !p-0 !gap-0 !rounded-none !border-none overflow-hidden bg-zinc-950 flex flex-col z-[100]" 
                portalContainer={container}
                showCloseButton={false}
            >
                <DialogHeader className="p-3 border-b border-zinc-800 bg-zinc-900 shrink-0 flex flex-row items-center gap-4 h-14">
                    <div className="flex items-center gap-4 flex-1 min-w-0">
                        <DialogTitle className="flex items-center gap-2 shrink-0">
                            <CornersIn className="text-primary" size={20} />
                            Save Screenshot
                        </DialogTitle>
                        <DialogDescription className="m-0 truncate pt-0.5">
                            Drag to crop, or save full frame.
                        </DialogDescription>
                    </div>
                    
                    <div className="flex items-center gap-2 shrink-0">
                        {cropRect && (
                            <Button variant="secondary" size="sm" onClick={() => downloadImage(true)} className="h-8">
                                <CornersIn className="mr-2 h-4 w-4" />
                                Save Crop
                            </Button>
                        )}
                        <Button size="sm" onClick={() => downloadImage(false)} className="h-8">
                            <DownloadSimple className="mr-2" size={16} />
                            Save Full
                        </Button>
                        <Button variant="ghost" size="icon-sm" onClick={() => onOpenChange(false)} className="h-8 w-8 ml-2">
                            <X size={18} />
                        </Button>
                    </div>
                </DialogHeader>

                <div className="relative bg-black overflow-hidden flex items-center justify-center flex-1 min-h-0 w-full h-full">
                    {imageUrl && (
                        <div 
                            ref={containerRef}
                            className="relative cursor-crosshair select-none"
                            onMouseDown={handleMouseDown}
                        >
                            <img 
                                ref={imageRef}
                                src={imageUrl} 
                                alt="Screenshot" 
                                className="max-w-full max-h-full object-contain block"
                                draggable={false}
                                crossOrigin="anonymous"
                            />
                            
                            {/* Overlay for non-selected areas */}
                            {cropRect && (
                                <>
                                    <div className="absolute inset-0 bg-black/50 pointer-events-none" 
                                         style={{ 
                                             clipPath: `polygon(0% 0%, 0% 100%, ${cropRect.x}px 100%, ${cropRect.x}px ${cropRect.y}px, ${cropRect.x + cropRect.width}px ${cropRect.y}px, ${cropRect.x + cropRect.width}px ${cropRect.y + cropRect.height}px, ${cropRect.x}px ${cropRect.y + cropRect.height}px, ${cropRect.x}px 100%, 100% 100%, 100% 0%)` 
                                         }} 
                                    />
                                    <div 
                                        className="absolute border-2 border-primary shadow-[0_0_0_1px_rgba(0,0,0,0.5)] pointer-events-none"
                                        style={{
                                            left: cropRect.x,
                                            top: cropRect.y,
                                            width: cropRect.width,
                                            height: cropRect.height
                                        }}
                                    >
                                        {/* Dimensions Label */}
                                        <div className="absolute -top-6 left-0 bg-primary text-primary-foreground text-[10px] px-1.5 py-0.5 rounded font-mono font-medium whitespace-nowrap">
                                            {Math.round(cropRect.width * (imageRef.current?.naturalWidth || 0) / (containerRef.current?.clientWidth || 1))} x {Math.round(cropRect.height * (imageRef.current?.naturalHeight || 0) / (containerRef.current?.clientHeight || 1))}
                                        </div>
                                    </div>
                                </>
                            )}
                        </div>
                    )}
                </div>
            </DialogContent>
        </Dialog>
    );
}

/**
 * ─── ShortcutGuideDialog.tsx ────────────────────────────────────────
 *
 * An interactive keyboard-shortcut reference dialog. Displays all
 * registered keybindings organised by category with a live search
 * filter.
 *
 * Features / Responsibilities:
 *   - Tabbed categories (General, Navigation, Playback, etc.)
 *   - Real-time search filtering across shortcut labels
 *   - Renders user-customised keybinds from the KEYBIND_REGISTRY
 *   - Styled keyboard-key badges for consistent visual presentation
 * ───────────────────────────────────────────────────────────────────
 */
import React, { type ReactNode, useState, useMemo } from "react";
import type { Icon } from "@phosphor-icons/react";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogDescription } from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { CaretRight, CaretLeft, CornersOut, CornersIn, SpeakerHigh, Image, FilmStrip, FileText, House, Folder, Graph, MagnifyingGlass, Gear, HardDrives, Trash, PencilSimple, CaretUp, CheckSquare, X } from "@phosphor-icons/react";
import { ScrollArea } from "@/components/ui/scroll-area";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { useStore } from "@/store/useStore";
import { useShallow } from "@/lib/zustand-shallow";
import { KEYBIND_REGISTRY } from "@/constants/keybinds";
import { formatKey } from "@/lib/utils";

interface ShortcutGuideDialogProps {
    open: boolean;
    onOpenChange: (open: boolean) => void;
}

const Key = ({ children }: { children: ReactNode }) => (
    <span className="inline-flex items-center justify-center min-w-[20px] h-5 px-1.5 text-[10px] font-bold font-mono text-zinc-400 bg-zinc-800 border border-zinc-700 rounded shadow-[0_1px_0_rgba(0,0,0,0.2)] select-none uppercase whitespace-nowrap">
        {children}
    </span>
);

const ShortcutRow = ({ label, keys, icon: Icon }: { label: string, keys: ReactNode[], icon?: Icon }) => (
    <div className="flex items-center justify-between py-2 border-b border-zinc-800/50 last:border-0">
        <div className="flex items-center gap-3">
            {Icon && <Icon className="text-zinc-400" size={16} />}
            <span className="text-sm text-zinc-300">{label}</span>
        </div>
        <div className="flex items-center gap-1">
            {keys.map((k, i) => {
                // Check if this element or the previous one is an "or" separator to avoid adding "+"
                const isSeparator = React.isValidElement(k) && (k.props as Record<string, string>).className?.includes('text-zinc-500');
                const prevWasSeparator = i > 0 && React.isValidElement(keys[i-1]) && (keys[i-1] as React.ReactElement<Record<string, string>>).props?.className?.includes('text-zinc-500');
                
                // If it's the first item, no plus.
                // If this is a separator, no plus.
                // If the previous was a separator, no plus.
                const showPlus = i > 0 && !isSeparator && !prevWasSeparator;

                return (
                    <div key={i} className="flex items-center gap-1">
                        {showPlus && <span className="text-zinc-600 text-xs">+</span>}
                        {k}
                    </div>
                );
            })}
        </div>
    </div>
);

// Helper to render dynamic row based on IDs
const DynamicShortcutRow = ({ ids, label, icon: Icon, customKeys, extraKeys }: { ids?: string[], label?: string, icon?: Icon, customKeys?: ReactNode[], extraKeys?: ReactNode[] }) => {
    const { customKeybinds } = useStore(useShallow((state) => ({
        customKeybinds: state.customKeybinds,
    })));

    if (customKeys) {
        return <ShortcutRow label={label!} icon={Icon} keys={customKeys} />;
    }

    if (!ids || ids.length === 0) return null;

    // Use the first ID's definition for label/icon if not provided
    const primaryDef = KEYBIND_REGISTRY[ids[0]];
    if (!primaryDef) return null;

    const rowLabel = label || primaryDef.label;
    const RowIcon = Icon || primaryDef.icon;

    const keysToRender: ReactNode[] = [];
    
    ids.forEach((id, index) => {
        const def = KEYBIND_REGISTRY[id];
        if (!def) return;
        
        const keyStr = customKeybinds[id] || def.defaultKey;
        
        if (index > 0) {
            keysToRender.push(<span key={`sep-${index}`} className="text-xs text-zinc-500 mx-1">or</span>);
        }
        
        const parts = keyStr.includes(' ') ? keyStr.split(' ') : keyStr.split('+');
        
        parts.forEach((part, pIndex) => {
             keysToRender.push(<Key key={`${id}-${pIndex}`}>{formatKey(part)}</Key>);
        });
    });

    if (extraKeys) {
        keysToRender.push(<span key="sep-extra" className="text-xs text-zinc-500 mx-1">or</span>);
        keysToRender.push(...extraKeys);
    }

    return <ShortcutRow label={rowLabel} icon={RowIcon} keys={keysToRender} />;
}

// Data Definition
type GuideItem = 
    | { type: 'dynamic', ids: string[], label?: string, extraKeys?: ReactNode[] }
    | { type: 'header', label: string }
    | { type: 'custom', label: string, icon: Icon, keys: ReactNode[] };

