                                        className={cn("flex items-center text-[10px] font-bold text-muted-foreground uppercase tracking-wider hover:text-foreground transition-colors w-full text-left relative", isSlim && "justify-center")}
                                    >
                                        <CaretDown weight="bold" className={cn("transition-transform text-xs mr-1", !projectsOpen && "-rotate-90")} />
                                        {!isSlim && <span>Project</span>}
                                        <div className="flex-grow border-t border-border/40 ml-1"></div>
                                    </button>
                                    
                                    <AnimatePresence initial={false}>
                                        {projectsOpen && (
                                            <motion.div
                                                initial={{ height: 0, opacity: 0 }}
                                                animate={{ height: "auto", opacity: 1 }}
                                                exit={{ height: 0, opacity: 0 }}
                                                className="overflow-hidden"
                                            >
                                                <div className={cn("flex gap-1 items-center pt-1", isSlim && "flex-col")}>
                                                    {projects.length > 0 ? (
                                                        <>
                                                            <Select value={activeProjectId || ""} onValueChange={handleProjectChange}>
                                                                <SelectTrigger className={cn("flex-1 h-8 bg-card border-border/60 shadow-sm group [&_svg]:text-muted-foreground [&_svg]:group-hover:text-foreground [&_svg]:transition-colors truncate max-w-full", isSlim && "px-1 justify-center")}> 
                                                                    {isSlim ? <FolderOpen weight="bold" className="text-muted-foreground group-hover:text-foreground transition-colors" /> : <span className="truncate block max-w-full"><SelectValue placeholder="Select Project" /></span>} 
                                                                </SelectTrigger>
                                                                <SelectContent>
                                                                    {projects.map((p: Project) => (
                                                                        <SelectItem key={p.id} value={p.id}>
                                                                            <span className="truncate block max-w-[220px]">{p.name}</span>
                                                                        </SelectItem>
                                                                    ))}
                                                                    <Separator className="my-1" />
                                                                    <SelectItem value="new"><span className="text-primary flex items-center gap-2"><Plus className="size-3" /> New Project</span></SelectItem>
                                                                </SelectContent>
                                                            </Select>

                                                            <Button 
                                                                variant="outline" 
                                                                size="icon" 
                                                                className="h-8 w-8 shrink-0 bg-card border-border/60 group"
                                                                onClick={() => {
                                                                    playSfx('cursor');
                                                                    handleEditProjectName();
                                                                }}
                                                                title="Edit Project Name"
                                                            >
                                                                <PencilSimple className="text-muted-foreground group-hover:text-foreground transition-colors" />
                                                            </Button>

                                                            <DropdownMenu>
                                                                <DropdownMenuTrigger asChild>
                                                                    <Button variant="outline" size="icon" className="h-8 w-8 shrink-0 bg-card border-border/60 group" title="Share">
                                                                        <Share className="text-muted-foreground group-hover:text-foreground transition-colors" />
                                                                    </Button>
                                                                </DropdownMenuTrigger>
                                                                <DropdownMenuContent align="end" className="w-auto min-w-40">
                                                                    <DropdownMenuItem onClick={handleExportProject} disabled={!activeProjectId} className="whitespace-nowrap">
                                                                        <UploadSimple className="mr-2" /> Export Project
                                                                    </DropdownMenuItem>
                                                                    <DropdownMenuItem onClick={handleImportProject} className="whitespace-nowrap">
                                                                        <DownloadSimple className="mr-2" /> Import Project
                                                                    </DropdownMenuItem>
                                                                </DropdownMenuContent>
                                                            </DropdownMenu>
                                                        </>
                                                    ) : (
                                                        <div className={cn("flex gap-1 items-center w-full", isSlim && "flex-col")}>
                                                            <Button 
                                                                variant="outline" 
                                                                className={cn("flex-1 h-8 bg-card border-border/60 shadow-sm text-[10px] text-muted-foreground uppercase tracking-wider", isSlim && "px-0 w-8 flex-none justify-center")}
                                                                onClick={() => {
                                                                    playSfx('cursor');
                                                                    setNewProjectOpen(true);
                                                                }}
                                                            >
                                                                {isSlim ? <Plus weight="bold" /> : "Create Project"}
                                                            </Button>
                                                            {!isSlim && (
                                                                <Button 
                                                                    variant="outline" 
                                                                    size="icon"
                                                                    className="h-8 w-8 shrink-0 bg-card border-border/60 shadow-sm group"
                                                                    onClick={() => {
                                                                        playSfx('cursor');
                                                                        const p1: Project = { id: crypto.randomUUID(), name: 'Demo Project', created: Date.now(), lastModified: Date.now() };
                                                                        const s1: Storage = { id: crypto.randomUUID(), projectId: p1.id, name: 'Main Storage', created: Date.now(), lastModified: Date.now() };
                                                                        const f1: AppFile = { id: crypto.randomUUID(), projectId: p1.id, storageId: s1.id, parentId: null, name: 'Getting Started.mp4', url: 'https://test-videos.co.uk/vids/bigbuckbunny/mp4/h264/720/Big_Buck_Bunny_720_10s_1MB.mp4', type: 'video', order: 0, created: Date.now(), lastModified: Date.now() };
                                                                        useStore.setState((state) => ({ 
                                                                            projects: [...state.projects, p1], 
                                                                            storages: [...state.storages, s1], 
                                                                            files: [...state.files, f1], 
                                                                            activeProjectId: p1.id, 
                                                                            activeStorageId: s1.id 
                                                                        }));
                                                                    }}
                                                                    title="Load Demo"
                                                                >
                                                                    <Sparkle weight="bold" className="size-4 text-primary group-hover:scale-110 transition-transform" />
                                                                </Button>
                                                            )}
                                                            {!isSlim && (
                                                                <Button 
                                                                    variant="outline" 
                                                                    size="icon"
                                                                    className="h-8 w-8 shrink-0 bg-card border-border/60 shadow-sm group"
                                                                    onClick={() => {
                                                                        playSfx('cursor');
                                                                        handleImportProject();
                                                                    }}
                                                                    title="Import Project"
                                                                >
                                                                    <DownloadSimple weight="bold" className="size-4 text-muted-foreground group-hover:text-foreground transition-colors" />
                                                                </Button>
                                                            )}
                                                        </div>
                                                    )}
                                                </div>

                                    {importStatus && (
                                        <div
                                            className={cn(
                                                "mt-2 text-[11px] px-2 py-1 rounded-none border",
                                                importStatus.type === "success"
                                                    ? "bg-emerald-500/10 border-emerald-700/60 text-emerald-300"
                                                    : "bg-red-500/10 border-red-700/60 text-red-300"
                                            )}
                                        >
                                            <div className="flex items-center justify-between gap-2">
                                                <span className="truncate">{importStatus.message}</span>
                                                <button
                                                    onClick={() => {
                                                        playSfx('cursor');
                                                        setImportStatus(null);
                                                    }}
                                                    className="text-xs text-zinc-400 hover:text-zinc-200"
                                                >
                                                    ×
                                                </button>
                                            </div>
                                        </div>
                                    )}
                                            </motion.div>
                                        )}
                                    </AnimatePresence>
                                </div>
                            )}

                            {/* Scrollable Content */}
                            <ScrollArea className="flex-1 px-3 py-2">
                                {/* Assets Section */}
                                <div className="mb-2">
                                    {!isSidebarCollapsed && (
                                        <div className="flex items-center">
                                            <button
                                                onClick={() => {
                                                    playSfx('cursor');
                                                    setAssetsOpen(!assetsOpen);
                                                }}
                                                className="flex items-center text-[10px] font-bold text-muted-foreground uppercase tracking-wider hover:text-foreground transition-colors w-full text-left relative"
                                            >
                                                <CaretDown weight="bold" className={cn("transition-transform text-xs mr-1", !assetsOpen && "-rotate-90")} />
                                                <span>Assets</span>
                                                <div className="flex-grow border-t border-border/40 ml-1"></div>
                                            </button>
                                        </div>
                                    )}
                                    
                                    <AnimatePresence initial={false}>
                                        {(assetsOpen || isSidebarCollapsed || isSlim) && (
                                            <motion.div
                                                initial={!isSidebarCollapsed ? { height: 0, opacity: 0 } : undefined}
                                                animate={!isSidebarCollapsed ? { height: "auto", opacity: 1 } : undefined}
                                                exit={!isSidebarCollapsed ? { height: 0, opacity: 0 } : undefined}
                                                className={cn("flex gap-1 overflow-hidden mt-1", (isSidebarCollapsed || isSlim) ? "flex-col space-y-2" : "flex-row")}
                                            >
                                                <ContextMenu>
                                                    <ContextMenuTrigger className={cn("flex-1", (isSidebarCollapsed || isSlim) && "w-full flex justify-center")}>
                                                        <button
                                                            onClick={() => {
                                                                playSfx('cursor');
                                                                if (isSidebarCollapsed) {
                                                                    toggleSidebarCollapse && toggleSidebarCollapse();
                                                                    return;
                                                                }
                                                                if (location.pathname === '/storage') {
                                                                    setSidebarView('storage');
                                                                } else {
                                                                    navigate('/storage');
                                                                    setSidebarView('main');
                                                                }
                                                            }}
                                                            className={cn(
                                                                "flex items-center justify-center rounded-none transition-all duration-200 group relative cursor-pointer px-2 w-full border border-border/60 shadow-sm",
                                                                (isSidebarCollapsed || isSlim)
                                                                    ? "w-10 h-10 mx-auto"
                                                                    : "h-9",
                                                                (location.pathname === "/storage")
                                                                    ? "bg-primary/20 text-primary border-primary/30"
                                                                    : "bg-secondary/40 text-muted-foreground hover:bg-secondary/60 hover:text-foreground"
                                                            )}
                                                        >
                                                            <HardDrives
                                                                weight={(location.pathname === "/storage") ? "fill" : "regular"}
                                                                size={18}
                                                                className="transition-transform group-hover:scale-110"
                                                            />
                                                            {!isSidebarCollapsed && !isSlim && (
                                                                <span className="ml-2 text-xs font-medium tracking-tight">
                                                                    Storage
                                                                </span>
                                                            )}
                                                        </button>
                                                    </ContextMenuTrigger>
                                                    <ContextMenuContent side="bottom" align="start" sideOffset={4} className="min-w-[8rem]">
                                                        {createMenuContent}
                                                    </ContextMenuContent>
                                                </ContextMenu>

                                                <ContextMenu>
                                                    <ContextMenuTrigger className={cn("flex-1", (isSidebarCollapsed || isSlim) && "w-full flex justify-center")}>
                                                        <button
                                                            onClick={() => {
                                                                playSfx('cursor');
                                                                if (isSidebarCollapsed) {
                                                                    toggleSidebarCollapse && toggleSidebarCollapse();
                                                                    return;
                                                                }
                                                                if (location.pathname.startsWith('/docs')) {
                                                                    setSidebarView('docs');
                                                                } else {
                                                                    navigate('/docs');
                                                                    setSidebarView('main');
                                                                }
                                                            }}
                                                            className={cn(
                                                                "flex items-center justify-center rounded-none transition-all duration-200 group relative cursor-pointer px-2 w-full border border-border/60 shadow-sm",
                                                                (isSidebarCollapsed || isSlim)
                                                                    ? "w-10 h-10 mx-auto"
                                                                    : "h-9",
                                                                location.pathname.startsWith("/docs")
                                                                    ? "bg-primary/20 text-primary border-primary/30"
                                                                    : "bg-secondary/40 text-muted-foreground hover:bg-secondary/60 hover:text-foreground"
                                                            )}
                                                        >
                                                            <NotePencil
                                                                weight={location.pathname.startsWith("/docs") ? "fill" : "regular"}
                                                                size={18}
                                                                className="transition-transform group-hover:scale-110"
                                                            />
                                                            {!isSidebarCollapsed && !isSlim && (
                                                                <span className="ml-2 text-xs font-medium tracking-tight">
                                                                    Docs
                                                                </span>
                                                            )}
                                                        </button>
                                                    </ContextMenuTrigger>
                                                    <ContextMenuContent side="bottom" align="start" sideOffset={4} className="min-w-[8rem]">
                                                        {createMenuContent}
                                                    </ContextMenuContent>
                                                </ContextMenu>

                                                <ContextMenu>
                                                    <ContextMenuTrigger className={cn("flex-1", (isSidebarCollapsed || isSlim) && "w-full flex justify-center")}>
                                                        <button
                                                            onClick={() => {
                                                                playSfx('cursor');
                                                                if (isSidebarCollapsed) {
                                                                    toggleSidebarCollapse && toggleSidebarCollapse();
                                                                    return;
                                                                }
                                                                if (location.pathname.startsWith('/graphs')) {
                                                                    setSidebarView('graphs');
                                                                } else {
                                                                    navigate('/graphs');
                                                                    setSidebarView('main');
                                                                }
                                                            }}
                                                            className={cn(
                                                                "flex items-center justify-center rounded-none transition-all duration-200 group relative cursor-pointer px-2 w-full border border-border/60 shadow-sm",
                                                                (isSidebarCollapsed || isSlim)
                                                                    ? "w-10 h-10 mx-auto"
                                                                    : "h-9",
                                                                location.pathname.startsWith("/graphs")
                                                                    ? "bg-primary/20 text-primary border-primary/30"
                                                                    : "bg-secondary/40 text-muted-foreground hover:bg-secondary/60 hover:text-foreground"
                                                            )}
                                                        >
                                                            <Graph
                                                                weight={location.pathname.startsWith("/graphs") ? "fill" : "regular"}
                                                                size={18}
                                                                className="transition-transform group-hover:scale-110"
                                                            />
                                                            {!isSidebarCollapsed && !isSlim && (
                                                                <span className="ml-2 text-xs font-medium tracking-tight">
                                                                    Graphs
                                                                </span>
                                                            )}
                                                        </button>
                                                    </ContextMenuTrigger>
                                                    <ContextMenuContent side="bottom" align="start" sideOffset={4} className="min-w-[8rem]">
                                                        {createMenuContent}
                                                    </ContextMenuContent>
                                                </ContextMenu>
                                            </motion.div>
                                        )}
                                    </AnimatePresence>
                                </div>


                                <button
                                    onClick={() => {
                                        playSfx('cursor');
                                        setCollectionsSectionOpen(!collectionsSectionOpen);
                                    }}
                                    className="flex items-center text-[10px] font-bold text-muted-foreground uppercase tracking-wider hover:text-foreground transition-colors w-full text-left my-1 relative"
                                >
                                    <div className={cn(
                                        "transition-transform duration-200 mr-1",
                                        !collectionsSectionOpen ? "-rotate-90" : "rotate-0"
                                    )}>
                                        <CaretDown weight="bold" className="text-xs transition-colors" />
                                    </div>
                                    <span className="text-[10px] font-bold uppercase tracking-wider transition-colors">
                                        Collections
                                    </span>
                                    <div className="flex-grow border-t border-border/40 ml-1"></div>
                                </button>

                                {/* Collections Section */}
                                <div className="mb-4 mt-1">
                                    <AnimatePresence initial={false}>
                                        {collectionsSectionOpen && (
                                            <motion.div
                                                initial={{ height: 0, opacity: 0 }}
                                                animate={{ height: "auto", opacity: 1 }}
                                                exit={{ height: 0, opacity: 0 }}
                                                transition={{ duration: 0.2, ease: "easeInOut" }}
                                                className="overflow-hidden"
                                            >
                                                <DndContext
                                        sensors={sensors}
                                        collisionDetection={(args) => {
                                            // 1. Check for all Folder Nesting targets (including root)
                                            // We use rectIntersection to make them easier targets than individual sortable items
                                            const folderCollisions = rectIntersection({
                                                ...args,
                                                droppableContainers: args.droppableContainers.filter(c => 
                                                    c.id.toString().startsWith("folder-nest-")
                                                )
                                            });
                                            if (folderCollisions.length > 0) return folderCollisions;

                                            // 2. Fallback to pointer for sortable reordering
                                            const pointerCollisions = pointerWithin(args);
                                            if (pointerCollisions.length > 0) return pointerCollisions;
                                            
                                            return closestCenter(args);
                                        }}
                                        onDragStart={handleDragStart}
                                        onDragEnd={handleDragEnd}
                                        onDragCancel={handleDragCancel}
                                    >
                                        <SidebarFolderItem
                                             isRoot
                                             folder={{ 
                                                 id: activeCollectionId || 'root',
                                                 name: activeCollection ? activeCollection.name : "Collections" 
                                             }}
                                             isSlim={isSlim}
                                             isCollapsed={!rootCollectionsOpen}
                                             onToggleCollapse={() => {
                                                  setRootCollectionsOpen(!rootCollectionsOpen);
                                              }}
                                             collapsedById={folderCollapsedById}
                                             setCollapsedById={setFolderCollapsedById}
                                             handleAddCollection={handleAddCollection}
                                             handleAddFolder={handleAddFolder}
                                             currentFolderId={currentFolderId}
                                          >
                                              <div className="space-y-0.5">
                                                  {!activeCollectionId ? (
                                                      <div className="px-3 py-4 text-center">
                                                          <p className="text-[10px] text-muted-foreground mb-2 uppercase tracking-tighter">No bucket selected</p>
                                                          <Button 
                                                              variant="outline" 
                                                              size="sm" 
                                                              className="h-7 text-[10px] w-full rounded-none border-border/60 bg-secondary/20"
                                                              onClick={() => setSidebarView('collections')}
                                                          >
                                                              Open Buckets
                                                          </Button>
                                                      </div>
                                                  ) : (() => {
                                                      const renderCollectionTree = (parentId: string | null = null, depth = 0) => {
                                                            const items = collections
                                                                .filter(c => c.projectId === activeProjectId && !c.deleted && c.parentId === parentId)
                                                                .sort((a, b) => (a.order || 0) - (b.order || 0));

                                                            const itemIds = items.map(c => c.id);

                                                            return (
                                                                <SortableContext 
                                                                    items={itemIds} 
                                                                    strategy={verticalListSortingStrategy}
                                                                >
                                                                    {items.map(item => {
                                                                        if (item.type === 'folder') {
                                                                            return (
                                                                                <SidebarFolderItem
                                                                                    key={item.id}
                                                                                    folder={item}
                                                                                    isSlim={isSlim}
                                                                                    depth={depth}
                                                                                    folders={projectCollections.filter(f => f.type === 'folder' && f.id !== item.id)}
                                                                                    handleAddCollection={handleAddCollection}
                                                                                    handleAddFolder={handleAddFolder}
                                                                                    collapsedById={folderCollapsedById}
                                                                                    setCollapsedById={setFolderCollapsedById}
                                                                                    currentFolderId={currentFolderId}
                                                                                    onRename={() => {
                                                                                        setCollectionToEdit(item);
                                                                                        setEditCollectionOpen(true);
                                                                                    }}
                                                                                    onDelete={() => trashCollection(item.id)}
                                                                                    onColorChange={(color: string) => {
                                                                                        updateCollection(item.id, { color, lastModified: Date.now() });
                                                                                    }}
                                                                                    onIconChange={(icon: string) => {
                                                                                        updateCollection(item.id, { icon, lastModified: Date.now() });
                                                                                    }}
                                                                                    onMoveDialog={() => {
                                                                                        setCollectionToMove(item);
                                                                                        setMoveCollectionDialogOpen(true);
                                                                                    }}
                                                                                    onMove={(newParentId: string | null) => {
                                                                                        useStore.setState((state) => ({
                                                                                            collections: state.collections.map((c: Collection) => 
                                                                                                c.id === item.id ? { ...c, parentId: newParentId, lastModified: Date.now() } : c
                                                                                            )
                                                                                        }));
                                                                                    }}
                                                                                >
                                                                                    {renderCollectionTree(item.id, depth + 1)}
                                                                                </SidebarFolderItem>
                                                                            );
                                                                        }
                                                                        return (
                                                                            <SortableCollectionItem
                                                                                key={item.id}
                                                                                collection={item}
                                                                                location={location}
                                                                                isSlim={isSlim}
                                                                                handleSelectCollection={handleSelectCollection}
                                                                                handleEditCollectionClick={handleEditCollectionClick}
                                                                                handleDeleteCollection={handleDeleteCollection}
                                                                                setCollectionToEdit={setCollectionToEdit}
                                                                                setEditCollectionOpen={setEditCollectionOpen}
                                                                                trashCollection={trashCollection}
                                                                                createMenuContent={createMenuContent}
                                                                                currentFolderId={currentFolderId}
                                                                                onMove={(c) => { setCollectionToMove(c); setMoveCollectionDialogOpen(true); }}
                                                                            />
                                                                        );
                                                                    })}
                                                                </SortableContext>
                                                            );
                                                        };
                                                        return renderCollectionTree(activeCollectionId);
                                                  })()}
                                              </div>
                                              {activeCollectionId && collections.filter((c: Collection) => c.projectId === activeProjectId && !c.deleted && c.parentId === activeCollectionId).length === 0 && (
                                                  <div className={cn("px-3 py-4 text-xs text-muted-foreground/60 italic text-center border-2 border-dashed border-border/30 rounded-md", isSlim && "px-1 text-[10px]")}>
                                                      {isSlim ? "Empty" : "Bucket is empty"}
                                                  </div>
                                              )}
                                          </SidebarFolderItem>
                                        <DragOverlay dropAnimation={null}>
                                            {activeDragId ? (() => {
                                                const item = collections.find(c => c.id === activeDragId);
                                                if (!item) return null;
                                                const Icon = getIcon(item.icon);
                                                return (
                                                     <div className="flex items-center gap-3 px-3 py-2 rounded-md text-sm bg-zinc-900 border border-zinc-800 shadow-xl opacity-90 w-48 pointer-events-none">
                                                        <Icon className="text-lg shrink-0" weight="fill" style={{ color: item.color }} />
                                                        <span className="truncate font-medium">{item.name}</span>
                                                     </div>
                                                );
                                            })() : null}
                                        </DragOverlay>
                                    </DndContext>
                                             </motion.div>
                                         )}
                                     </AnimatePresence>
                                </div>
                            </ScrollArea>
                        </motion.div>
                    ) : sidebarView === 'docs' ? (
                        <motion.div
                            key="docs"
                            initial={{ x: 20, opacity: 0 }}
                            animate={{ x: 0, opacity: 1 }}
                            exit={{ x: 20, opacity: 0 }}
                            transition={{ duration: 0.2 }}
                            className="flex-1 flex flex-col min-h-0"
                        >
                            <div className="px-3 py-2 border-b border-border/40 bg-card/20 shrink-0">
                                <div className="flex items-center gap-2">
                                    <button
                                        onClick={() => {
                                            playSfx('cursor');
                                            setSidebarView('main');
                                        }}
                                        className="h-6 w-6 flex items-center justify-center rounded-none border border-border/60 shadow-sm bg-secondary/40 text-muted-foreground hover:bg-secondary/60 hover:text-foreground transition-all duration-200"
                                        title="Back to sidebar"
                                    >
                                        <CaretLeft weight="bold" size={14} />
                                    </button>
                                    <div className="flex-1 flex items-center justify-center gap-2 text-sm font-semibold text-foreground">
                                        <NotePencil weight="bold" />
                                        Documents
                                    </div>
                                    <button
                                        onClick={() => {
                                            playSfx('cursor');
                                            handleCreateDoc();
                                        }}
                                        className="h-6 w-6 flex items-center justify-center rounded-none border border-border/60 shadow-sm bg-secondary/40 text-muted-foreground hover:bg-secondary/60 hover:text-foreground transition-all duration-200"
                                        title="New document"
                                    >
                                        <Plus weight="bold" size={14} />
                                    </button>
                                </div>
                            </div>
                            
                            <ScrollArea className="flex-1 px-3 py-2">
                                <div className="space-y-1">
                                    <DndContext sensors={sensors} collisionDetection={closestCenter} onDragEnd={handleDragEnd}>
                                        <SortableContext items={projectDocs.map((d: Doc) => d.id)} strategy={verticalListSortingStrategy}>
                                            {projectDocs.map((doc: Doc) => (
                                                <SortableEntityItem 
                                                    key={doc.id}
                                                    entity={doc}
                                                    isActive={activeDocId === doc.id}
                                                    onSelect={() => handleSelectDoc(doc.id)}
                                                    onEdit={(e) => handleRenameDoc(e, doc)}
                                                    onDelete={(e) => handleDeleteDoc(e, doc.id)}
                                                    dataAttrs={{ 'data-doc-id': doc.id }}
                                                />
                                            ))}
                                        </SortableContext>
                                    </DndContext>

                                    {projectDocs.length === 0 && (
                                        <div className="p-4 text-center text-xs text-muted-foreground/60 italic border-2 border-dashed border-border/30 rounded-md m-2">
                                            No documents yet
                                        </div>
                                    )}
                                </div>
                            </ScrollArea>
                        </motion.div>
                    ) : sidebarView === 'graphs' ? (
                        <motion.div
                            key="graphs"
                            initial={{ x: 20, opacity: 0 }}
                            animate={{ x: 0, opacity: 1 }}
                            exit={{ x: 20, opacity: 0 }}
                            transition={{ duration: 0.2 }}
                            className="flex-1 flex flex-col min-h-0"
                        >
                            <div className="px-3 py-2 border-b border-border/40 bg-card/20 shrink-0">
                                <div className="flex items-center gap-2">
                                    <button
                                        onClick={() => setSidebarView('main')}
                                        className="h-6 w-6 flex items-center justify-center rounded-none border border-border/60 shadow-sm bg-secondary/40 text-muted-foreground hover:bg-secondary/60 hover:text-foreground transition-all duration-200"
                                        title="Back to sidebar"
                                    >
                                        <CaretLeft weight="bold" size={14} />
                                    </button>
                                    <div className="flex-1 flex items-center justify-center gap-2 text-sm font-semibold text-foreground">
                                        <Graph weight="bold" />
                                        Graphs
                                    </div>
                                    <button onClick={handleCreateGraph} className="h-6 w-6 flex items-center justify-center rounded-none border border-border/60 shadow-sm bg-secondary/40 text-muted-foreground hover:bg-secondary/60 hover:text-foreground transition-all duration-200" title="New graph">
                                        <Plus weight="bold" size={14} />
                                    </button>
                                </div>
                            </div>
                            
                            <ScrollArea className="flex-1 px-3 py-2">
                                <div className="space-y-1">
                                    <DndContext sensors={sensors} collisionDetection={closestCenter} onDragEnd={handleDragEnd}>
                                        <SortableContext items={projectGraphs.map((g: GraphType) => g.id)} strategy={verticalListSortingStrategy}>
                                            {projectGraphs.map((graph: GraphType) => (
                                                <SortableEntityItem
                                                    key={graph.id}
                                                    entity={graph}
                                                    isActive={activeGraphId === graph.id}
                                                    onSelect={() => handleSelectGraph(graph.id)}
                                                    onEdit={(e) => handleEditGraph(e, graph)}
                                                    onDelete={(e) => handleDeleteGraph(e, graph.id)}
                                                />
                                            ))}
                                        </SortableContext>
                                    </DndContext>

                                    {projectGraphs.length === 0 && (
                                        <div className="p-4 text-center text-xs text-muted-foreground/60 italic border-2 border-dashed border-border/30 rounded-md m-2">
                                            No graphs yet
                                        </div>
                                    )}
                                </div>
                            </ScrollArea>
                        </motion.div>
                    ) : sidebarView === 'history' ? (
                        <motion.div
                            key="history"
                            initial={{ x: 20, opacity: 0 }}
                            animate={{ x: 0, opacity: 1 }}
                            exit={{ x: 20, opacity: 0 }}
                            transition={{ duration: 0.2 }}
                            className="flex-1 flex flex-col min-h-0"
                        >
                            <SidebarHistory onBack={() => setSidebarView('main')} />
                        </motion.div>
                    ) : sidebarView === 'trash' ? (
                        <motion.div
                            key="trash"
                            initial={{ x: 20, opacity: 0 }}
                            animate={{ x: 0, opacity: 1 }}
                            exit={{ x: 20, opacity: 0 }}
                            transition={{ duration: 0.2 }}
                            className="flex-1 flex flex-col min-h-0"
                        >
                            <SidebarTrash onBack={() => setSidebarView('main')} />
                        </motion.div>
                    ) : sidebarView === 'sync' ? (
                        <motion.div
                            key="sync"
                            initial={{ x: 20, opacity: 0 }}
                            animate={{ x: 0, opacity: 1 }}
                            exit={{ x: 20, opacity: 0 }}
                            transition={{ duration: 0.2 }}
                            className="flex-1 flex flex-col min-h-0"
                        >
                            <SidebarSync onBack={() => setSidebarView('main')} />
                        </motion.div>
                    ) : sidebarView === 'collections' ? (
                        <motion.div
                            key="collections"
                            initial={{ x: 20, opacity: 0 }}
                            animate={{ x: 0, opacity: 1 }}
                            exit={{ x: 20, opacity: 0 }}
                            transition={{ duration: 0.2 }}
                            className="flex-1 flex flex-col min-h-0"
                        >
                            <div className="px-3 py-2 border-b border-border/40 bg-card/20 shrink-0">
                                <div className="flex items-center gap-2">
                                    <button
                                        onClick={() => {
                                            playSfx('cursor');
                                            setSidebarView('main');
                                        }}
                                        className="h-6 w-6 flex items-center justify-center rounded-none border border-border/60 shadow-sm bg-secondary/40 text-muted-foreground hover:bg-secondary/60 hover:text-foreground transition-all duration-200"
                                        title="Back to sidebar"
                                    >
                                        <CaretLeft weight="bold" size={14} />
                                    </button>
                                    <div className="flex-1 flex items-center justify-center gap-2 text-sm font-semibold text-foreground">
                                        <Folder weight="bold" />
                                        Buckets
                                    </div>
                                    <button 
                                        onClick={() => { 
                                            playSfx('cursor'); 
                                            handleCreateBucket();
                                        }} 
                                        className="h-6 w-6 flex items-center justify-center rounded-none border border-border/60 shadow-sm bg-secondary/40 text-muted-foreground hover:bg-secondary/60 hover:text-foreground transition-all duration-200"
                                        title="New bucket"
                                    >
                                        <Plus weight="bold" size={14} />
                                    </button>
                                </div>
                            </div>
                            
                            <ScrollArea className="flex-1 px-3 py-2">
                                <div className="space-y-1">
                                    <DndContext sensors={sensors} collisionDetection={closestCenter} onDragEnd={handleDragEnd}>
                                        <SortableContext items={projectBuckets.map((c: Collection) => c.id)} strategy={verticalListSortingStrategy}>
                                            {projectBuckets
                                                .sort((a, b) => (a.order || 0) - (b.order || 0))
                                                .map((collection: Collection) => (
                                                    <SortableCollectionItem
                                                        key={collection.id}
                                                        collection={collection}
                                                        location={location}
                                                        isSlim={false}
                                                        handleSelectCollection={(id: string) => {
                                                            handleSelectCollection(id);
                                                            setSidebarView('main');
                                                        }}
                                                        handleEditCollectionClick={handleEditCollectionClick}
                                                        handleDeleteCollection={handleDeleteCollection}
                                                        setCollectionToEdit={setCollectionToEdit}
                                                        setEditCollectionOpen={setEditCollectionOpen}
                                                        trashCollection={trashCollection}
                                                        createMenuContent={createMenuContent}
                                                        currentFolderId={currentFolderId}
                                                        onMove={(c) => { setCollectionToMove(c); setMoveCollectionDialogOpen(true); }}
                                                    />
                                                ))}
                                        </SortableContext>
                                    </DndContext>

                                    {projectBuckets.length === 0 && (
                                        <ViewEmptyState
                                            icon={Folder}
                                            title="Select or create a bucket"
                                            description="Create a bucket to start organizing collection roots."
                                            actionLabel="Create Bucket"
                                            onAction={handleCreateBucket}
                                            compact
                                        />
                                    )}
                                </div>
                            </ScrollArea>
                        </motion.div>
                    ) : (
                        <motion.div
                            key="storage"
                            initial={{ x: 20, opacity: 0 }}
                            animate={{ x: 0, opacity: 1 }}
                            exit={{ x: 20, opacity: 0 }}
                            transition={{ duration: 0.2 }}
                            className="flex-1 flex flex-col min-h-0"
                        >
                            <div className="px-3 py-2 border-b border-border/40 bg-card/20 shrink-0">
                                <div className="flex items-center gap-2">
                                    <button
                                        onClick={() => {
                                            playSfx('cursor');
                                            setSidebarView('main');
                                        }}
                                        data-sound-back
                                        className="h-6 w-6 flex items-center justify-center rounded-none border border-border/60 shadow-sm bg-secondary/40 text-muted-foreground hover:bg-secondary/60 hover:text-foreground transition-all duration-200"
                                        title="Back to sidebar"
                                    >
                                        <CaretLeft weight="bold" size={14} />
                                    </button>
                                    <div className="flex-1 flex items-center justify-center gap-2 text-sm font-semibold text-foreground">
                                        <HardDrives weight="bold" />
                                        Storages
                                    </div>
                                    <button
                                        onClick={() => {
                                            playSfx('cursor');
                                            handleCreateStorage();
                                        }}
                                        className="h-6 w-6 flex items-center justify-center rounded-none border border-border/60 shadow-sm bg-secondary/40 text-muted-foreground hover:bg-secondary/60 hover:text-foreground transition-all duration-200"
                                        title="New storage"
                                    >
                                        <Plus weight="bold" size={14} />
                                    </button>
                                </div>
                            </div>

                            <ScrollArea className="flex-1 px-3 py-2">
                                <div className="space-y-1">
                                    <DndContext sensors={sensors} collisionDetection={closestCenter} onDragEnd={handleDragEnd}>
                                        <SortableContext items={projectStorages.map((s: Storage) => s.id)} strategy={verticalListSortingStrategy}>
                                            {projectStorages.map((storage: Storage) => (
                                                <SortableEntityItem
                                                    key={storage.id}
                                                    entity={storage}
                                                    isActive={activeStorageId === storage.id}
                                                    onSelect={() => handleSelectStorage(storage.id)}
                                                    onEdit={(e) => handleEditStorageClick(e, storage)}
                                                    onDelete={(e) => handleDeleteStorage(e, storage.id)}
                                                />
                                            ))}
                                        </SortableContext>
                                    </DndContext>

                                    {projectStorages.length === 0 && (
                                        <div
                                            className={cn(
                                                "text-muted-foreground/60 italic border-2 border-dashed border-border/30 rounded-md m-2 flex items-center justify-center",
                                                isSlim ? "p-2 h-10" : "p-4 text-center text-xs"
                                            )}
                                        >
                                            {isSlim ? <HardDrives className="opacity-50" /> : "No storages created yet"}
                                        </div>
                                    )}
                                </div>
                            </ScrollArea>
                        </motion.div>
                    )}
                </AnimatePresence>

                {/* Footer / PiP Placeholder */}
                <div className="px-3 py-2 border-t border-border/40 bg-card/30 shrink-0">
                    {isPipOpen && pipFileId ? (
                        <PiPPlayer isCollapsed={isSidebarCollapsed} />
                    ) : (
                        <div className="flex items-center gap-1 w-full">
                            <button
                                onClick={() => {
                                    playSfx('cursor');
                                    setSidebarView('sync');
                                }}
                                className="flex-1 min-w-0 h-8 flex items-center gap-2 px-2 rounded-none border border-border/60 shadow-sm bg-secondary/40 text-muted-foreground hover:bg-secondary/60 hover:text-foreground transition-all duration-200"
                            >
                                <ArrowsClockwise weight="bold" size={16} className={cn("shrink-0", syncStatus === 'syncing' && "animate-spin text-primary")} />
                                <span className="text-[10px] font-medium truncate">
                                    {syncStatus === 'syncing' ? 'Syncing...' :
                                     syncStatus === 'error' ? 'Sync error' :
                                     lastSyncTime ? formatDistanceToNow(lastSyncTime, { addSuffix: true }) :
                                     'Not synced'}
                                </span>
                            </button>
                            <button
                                onClick={() => {
                                    playSfx('cursor');
                                    setSidebarView('history');
                                }}
                                className="h-8 w-8 flex items-center justify-center rounded-none border border-border/60 shadow-sm bg-secondary/40 text-muted-foreground hover:bg-secondary/60 hover:text-foreground transition-all duration-200 shrink-0"
                                title="History"
                            >
                                <ClockCounterClockwise weight="bold" size={18} />
                            </button>
                            <button
                                onClick={() => {
                                    playSfx('cursor');
                                    setSidebarView('trash');
                                }}
                                className="h-8 w-8 flex items-center justify-center rounded-none border border-border/60 shadow-sm bg-secondary/40 text-muted-foreground hover:bg-secondary/60 hover:text-foreground transition-all duration-200 shrink-0"
                                title="Trash"
                            >
                                <Trash weight="bold" size={18} />
                            </button>
                            <button
                                onClick={() => {
                                    playSfx('cursor');
                                    navigate('/settings');
                                }}
                                className={cn(
                                    "h-8 w-8 flex items-center justify-center rounded-none border border-border/60 shadow-sm transition-all duration-200 shrink-0",
                                    location.pathname === '/settings'
                                        ? "bg-primary/20 text-primary border-primary/30"
                                        : "bg-secondary/40 text-muted-foreground hover:bg-secondary/60 hover:text-foreground"
                                )}
                                title="Settings"
                            >
                                <Gear weight="fill" size={18} />
                            </button>
                        </div>
                    )}
                </div>
                </>
            )}
            </motion.aside>

            {isSidebarCollapsed && !isSlim && (
                <button
                    onClick={() => {
                        playSfx('cursor');
                        toggleSidebarCollapse();
                    }}
                    className="fixed top-1/2 -translate-y-1/2 left-4 z-30 h-10 w-8 rounded-none border border-border/60 shadow-sm bg-secondary/40 text-muted-foreground hover:text-foreground hover:bg-secondary/60 transition-all duration-200 flex items-center justify-center"
                    title="Show sidebar"
                >
                    <SidebarSimple weight="bold" size={18} />
                </button>
            )}

            {/* ═══════════════════════════════════════════════════════
               DIALOG COMPONENTS
               ═══════════════════════════════════════════════════════ */}

            <CreateCollectionDialog
                open={createCollectionOpen}
                onOpenChange={setCreateCollectionOpen}
                onSubmit={handleCreateCollection}
                title={sidebarView === 'collections' ? "New Bucket" : "New Collection"}
            />
            <CreateFolderDialog
                open={createFolderOpen}
                onOpenChange={setCreateFolderOpen}
                onSubmit={handleCreateFolder}
            />
            <EditCollectionDialog
                open={editCollectionOpen}
                onOpenChange={setEditCollectionOpen}
                collection={collectionToEdit}
                onSubmit={handleUpdateCollection}
            />

            <CreateStorageDialog
                open={createStorageOpen}
                onOpenChange={setCreateStorageOpen}
                onSubmit={handleCreateStorageSubmit}
            />
            <EditStorageDialog
                open={editStorageOpen}
                onOpenChange={setEditStorageOpen}
                onSubmit={handleUpdateStorage}
                initialName={storageToEdit?.name || ""}
                initialColor={storageToEdit?.color}
                initialIcon={storageToEdit?.icon}
            />
            <EditGraphDialog
                open={editGraphOpen}
                onOpenChange={setEditGraphOpen}
                onSubmit={handleUpdateGraph}
                initialName={graphToEdit?.name || ""}
                initialColor={graphToEdit?.color}
                initialIcon={graphToEdit?.icon}
            />
            <EditDocDialog
                open={renameDocOpen}
                onOpenChange={setRenameDocOpen}
                onSubmit={handleUpdateDoc}
                initialName={docToRename?.name || ""}
                initialColor={docToRename?.color}
                initialIcon={docToRename?.icon}
            />
            <EditProjectDialog
                open={editProjectOpen}
                onOpenChange={setEditProjectOpen}
                currentName={projects.find((p: Project) => p.id === activeProjectId)?.name || ""}
                onSave={(newName) => {
                    if (activeProjectId) {
                        updateProject(activeProjectId, { name: newName });
                    }
                }}
                onDelete={() => {
                    if (activeProjectId) {
                        deleteProject(activeProjectId);
                    }
                }}
            />




            <NewDocDialog
                open={newDocOpen}
                onOpenChange={setNewDocOpen}
                onSubmit={handleCreateDocSubmit}
            />

            <NewGraphDialog
                open={newGraphOpen}
                onOpenChange={setNewGraphOpen}
                onSubmit={handleCreateGraphSubmit}
            />

            <Dialog open={newProjectOpen} onOpenChange={setNewProjectOpen}>
                <DialogContent className="sm:max-w-md bg-zinc-950 border-zinc-800 text-white">
                    <DialogHeader>
                        <DialogTitle>New Project</DialogTitle>
                        <DialogDescription className="text-zinc-400">
                            Enter a name for your new archive.
                        </DialogDescription>
                    </DialogHeader>
                    <div className="space-y-4 py-4">
                        <div className="space-y-2">
                            <Label htmlFor="new-project-name" className="text-zinc-400">Project Name</Label>
                            <Input
                                id="new-project-name"
                                placeholder="E.g. My Creative Work"
                                value={newProjectName}
                                onChange={(e: ReactChangeEvent<HTMLInputElement>) => setNewProjectName(e.target.value)}
                                autoFocus
                                className="bg-zinc-900 border-zinc-800 text-white placeholder:text-zinc-500 focus-visible:ring-zinc-800"
                            />
                        </div>
                    </div>
                    <DialogFooter>
                        <Button 
                            variant="ghost" 
                            onClick={() => setNewProjectOpen(false)}
                            className="text-zinc-400 hover:text-white hover:bg-zinc-900"
                        >
                            Cancel
                        </Button>
                        <Button 
                            onClick={handleCreateProjectSubmit} 
                            disabled={!newProjectName.trim()}
                            className="bg-primary text-primary-foreground hover:bg-primary/90"
                        >
                            Create Project
                        </Button>
                    </DialogFooter>
                </DialogContent>
            </Dialog>
            <MoveCollectionDialog
                open={moveCollectionDialogOpen}
                onOpenChange={setMoveCollectionDialogOpen}
                collectionIds={collectionToMove ? [collectionToMove.id] : []}
            />
        </>
    );
}

/**
 * ============================================================================
 * SIDEBAR FOLDER ITEM — Collapsible folder/bucket container in the sidebar
 * ============================================================================
 *
 * Renders a folder or root bucket header in the sidebar collection tree.
 * Supports:
 *  - Expand/collapse with animation (Framer Motion)
 *  - Drag-and-drop (as both a draggable sortable item AND a drop target)
 *  - Active/selected state theming (primary colors when viewing this folder)
 *  - Slim mode (icon-only layout for collapsed sidebar)
 *  - Nested folder depth indentation
 *  - Hover-reveal action buttons: open, add collection, add folder, rename, delete
 *  - Right-click context menu with rename, move, delete
 *  - Auto-expand when folder becomes active via route navigation
 *
 * Children are rendered inside the collapsible area (collections and sub-folders).
 *
 * Props:
 *  - folder:           The folder/bucket data object
 *  - isRoot:           Whether this is the root bucket header
 *  - isSlim:           Slim sidebar mode
 *  - depth:            Nesting depth for indentation
 *  - isCollapsed:      Root-level collapse state (only used when isRoot=true)
 *  - onToggleCollapse: Root-level toggle callback (only used when isRoot=true)
 *  - collapsedById:    Map of folder IDs to their collapsed state
 *  - setCollapsedById: Setter for the collapsed state map
 *  - currentFolderId:  Active folder ID from URL params
 *  - folders:          All available folders (for "Move to" context menu)
 *  - children:         React children rendered in the collapsible area
 *
 * Used by: ProjectSidebar → collection tree rendering
 * ============================================================================
 */

import React, { useEffect } from "react";
import { useNavigate, useLocation } from "react-router-dom";
import { motion, AnimatePresence } from "framer-motion";
import {
    Folder,
    FolderOpen,
    FolderPlus,
    FolderSimplePlus,
    Plus,
    Trash,
    PencilSimple,
    CaretDown,
    HardDrives,
    ArrowSquareOut,
    Palette,
    Check,
    X,
    Shapes,
} from "@phosphor-icons/react";
import { useSortable } from '@dnd-kit/sortable';
import { useDroppable } from '@dnd-kit/core';
import { CSS } from '@dnd-kit/utilities';
import { cn } from "@/lib/utils";
import { useStore } from "@/store/useStore";
import { useShallow } from "@/lib/zustand-shallow";
import { getIcon, iconNames } from "@/utils/iconMap";
import { playSfx } from "@/utils/sound";
import {
    DropdownMenu,
    DropdownMenuContent,
    DropdownMenuItem,
    DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import {
    ContextMenu,
    ContextMenuContent,
    ContextMenuItem,
    ContextMenuLabel,
    ContextMenuTrigger,
    ContextMenuSeparator,
    ContextMenuSub,
    ContextMenuSubTrigger,
    ContextMenuSubContent,
} from "@/components/ui/context-menu";
import type { Collection } from "@/types";

const FOLDER_COLORS = [
    "#ef4444", "#f97316", "#f59e0b", "#84cc16", "#10b981",
    "#06b6d4", "#3b82f6", "#6366f1", "#8b5cf6", "#d946ef",
    "#f43f5e", "#64748b"
];

/** Props for the SidebarFolderItem component */
interface SidebarFolderItemProps {
    /** The folder/bucket data (with id, name, etc.) */
    folder: Pick<Collection, 'id' | 'name'> & Partial<Collection>;
    /** Whether the sidebar is in slim (icon-only) mode */
    isSlim: boolean;
    /** React children — collection items and sub-folders rendered inside collapse */
    children?: React.ReactNode;
    /** Callback to change this folder's color */
    onColorChange?: (color: string) => void;
    /** Callback to change this folder's icon */
    onIconChange?: (icon: string) => void;
    /** Callback to rename this folder */
    onRename?: () => void;
    /** Callback to delete this folder */
    onDelete?: () => void;
    /** Callback to move this folder to a new parent */
    onMove?: (newParentId: string | null) => void;
    /** Callback to open the move dialog for this folder */
    onMoveDialog?: () => void;
    /** All available sibling folders (for "Move to" submenu) */
    folders?: Collection[];
    /** Callback to open the "add collection" dialog */
    handleAddCollection: (e?: React.MouseEvent) => void;
    /** Callback to open the "add folder" dialog */
    handleAddFolder: (e?: React.MouseEvent) => void;
    /** Nesting depth (0 = direct child of root) */
    depth?: number;
    /** Whether this item is the root bucket header */
    isRoot?: boolean;
    /** Root-level toggle callback (only for isRoot=true) */
    onToggleCollapse?: () => void;
    /** Root-level collapsed state (only for isRoot=true) */
    isCollapsed?: boolean;
    /** Currently active folder ID from URL search params */
    currentFolderId?: string | null;
    /** Map of folder IDs → collapsed state (for non-root folders) */
    collapsedById?: Record<string, boolean>;
    /** Setter for the collapsedById map */
    setCollapsedById?: React.Dispatch<React.SetStateAction<Record<string, boolean>>>;
}

export function SidebarFolderItem({
    folder,
    isSlim,
    children,
    onRename,
    onDelete,
    onMove,
    onMoveDialog,
    onColorChange,
    onIconChange,
    folders,
    handleAddCollection,
    handleAddFolder,
    depth = 0,
    isRoot = false,
    onToggleCollapse,
    isCollapsed: isCollapsedProp,
    currentFolderId = null,
    collapsedById,
    setCollapsedById
}: SidebarFolderItemProps) {
    const navigate = useNavigate();
    const location = useLocation();

    // ── Auto-expand when this folder becomes the active route ────────────
    const isFolderActive = !isRoot && (
        location.pathname === `/collection/${folder.id}` ||
        (location.pathname === '/collections' && currentFolderId === folder.id)
    );

    useEffect(() => {
        if (isFolderActive && collapsedById?.[folder.id] !== false && setCollapsedById) {
            setCollapsedById((prev: Record<string, boolean>) => ({
                ...prev,
                [folder.id]: false
            }));
        }
    }, [isFolderActive]);

    // Determine collapsed state: root uses prop, non-root uses collapsedById map
    const isCollapsed = isRoot ? isCollapsedProp : (collapsedById?.[folder.id] ?? true);

    // ── Store data ──────────────────────────────────────────────────────────
    const { setSidebarView, activeCollectionId, collections } = useStore(useShallow((state) => ({
        setSidebarView: state.setSidebarView,
        activeCollectionId: state.activeCollectionId,
        collections: state.collections
    })));

    const activeCollection = activeCollectionId
        ? collections.find((c: Collection) => c.id === activeCollectionId)
        : null;
    const CollectionIcon = activeCollection ? getIcon(activeCollection.icon) : Folder;

    // ── Drag-and-drop setup ─────────────────────────────────────────────────
    const {
        attributes,
        listeners,
        setNodeRef: setSortableRef,
        transform,
        transition,
        isDragging
    } = useSortable({
        id: isRoot ? "collections-root-header" : folder.id,
        data: { type: 'folder', folder: isRoot ? { ...folder, id: null } : folder }
    });

    const { setNodeRef: setDroppableRef, isOver: isFolderOver } = useDroppable({
        id: isRoot ? "folder-nest-root" : `folder-nest-${folder.id}`,
        data: { type: 'folder', folderId: isRoot ? null : folder.id }
    });

    const style = {
        transform: CSS.Transform.toString(transform),
        transition,
        opacity: isDragging ? 0.5 : 1,
        position: "relative" as const,
        zIndex: isDragging ? 50 : "auto",
    };

    // ── Toggle handler ──────────────────────────────────────────────────────
    const handleToggle = (e?: React.MouseEvent) => {
        if (e) e.stopPropagation();
        playSfx('cursor');
        if (isRoot) {
            if (isSlim) {
                navigate('/collections');
            }
            if (onToggleCollapse) onToggleCollapse();
        } else {
            if (isSlim) {
                navigate(`/collections?folderId=${folder.id}`);
            } else {
                if (setCollapsedById) {
                    setCollapsedById((prev: Record<string, boolean>) => ({
                        ...prev,
                        [folder.id]: !(prev?.[folder.id] ?? true)
                    }));
                }
            }
        }
    };

    // ═══════════════════════════════════════════════════════════════════════
    // SLIM MODE RENDER
    // ═══════════════════════════════════════════════════════════════════════
    if (isSlim) {
        return (
            <div ref={setSortableRef} style={style} className="mb-1 flex justify-center">
                <button
                    ref={setDroppableRef}
                    onClick={handleToggle}
                    {...attributes}
                    {...listeners}
                    className={cn(
                        "p-2 rounded-md transition-all group text-zinc-500 hover:text-zinc-300 hover:bg-secondary/40",
                        isRoot && (location.pathname === '/collections' || location.pathname.startsWith('/collection/')) && "text-primary bg-primary/10",
                        !isRoot && (location.pathname === `/collection/${folder.id}` || (location.pathname === '/collections' && currentFolderId === folder.id)) && "text-primary bg-primary/10",
                        (isFolderOver || (isRoot && isDragging)) && "bg-primary/20 ring-2 ring-primary ring-inset"
                    )}
                    title={isRoot ? (activeCollectionId ? (collections.find((c: Collection) => c.id === activeCollectionId)?.name || "Bucket") : "Collections") : folder.name}
                >
                    {isRoot ? (
                        activeCollectionId ? (
                            <div style={{ color: activeCollection?.color }}>
                                <CollectionIcon weight="fill" className="size-5" />
                            </div>
                        ) : (
                            <Folder weight="fill" className="size-5" />
                        )
                    ) : folder.icon ? (
                        <div style={{ color: folder.color }}>
                            {React.createElement(getIcon(folder.icon), { weight: "fill", className: "size-4" })}
                        </div>
                    ) : (
                        <FolderOpen weight="bold" className="size-4" />
                    )}
                </button>
            </div>
        );
    }

    // ═══════════════════════════════════════════════════════════════════════
    // FULL MODE RENDER
    // ═══════════════════════════════════════════════════════════════════════
    return (
        <div ref={setSortableRef} style={style} className={cn("mb-0.5", isRoot && "mb-2")}>
            <ContextMenu>
                <ContextMenuTrigger asChild>
                    <div
                        ref={setDroppableRef}
                        onClick={handleToggle}
                        {...attributes}
                        {...listeners}
                        role="button"
                        tabIndex={0}
                        data-no-sfx
                        onKeyDown={(e) => {
                            if (e.key === 'Enter' || e.key === ' ') {
                                e.preventDefault();
                                handleToggle();
                            }
                        }}
                        className={cn(
                            "w-full flex items-center gap-2 pr-0 pl-2 py-0 text-[11px] font-semibold tracking-wider rounded-none transition-all group border shadow-sm relative h-7 cursor-pointer outline-none focus-visible:ring-1 focus-visible:ring-ring",
                            // Root theming: active vs inactive
                            isRoot
                                ? (location.pathname === '/collections' && !currentFolderId)
                                    ? "bg-primary/20 border-primary/30 text-primary uppercase"
                                    : "bg-secondary/40 border-border/60 text-zinc-500 hover:text-zinc-300 hover:bg-secondary/60 uppercase"
                                // Non-root theming: active vs inactive
                                : (location.pathname === `/collection/${folder.id}` || (location.pathname === '/collections' && currentFolderId === folder.id))
                                    ? "bg-primary/20 border-primary/30 text-primary"
                                    : "bg-secondary/20 border-border/40 text-muted-foreground hover:text-foreground hover:bg-secondary/30",
                            depth > 0 && "ml-3 w-[calc(100%-12px)]"
                        )}
                    >
                        {/* Collapse/expand caret */}
                        <div className={cn(
                            "flex-shrink-0 transition-transform duration-200",
                            isCollapsed ? "-rotate-90" : "rotate-0"
                        )}>
                            <CaretDown size={12} weight="bold" />
                        </div>

                        {/* Root icon: shows active collection icon or generic folder */}
                        {isRoot && (
                            activeCollectionId
                                ? <div style={{ color: activeCollection?.color }}><CollectionIcon weight="fill" className={cn("flex-shrink-0 size-4", (location.pathname === '/collections' || location.pathname.startsWith('/collection/')) && "brightness-125")} /></div>
                                : <Folder weight="fill" className={cn("flex-shrink-0 size-4", (location.pathname === '/collections' || location.pathname.startsWith('/collection/')) ? "text-primary" : "text-muted-foreground")} />
                        )}

                        {/* Non-root folder icon: shows user-set icon or default folder */}
                        {!isRoot && (
                            folder.icon ? (
                                <div style={{ color: folder.color }}>{React.createElement(getIcon(folder.icon), { weight: "fill", className: "flex-shrink-0 size-4" })}</div>
                            ) : (
                                <Folder weight="fill" className={cn("flex-shrink-0 size-4", (location.pathname === `/collection/${folder.id}` || (location.pathname === '/collections' && currentFolderId === folder.id)) ? "text-primary" : "text-muted-foreground")} />
                            )
                        )}

                        {/* Folder name */}
                        <span title={isRoot ? undefined : folder.name} className="truncate w-0 flex-1 text-left py-0.5 max-w-[calc(100%-60px)]">{folder.name}</span>

                        {/* ── Hover-reveal action buttons ──────────────────────────── */}
                        <div className="h-full flex-shrink-0 flex items-center transition-opacity opacity-0 group-hover:opacity-100 pointer-events-none group-hover:pointer-events-auto">
                            {/* Open folder button */}
                            <button
                                onPointerDown={(e) => e.stopPropagation()}
                                onClick={(e) => {
                                    e.stopPropagation();
                                    playSfx('cursor');
                                    if (isRoot) {
                                        navigate('/collections');
                                    } else {
                                        navigate(`/collections?folderId=${folder.id}`);
                                    }
                                }}
                                className="h-6 w-6 flex items-center justify-center rounded-none border border-border/60 shadow-sm bg-secondary/40 text-muted-foreground hover:bg-secondary/60 hover:text-foreground transition-all duration-200"
                                title="Open Folder"
                            >
                                <ArrowSquareOut weight="bold" size={14} />
                            </button>

                            {/* Manage Buckets button (root only) */}
                            {isRoot && (
                                <button
                                    onPointerDown={(e) => e.stopPropagation()}
                                    onClick={(e) => {
                                        e.stopPropagation();
                                        playSfx('cursor');
                                        setSidebarView('collections');
                                    }}
                                    className="h-6 w-6 flex items-center justify-center rounded-none border border-border/60 shadow-sm bg-secondary/40 text-muted-foreground hover:bg-secondary/60 hover:text-foreground transition-all duration-200"
                                    title="Manage Buckets"
                                >
                                    <HardDrives weight="bold" size={14} />
                                </button>
                            )}

                            {/* Add item dropdown (collection or folder) */}
                            <DropdownMenu modal={false}>
                                <DropdownMenuTrigger asChild>
                                    <button
                                        onPointerDown={(e) => e.stopPropagation()}
                                        onClick={(e) => e.stopPropagation()}
                                        className="h-6 w-6 flex items-center justify-center rounded-none border border-border/60 shadow-sm bg-secondary/40 text-muted-foreground hover:bg-secondary/60 hover:text-foreground transition-all duration-200"
                                        title="Add Item"
                                    >
                                        <Plus weight="bold" size={14} />
                                    </button>
                                </DropdownMenuTrigger>
                                <DropdownMenuContent loop side="bottom" align="start" sideOffset={4} className="w-40" onCloseAutoFocus={(e: Event) => e.preventDefault()} onClick={(e: React.MouseEvent) => e.stopPropagation()}>
                                    <DropdownMenuItem onSelect={() => {
                                        playSfx('cursor');
                                        if (!isRoot) {
                                            navigate(`/collections?folderId=${folder.id}`, { replace: true });
                                        }
                                        handleAddCollection();
                                    }}>
                                        <FolderPlus className="mr-2 h-4 w-4" />
                                        Collection
                                    </DropdownMenuItem>
                                    <DropdownMenuItem onSelect={() => {
                                        playSfx('cursor');
                                        if (!isRoot) {
                                            navigate(`/collections?folderId=${folder.id}`, { replace: true });
                                        }
                                        handleAddFolder();
                                    }}>
                                        <FolderSimplePlus className="mr-2 h-4 w-4" />
                                        Folder
                                    </DropdownMenuItem>
                                </DropdownMenuContent>
                            </DropdownMenu>

                            {/* Rename and delete buttons (non-root only) */}
                            {!isRoot && (
                                <>
                                    <button
                                        onPointerDown={(e) => e.stopPropagation()}
                                        onClick={(e) => {
                                            e.stopPropagation();
                                            playSfx('cursor');
                                            onRename?.();
                                        }}
                                        className="h-6 w-6 flex items-center justify-center rounded-none border border-border/60 shadow-sm bg-secondary/40 text-muted-foreground hover:bg-secondary/60 hover:text-foreground transition-all duration-200"
                                        title="Edit Folder"
                                    >
                                        <PencilSimple weight="bold" size={14} />
                                    </button>
                                    <button
                                        onPointerDown={(e) => e.stopPropagation()}
                                        onClick={(e) => {
                                            e.stopPropagation();
                                            playSfx('cursor');
                                            onDelete?.();
                                        }}
                                        className="h-6 w-6 flex items-center justify-center rounded-none border border-border/60 shadow-sm bg-secondary/40 text-muted-foreground hover:bg-secondary/60 hover:text-foreground transition-all duration-200"
                                        title="Delete Folder"
                                    >
                                        <Trash weight="bold" size={14} />
                                    </button>
                                </>
                            )}
                        </div>
                    </div>
                </ContextMenuTrigger>

                {/* Right-click context menu */}
                <ContextMenuContent side="bottom" align="start" sideOffset={4} className="min-w-[8rem]">
                    {/* Open — both root and non-root */}
                    <ContextMenuItem onClick={() => {
                        playSfx('cursor');
                        if (isRoot) {
                            navigate('/collections');
                        } else {
                            navigate(`/collections?folderId=${folder.id}`);
                        }
                    }}>
                        <ArrowSquareOut className="mr-2 h-4 w-4" />
                        {isRoot ? 'Open' : 'Open Folder'}
                    </ContextMenuItem>

                    {/* Manage Buckets — root only */}
                    {isRoot && (
                        <ContextMenuItem onClick={() => {
                            playSfx('cursor');
                            setSidebarView('collections');
                        }}>
                            <HardDrives className="mr-2 h-4 w-4" />
                            Manage Buckets
                        </ContextMenuItem>
                    )}

                    <ContextMenuSeparator />

                    {/* Add Collection & Folder — both root and non-root */}
                    <ContextMenuItem onClick={() => {
                        playSfx('cursor');
                        if (!isRoot) {
                            navigate(`/collections?folderId=${folder.id}`, { replace: true });
                        }
                        handleAddCollection();
                    }}>
                        <FolderPlus className="mr-2 h-4 w-4" />
                        Add Collection
                    </ContextMenuItem>
                    <ContextMenuItem onClick={() => {
                        playSfx('cursor');
                        if (!isRoot) {
                            navigate(`/collections?folderId=${folder.id}`, { replace: true });
                        }
                        handleAddFolder();
                    }}>
                        <FolderSimplePlus className="mr-2 h-4 w-4" />
                        Add Folder
                    </ContextMenuItem>

                    {/* Edit actions — non-root only */}
                    {!isRoot && (
                        <>
                            <ContextMenuSeparator />
                            <ContextMenuLabel>Edit</ContextMenuLabel>
                            <ContextMenuItem onClick={onRename}>
                                <PencilSimple className="mr-2 h-4 w-4" />
                                Edit Folder
                            </ContextMenuItem>
                            {onMoveDialog && (
                                <ContextMenuItem onClick={onMoveDialog}>
                                    <FolderOpen className="mr-2 h-4 w-4" />
                                    Move to
                                </ContextMenuItem>
                            )}
                            <ContextMenuSub>
                                <ContextMenuSubTrigger>
                                    <Palette className="mr-2 h-4 w-4" />
                                    Change Color
                                </ContextMenuSubTrigger>
                                <ContextMenuSubContent className="p-2">
                                    <div className="grid grid-cols-5 gap-1.5">
                                        {FOLDER_COLORS.map((c) => (
                                            <ContextMenuItem
                                                key={c}
                                                className="p-0 w-6 h-6 rounded-none focus:bg-transparent"
                                                onSelect={() => onColorChange?.(c)}
                                            >
                                                <div
                                                    className={cn(
                                                        "w-6 h-6 rounded-none border-2 flex items-center justify-center transition-all",
                                                        folder.color?.toLowerCase() === c.toLowerCase()
                                                            ? "border-white scale-110"
                                                            : "border-transparent hover:border-white/30 hover:scale-110"
                                                    )}
                                                    style={{ backgroundColor: c }}
                                                >
                                                    {folder.color?.toLowerCase() === c.toLowerCase() && (
                                                        <Check weight="bold" className="w-3 h-3 text-white drop-shadow" />
                                                    )}
                                                </div>
                                            </ContextMenuItem>
                                        ))}
                                        <ContextMenuItem
                                            className="p-0 w-6 h-6 rounded-none focus:bg-transparent"
                                            onSelect={() => onColorChange?.("")}
                                        >
                                            <div
                                                className={cn(
                                                    "w-6 h-6 rounded-none border-2 flex items-center justify-center transition-all bg-zinc-800",
                                                    !folder.color
                                                        ? "border-white scale-110"
                                                        : "border-transparent hover:border-white/30 hover:scale-110"
                                                )}
                                            >
                                                {!folder.color ? (
                                                    <Check weight="bold" className="w-3 h-3 text-white drop-shadow" />
                                                ) : (
                                                    <X weight="bold" className="w-3 h-3 text-zinc-400" />
                                                )}
                                            </div>
                                        </ContextMenuItem>
                                    </div>
                                </ContextMenuSubContent>
                            </ContextMenuSub>
                            <ContextMenuSub>
                                <ContextMenuSubTrigger>
                                    <Shapes className="mr-2 h-4 w-4" />
                                    Change Icon
                                </ContextMenuSubTrigger>
                                <ContextMenuSubContent className="p-2">
                                    <div className="grid grid-cols-5 gap-1.5">
                                        {iconNames.map((name) => {
                                            const Icon = getIcon(name);
                                            return (
                                                <ContextMenuItem
                                                    key={name}
                                                    className="p-0 w-6 h-6 rounded-none focus:bg-transparent"
                                                    onSelect={() => onIconChange?.(name)}
                                                >
                                                    <div
                                                        className={cn(
                                                            "w-6 h-6 rounded-none border-2 flex items-center justify-center transition-all",
                                                            folder.icon === name
                                                                ? "border-white scale-110 bg-zinc-700"
                                                                : "border-transparent hover:border-white/30 hover:scale-110"
                                                        )}
                                                    >
                                                        <Icon weight={folder.icon === name ? "fill" : "regular"} className="w-3.5 h-3.5 text-zinc-200" />
                                                    </div>
                                                </ContextMenuItem>
                                            );
                                        })}
                                        <ContextMenuItem
                                            className="p-0 w-6 h-6 rounded-none focus:bg-transparent"
                                            onSelect={() => onIconChange?.("")}
                                        >
                                            <div
                                                className={cn(
                                                    "w-6 h-6 rounded-none border-2 flex items-center justify-center transition-all bg-zinc-800",
                                                    !folder.icon
                                                        ? "border-white scale-110"
                                                        : "border-transparent hover:border-white/30 hover:scale-110"
                                                )}
                                            >
                                                {!folder.icon ? (
                                                    <Check weight="bold" className="w-3 h-3 text-white drop-shadow" />
                                                ) : (
                                                    <X weight="bold" className="w-3 h-3 text-zinc-400" />
                                                )}
                                            </div>
                                        </ContextMenuItem>
                                    </div>
                                </ContextMenuSubContent>
                            </ContextMenuSub>
                            <ContextMenuSeparator />
                            <ContextMenuItem onClick={onDelete} className="text-red-500 focus:text-red-500">
                                <Trash className="mr-2 h-4 w-4" />
                                Delete Folder
                            </ContextMenuItem>
                        </>
                    )}
                </ContextMenuContent>
            </ContextMenu>

            {/* ── Collapsible children area ─────────────────────────────────── */}
            <AnimatePresence initial={false}>
                {!isCollapsed && (
                    <motion.div
                        initial={{ height: 0, opacity: 0 }}
                        animate={{ height: "auto", opacity: 1 }}
                        exit={{ height: 0, opacity: 0 }}
                        transition={{ duration: 0.2 }}
                        className={cn(
                            "overflow-hidden border-l border-zinc-800/50 ml-2.5 pl-1.5 mt-0.5 space-y-0.5",
                            depth > 0 && "ml-5.5",
                            isRoot && "ml-3 border-l border-border/40 pl-2"
                        )}
                    >
                        {children}
                    </motion.div>
                )}
            </AnimatePresence>
        </div>
    );
}

import { useEffect, useState, useRef, type KeyboardEvent, type MouseEvent, type ChangeEvent, type FormEvent } from "react";
import { useNavigate } from "react-router-dom";
import { useShallow } from "@/lib/zustand-shallow";
import { useStore, type AppStore } from "@/store/useStore";
import { authStorage } from "@/utils/authStorage";
import { useSync } from "@/hooks/useSync";
import { SYNC_API_URL } from "@/constants";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { ScrollArea } from "@/components/ui/scroll-area";
import {
    CaretLeft,
    CloudArrowUp,
    CloudArrowDown,
    Gear,
    Cloud,
    SignIn,
    SignOut,
    User,
    CheckCircle,
    Shuffle,
    ShieldCheck,
    Copy,
    Warning,
    QrCode,
    PencilSimple,
    Check,
    
    X,
    Eye,
    EyeSlash,
    Fingerprint
} from "@phosphor-icons/react";
import { Separator } from "@/components/ui/separator";

import { startAuthentication } from "@/utils/webauthn";

declare global {
    interface Window {
        turnstile?: {
            reset: (container?: string | HTMLElement) => void;
            render: (container: string | HTMLElement, options: { sitekey: string; theme?: string; callback?: (token: string) => void; 'error-callback'?: () => void }) => string;
            remove: (widgetId: string) => void;
        };
    }
}

const TURNSTILE_SITE_KEY = "0x4AAAAAACL9Ojn2jXAFNaw_";

interface SidebarSyncProps {
    onBack: () => void;
}

export function SidebarSync({ onBack }: SidebarSyncProps) {
    const {
        user,
        login,
        logout,
        updateUser,
        lastSyncTime,
        setLastSyncTime,
        setState,
        syncStatus,
        setSyncStatus
    } = useStore(useShallow((state: AppStore) => ({
        user: state.user,
        login: state.login,
        logout: state.logout,
        updateUser: state.updateUser,
        lastSyncTime: state.lastSyncTime,
        setLastSyncTime: state.setLastSyncTime,
        setState: state.setState,
        syncStatus: state.syncStatus,
        setSyncStatus: state.setSyncStatus
    })));
    const { handleSync, error: syncError } = useSync();
    const [syncId, setSyncId] = useState("");
    const [isLoading, setIsLoading] = useState(false);
    const [captchaToken, setCaptchaToken] = useState<string | null>(null);
    const [accountId, setAccountId] = useState<string | null>(null);
    const [sessionToken, setSessionToken] = useState<string | null>(null);
    const [error, setError] = useState<string | null>(null);
    const [phase, setPhase] = useState<'login' | 'totp'>('login');
    const [pendingToken, setPendingToken] = useState<string | null>(null);
    const [totpCode, setTotpCode] = useState("");
    const [turnstileWidgetId, setTurnstileWidgetId] = useState<string | null>(null);
    
    // 2FA Management State
    const [totpEnabled, setTotpEnabled] = useState(false);
    const [showTwoFactorSetup, setShowTwoFactorSetup] = useState(false);
    const [setupMode, setSetupMode] = useState<'enable' | 'disable'>('enable');
    const [setupSecret, setSetupSecret] = useState<string | null>(null);
    const [setupStep, setSetupStep] = useState<'intro' | 'scan' | 'verify'>('intro');

    const [isEditingName, setIsEditingName] = useState(false);
    const [editName, setEditName] = useState("");
    const [isSyncIdRevealed, setIsSyncIdRevealed] = useState(false);

    const navigate = useNavigate();
    const containerRef = useRef<HTMLDivElement>(null);
    const sidebarHeaderButtonClassName = "h-6 w-6 flex items-center justify-center rounded-none border border-border/60 shadow-sm bg-secondary/40 text-muted-foreground transition-all duration-200 hover:bg-secondary/60 hover:text-foreground";
    const sidebarHeaderTitleClassName = "flex-1 flex items-center justify-center gap-2 text-sm font-semibold text-foreground";
    const sidebarSectionClassName = "rounded-none border border-border bg-card/50 p-3";
    const sidebarSectionEyebrowClassName = "text-[10px] font-semibold uppercase tracking-[0.15em] text-muted-foreground/70";
    const syncStatusBadgeClassName =
        syncStatus === "syncing"
            ? "border-blue-500/30 bg-blue-500/10 text-blue-400"
            : syncStatus === "error"
                ? "border-red-500/30 bg-red-500/10 text-red-400"
                : "border-green-500/30 bg-green-500/10 text-green-400";
    const syncStatusLabel =
        syncStatus === "syncing"
            ? "Syncing"
            : syncStatus === "error"
                ? "Attention"
                : lastSyncTime
                    ? "Connected"
                    : "Ready";
    const syncStatusIconToneClassName =
        syncStatus === "syncing"
            ? "border-blue-500/30 bg-blue-500/10 text-blue-400"
            : syncStatus === "error"
                ? "border-red-500/30 bg-red-500/10 text-red-400"
                : "border-green-500/30 bg-green-500/10 text-green-400";

    useEffect(() => {
        let widgetId: string | null = null;
        const interval = setInterval(() => {
            if (window.turnstile && !widgetId) {
                const container = containerRef.current;
                if (container) {
                    // Check if container already has content to avoid double render
                    if (container.hasChildNodes()) {
                        clearInterval(interval);
                        return;
                    }
                    
                    try {
                        widgetId = window.turnstile.render(container, {
                            sitekey: TURNSTILE_SITE_KEY,
                            theme: "auto",
                            callback: (token: string) => {
                                setCaptchaToken(token);
                                setError(null);
                            },
                            "expired-callback": () => {
                                setCaptchaToken(null);
                            },
                        });
                        setTurnstileWidgetId(widgetId);
                        clearInterval(interval);
                    } catch (e) {
                        console.error("Turnstile render error:", e);
                    }
                }
            }
        }, 500);

        return () => {
            clearInterval(interval);
            if (widgetId && window.turnstile) {
                try {
                    window.turnstile.remove(widgetId);
                } catch (e) {
                    // Ignore removal errors
                }
            }
        };
    }, []);

    useEffect(() => {
        const { accountId: storedAccount, token: storedToken, lastSync: storedLastSync, displayName: storedDisplayName, totpEnabled } = authStorage.getCredentials();
        
        if (storedAccount && storedToken) {
            setAccountId(storedAccount);
            setSessionToken(storedToken);
            
            if (totpEnabled) {
                setTotpEnabled(true);
            }
            
            // Only update store if not already logged in or ID mismatch
            if (!user || user.id !== storedAccount) {
                login({ id: storedAccount, email: storedDisplayName || storedAccount });
            }
            
            if (storedLastSync) {
                const asNumber = Number(storedLastSync);
                if (!Number.isNaN(asNumber)) {
                    const current = useStore.getState().lastSyncTime;
                    if (!current || asNumber > current) {
                        setLastSyncTime(asNumber);
                    }
                }
            }
        } else {
            // Clear local state if storage is empty
            setAccountId(null);
            setSessionToken(null);
            setTotpEnabled(false);
        }
    }, [login, setLastSyncTime, user?.id]);

    const formatAccountId = (id: string) => {
        const clean = id.replace(/\D/g, "").slice(0, 16);
        const parts = [];
        for (let i = 0; i < clean.length; i += 4) {
            parts.push(clean.slice(i, i + 4));
        }
        return parts.join("-");
    };

    const getCleanAccountId = (value: string) => value.replace(/\D/g, "").slice(0, 16);

    const handleLogin = async (e: FormEvent) => {
        e.preventDefault();
        const cleanId = getCleanAccountId(syncId);
        if (cleanId.length !== 16) {
            setError("Sync ID must be 16 digits");
            return;
        }
        if (!captchaToken) {
            setError("Complete the captcha to continue");
            return;
        }
        setIsLoading(true);
        setError(null);
        try {
            const response = await fetch(`${SYNC_API_URL}/login`, {
                method: "POST",
                headers: { "Content-Type": "application/json" },
                body: JSON.stringify({
                    account_id: cleanId,
                    captcha_token: captchaToken,
                }),
            });
            const data = await response.json();
            if (!response.ok) {
                setError(data.error || "Login failed");
                if (window.turnstile) {
                    window.turnstile.reset();
                }
                return;
            }
            setCaptchaToken(null);
            if (data.requires_totp) {
                setPendingToken(data.pending_token);
                setPhase("totp");
                setAccountId(cleanId);
                return;
            }
            const token: string = data.token;
            const displayName: string | undefined = data.display_name;
            setAccountId(cleanId);
            setSessionToken(token);
            authStorage.setCredentials({ accountId: cleanId, token, displayName });
            // If we logged in without 2FA challenge, it means 2FA is disabled
            setTotpEnabled(false);
            authStorage.setTotpEnabled(false);
            
            login({ id: cleanId, email: displayName || cleanId });
        } catch (err) {
            setError(err instanceof Error ? err.message : "Login error");
        } finally {
            setIsLoading(false);
        }
    };

    const handleGenerateId = () => {
        const array = new Uint8Array(8);
        crypto.getRandomValues(array);
        let id = "";
        for (let i = 0; i < array.length; i++) {
            const digits = (array[i] % 100).toString().padStart(2, "0");
            id += digits;
        }
        setSyncId(formatAccountId(id));
    };

    const handleVerifyTotp = async () => {
        if (!pendingToken) {
            setError("No pending verification");
            return;
        }
        if (totpCode.replace(/\s/g, "").length !== 6) {
            setError("Enter a 6-digit code");
            return;
        }
        setIsLoading(true);
        setError(null);
        try {
            const response = await fetch(`${SYNC_API_URL}/login/totp`, {
                method: "POST",
                headers: { "Content-Type": "application/json" },
                body: JSON.stringify({
                    pending_token: pendingToken,
                    totp_code: totpCode.replace(/\s/g, ""),
                }),
            });
            const data = await response.json();
            if (!response.ok) {
                setError(data.error || "Verification failed");
                return;
            }
            const token: string = data.token;
            const account = data.account_id as string;
            const displayName: string | undefined = data.display_name;
            setAccountId(account);
            setSessionToken(token);
            authStorage.setCredentials({ accountId: account, token, displayName });
            // If we successfully verified TOTP, it means 2FA is enabled
            setTotpEnabled(true);
            authStorage.setTotpEnabled(true);

            login({ id: account, email: displayName || account });
            setPhase("login");
            setPendingToken(null);
            setTotpCode("");
        } catch (err) {
            setError(err instanceof Error ? err.message : "Verification error");
        } finally {
            setIsLoading(false);
        }
    };



    const handleLogout = () => {
        setAccountId(null);
        setSessionToken(null);
        setCaptchaToken(null);
        setPendingToken(null);
        setTotpCode("");
        authStorage.clearCredentials();
        logout();
    };

    const handlePasskeyLogin = async () => {
        const cleanId = getCleanAccountId(syncId);
        if (cleanId.length !== 16) {
            setError("Sync ID must be 16 digits");
            return;
        }
        setIsLoading(true);
        setError(null);
        try {
            // 1. Get authentication options from server
            const optionsResponse = await fetch(`${SYNC_API_URL}/passkeys/login/start`, {
                method: "POST",
                headers: { "Content-Type": "application/json" },
                body: JSON.stringify({ account_id: cleanId })
            });
            
            if (!optionsResponse.ok) {
                const errorData = await optionsResponse.json();
                throw new Error(errorData.error || "Failed to start passkey login");
            }
            
            const options = await optionsResponse.json();
            
            // 2. Get assertion using WebAuthn API
            const assertion = await startAuthentication(options);
            
            // 3. Send assertion to server to finish login
            let verifyResponse = await fetch(`${SYNC_API_URL}/passkeys/login/finish`, {
                method: "POST",
                headers: { "Content-Type": "application/json" },
                body: JSON.stringify({
                    account_id: cleanId,
                    assertion
                })
            });

            // Compatibility fallback: some backends expect assertion fields at top level.
            if (!verifyResponse.ok) {
                verifyResponse = await fetch(`${SYNC_API_URL}/passkeys/login/finish`, {
                    method: "POST",
                    headers: { "Content-Type": "application/json" },
                    body: JSON.stringify({
                        account_id: cleanId,
                        ...assertion
                    })
                });
            }
            
            if (!verifyResponse.ok) {
                const errorData = await verifyResponse.json();
                throw new Error(errorData.error || "Passkey login failed");
            }
            
            const data = await verifyResponse.json();
            const token: string = data.token;
            const displayName: string | undefined = data.display_name;
            
            setAccountId(cleanId);
            setSessionToken(token);
            authStorage.setCredentials({ accountId: cleanId, token, displayName });
            
            setTotpEnabled(data.totp_enabled || false);
            authStorage.setTotpEnabled(data.totp_enabled || false);
            
            login({ id: cleanId, email: displayName || cleanId });
            setPhase("login");
        } catch (err) {
            setError(err instanceof Error ? err.message : "Passkey login error");
        } finally {
            setIsLoading(false);
        }
    };

    // handleSync is now provided by useSync hook

    const handleStartEditName = () => {
        setEditName(user?.email && user.email !== accountId ? user.email : "");
        setIsEditingName(true);
    };

    const handleSaveName = () => {
        if (!user) return;
        const newName = editName.trim();
        // If empty, revert to ID (effectively) by storing empty string, 
        // but let's keep it clean.
        updateUser({ email: newName || user.id });
        
        if (newName) {
            authStorage.setDisplayName(newName);
        } else {
            authStorage.setDisplayName("");
        }
        setIsEditingName(false);
    };

    const handleStart2FASetup = async () => {
        setIsLoading(true);
        setError(null);
        try {
            const response = await fetch(`${SYNC_API_URL}/2fa/setup`, {
                method: "POST",
                headers: {
                    "Content-Type": "application/json",
                    Authorization: `Bearer ${sessionToken}`,
                },
            });
            if (response.status === 401) {
                handleLogout();
                setError("Session expired. Please sign in again.");
                return;
            }
            const data = await response.json();
            if (!response.ok) {
                if (data.error === "2FA is already enabled") {
                    setTotpEnabled(true);
                    authStorage.setTotpEnabled(true);
                }
                setError(data.error || "Setup failed");
                return;
            }
            setSetupSecret(data.secret);
            setSetupStep('scan');
        } catch (err) {
            setError(err instanceof Error ? err.message : "Setup error");
        } finally {
            setIsLoading(false);
        }
    };

    const handleEnable2FA = async () => {
        if (totpCode.length !== 6) {
            setError("Enter a 6-digit code");
            return;
        }
        setIsLoading(true);
        setError(null);
        try {
            const response = await fetch(`${SYNC_API_URL}/2fa/enable`, {
                method: "POST",
                headers: {
                    "Content-Type": "application/json",
                    Authorization: `Bearer ${sessionToken}`,
                },
                body: JSON.stringify({ totp_code: totpCode }),
            });
            if (response.status === 401) {
                handleLogout();
                setError("Session expired. Please sign in again.");
                return;
            }
            const data = await response.json();
            if (!response.ok) {
                setError(data.error || "Failed to enable 2FA");
                return;
            }
            setTotpEnabled(true);
            authStorage.setTotpEnabled(true);
            setSetupStep('intro');
            setShowTwoFactorSetup(false);
            setTotpCode("");
        } catch (err) {
            setError(err instanceof Error ? err.message : "Error enabling 2FA");
        } finally {
            setIsLoading(false);
        }
    };

    const handleDisable2FA = async () => {
        if (totpCode.length !== 6) {
            setError("Enter a 6-digit code");
            return;
        }
        setIsLoading(true);
        setError(null);
        try {
            const response = await fetch(`${SYNC_API_URL}/2fa/disable`, {
                method: "POST",
                headers: {
                    "Content-Type": "application/json",
                    Authorization: `Bearer ${sessionToken}`,
                },
                body: JSON.stringify({ totp_code: totpCode }),
            });
            if (response.status === 401) {
                handleLogout();
                setError("Session expired. Please sign in again.");
                return;
            }
            const data = await response.json();
            if (!response.ok) {
                setError(data.error || "Failed to disable 2FA");
                return;
            }
            setTotpEnabled(false);
            authStorage.setTotpEnabled(false);
            setTotpCode("");
            setShowTwoFactorSetup(false);
        } catch (err) {
            setError(err instanceof Error ? err.message : "Error disabling 2FA");
        } finally {
            setIsLoading(false);
        }
    };

    if (!user) {
        if (phase === "totp") {
            return (
                <div className="flex flex-col h-full bg-sidebar-background">
                    <div className="px-3 py-2 border-b border-border/40 bg-card/20 shrink-0">
                        <div className="flex items-center gap-2">
                            <button
                                onClick={onBack}
                                className={sidebarHeaderButtonClassName}
                                title="Back to sidebar"
                            >
                                <CaretLeft weight="bold" size={14} />
                            </button>
                            <div className={sidebarHeaderTitleClassName}>
                                <SignIn weight="bold" size={14} />
                                Sync 2FA
                            </div>
                            <button
                                title="Settings"
                                onClick={() => navigate('/settings?tab=sync')}
                                className={sidebarHeaderButtonClassName}
                            >
                                <Gear weight="bold" size={14} />
                            </button>
                        </div>
                    </div>
                    <div className="flex-1 p-3 flex flex-col justify-center items-center gap-3">
                        <div className="text-center space-y-2 mb-2">
                            <div className="w-12 h-12 bg-primary/10 rounded-full flex items-center justify-center mx-auto text-primary">
                                <Cloud weight="fill" size={24} />
                            </div>
                            <h3 className="font-semibold text-foreground">Two-Factor Authentication</h3>
                            <p className="text-xs text-muted-foreground max-w-[220px]">
                                Enter the 6-digit code from your authenticator app to finish login.
                            </p>
                        </div>
                        <div className="w-full space-y-3">
                            <Input
                                type="text"
                                inputMode="numeric"
                                maxLength={6}
                                value={totpCode}
                                onChange={(e: ChangeEvent<HTMLInputElement>) => setTotpCode(e.target.value.replace(/\D/g, "").slice(0, 6))}
                                autoComplete="one-time-code"
                                className="h-10 text-center tracking-[0.5em] text-lg font-mono bg-zinc-900 border-zinc-800 text-white placeholder:text-zinc-500"
                                placeholder="000000"
                            />
                            {error && (
                                <div className="text-xs text-red-400 text-center px-2">
                                    {error}
                                </div>
                            )}
                            <div className="flex gap-2">
                                <Button
                                    type="button"
                                    className="flex-1 h-8"
                                    onClick={handleVerifyTotp}
                                    disabled={isLoading}
                                >
                                    Verify
                                </Button>
                                <Button
                                    type="button"
                                    variant="outline"
                                    className="flex-1 h-8"
                                    onClick={() => {
                                        setPhase("login");
                                        setPendingToken(null);
                                        setTotpCode("");
                                    }}
                                >
                                    Cancel
                                </Button>
                            </div>
                        </div>
                    </div>
                </div>
            );
        }
        return (
            <div className="flex flex-col h-full bg-sidebar-background">
                <div className="px-3 py-2 border-b border-border/40 bg-card/20 shrink-0">
                    <div className="flex items-center gap-2">
                        <button
                            onClick={onBack}
                            className={sidebarHeaderButtonClassName}
                            title="Back to sidebar"
                        >
                            <CaretLeft weight="bold" size={14} />
                        </button>
                        <div className={sidebarHeaderTitleClassName}>
                            <SignIn weight="bold" size={14} />
                            Sync Access
                        </div>
                        <button
                            title="Settings"
                            onClick={() => navigate('/settings?tab=sync')}
                            className={sidebarHeaderButtonClassName}
                        >
                            <Gear weight="bold" size={14} />
                        </button>
                    </div>
                </div>

                    <div className="flex-1 p-3 flex flex-col justify-center items-center gap-3">
                    <div className="text-center space-y-2 mb-2">
                        <div className="w-12 h-12 bg-primary/10 rounded-full flex items-center justify-center mx-auto text-primary">
                            <Cloud weight="fill" size={24} />
                        </div>
                        <h3 className="font-semibold text-foreground">Sync Access</h3>
                        <p className="text-xs text-muted-foreground max-w-[200px]">
                            Enter your 16-digit Sync ID to access your data.
                        </p>
                    </div>

                    <form onSubmit={handleLogin} className="w-full space-y-3">
                        <div className="space-y-1">
                            <label className="text-[10px] font-bold text-muted-foreground uppercase tracking-wider">Sync ID</label>
                            <Input 
                                type="text" 
                                placeholder="16-digit ID" 
                                value={syncId}
                                onChange={(e: ChangeEvent<HTMLInputElement>) => setSyncId(formatAccountId(e.target.value))}
                                className="h-8 text-sm font-mono bg-zinc-900 border-zinc-800 text-white placeholder:text-zinc-500"
                                maxLength={19}
                                minLength={16}
                                required
                            />
                            <Button
                                type="button"
                                variant="outline"
                                className="w-full h-8 mt-1 text-xs gap-2 border-sidebar-border bg-sidebar-background hover:bg-sidebar-accent"
                                onClick={handleGenerateId}
                                title="Generate New Account ID"
                            >
                                <Shuffle weight="bold" className="size-4" />
                                <span>Generate New Account ID</span>
                            </Button>
                        </div>
                        <div className="flex justify-center items-center relative min-h-[65px]">
                            <div
                                ref={containerRef}
                                className="relative z-10 scale-[0.85] origin-center flex items-center justify-center"
                            />
                        </div>
                        {error && (
                            <div className="text-xs text-red-400 text-center px-2">
                                {error}
                            </div>
                        )}
                        <div className="flex flex-col gap-2">
                            <Button
                                type="submit"
                                className="w-full h-8"
                                disabled={isLoading || getCleanAccountId(syncId).length < 16}
                                data-sound-confirm
                            >
                                {isLoading ? "Connecting..." : "Connect"}
                            </Button>
                            <div className="flex items-center gap-2">
                                <div className="h-[1px] flex-1 bg-border/40" />
                                <span className="text-[10px] uppercase tracking-wider text-muted-foreground font-medium">or</span>
                                <div className="h-[1px] flex-1 bg-border/40" />
                            </div>
                            <Button
                                type="button"
                                variant="outline"
                                className="w-full h-8"
                                onClick={handlePasskeyLogin}
                                disabled={isLoading}
                            >
                                <Fingerprint className="mr-2" size={16} />
                                Use Passkey
                            </Button>
                        </div>
                    </form>
                    
                    <div className="text-center mt-4">
                        <p className="text-[10px] text-muted-foreground">
                            Use the same ID on all devices to sync.
                        </p>
                    </div>
                </div>
            </div>
        );
    }

    if (showTwoFactorSetup) {
        return (
            <div className="flex flex-col h-full bg-sidebar-background">
                <div className="px-3 py-2 border-b border-border/40 bg-card/20 shrink-0">
                    <div className="flex items-center gap-2">
                        <button
                            onClick={() => {
                                setShowTwoFactorSetup(false);
                                setSetupStep('intro');
                                setTotpCode("");
                                setError(null);
                            }}
                            data-sound-back
                            className={sidebarHeaderButtonClassName}
                            title="Back to sync"
                        >
                            <CaretLeft weight="bold" size={14} />
                        </button>
                        <div className={sidebarHeaderTitleClassName}>
                            <ShieldCheck weight="bold" size={14} />
                            {setupMode === 'enable' ? 'Setup 2FA' : 'Disable 2FA'}
                        </div>
                        <div className="h-6 w-6 shrink-0" aria-hidden="true" />
                    </div>
                </div>

                <div className="flex-1 px-3 py-3 flex flex-col items-center gap-3 overflow-y-auto">
                    {setupMode === 'enable' && setupStep === 'intro' && (
                        <div className="text-center space-y-4 pt-8">
                            <div className="w-16 h-16 bg-primary/10 rounded-full flex items-center justify-center mx-auto text-primary">
                                <ShieldCheck weight="fill" size={32} />
                            </div>
                            <div className="space-y-2">
                                <h3 className="font-semibold text-foreground">Secure your account</h3>
                                <p className="text-sm text-muted-foreground max-w-[240px] mx-auto">
                                    Two-factor authentication adds an extra layer of security to your sync account.
                                </p>
                            </div>
                            <Button 
                                onClick={handleStart2FASetup} 
                                disabled={isLoading}
                                className="w-full"
                            >
                                {isLoading ? "Starting..." : "Start Setup"}
                            </Button>
                        </div>
                    )}

                    {setupMode === 'enable' && setupStep === 'scan' && (
                        <div className="w-full space-y-6">
                            <div className="flex flex-col items-center justify-center p-8 text-center space-y-4">
                                <QrCode size={128} className="bg-white p-2 rounded-lg text-black" />
                                <div className="space-y-2">
                                    <p className="text-sm font-medium">Scan with your authenticator app</p>
                                </div>
                            </div>

                            <Separator className="bg-sidebar-border" />

                            <div className="space-y-2 text-center">
                                <p className="text-sm font-medium">1. Copy Secret Key</p>
                                <p className="text-xs text-muted-foreground">
                                    Enter this key into your authenticator app (Google Authenticator, Authy, etc).
                                </p>
                                <div className="flex items-center gap-2 mt-2">
                                    <code className="flex-1 bg-zinc-900 p-2 rounded text-xs font-mono break-all border border-zinc-800">
                                        {setupSecret}
                                    </code>
                                    <Button
                                        size="icon"
                                        variant="outline"
                                        className="h-8 w-8 shrink-0"
                                        onClick={() => {
                                            if (setupSecret) navigator.clipboard.writeText(setupSecret);
                                        }}
                                        title="Copy Secret"
                                    >
                                        <Copy size={14} />
                                    </Button>
                                </div>
                            </div>

                            <Separator className="bg-sidebar-border" />

                            <div className="space-y-3 text-center">
                                <p className="text-sm font-medium">2. Enter Verification Code</p>
                                <Input
                                    type="text"
                                    inputMode="numeric"
                                    maxLength={6}
                                    value={totpCode}
                                    onChange={(e: ChangeEvent<HTMLInputElement>) => setTotpCode(e.target.value.replace(/\D/g, "").slice(0, 6))}
                                    className="h-10 text-center tracking-[0.5em] text-lg font-mono bg-zinc-900 border-zinc-800 text-white placeholder:text-zinc-500"
                                    placeholder="000000"
                                />
                                {error && (
                                    <div className="text-xs text-red-400 px-2">{error}</div>
                                )}
                                <Button 
                                    onClick={handleEnable2FA} 
                                    disabled={isLoading || totpCode.length !== 6}
                                    className="w-full"
                                >
                                    {isLoading ? "Verifying..." : "Verify & Enable"}
                                </Button>
                            </div>
                        </div>
                    )}

                    {setupMode === 'disable' && (
                        <div className="w-full space-y-4 pt-4">
                            <div className="p-3 bg-red-500/10 border border-red-500/20 rounded-lg flex gap-3 items-start">
                                <Warning className="text-red-500 shrink-0 mt-0.5" weight="fill" size={16} />
                                <div className="text-xs text-red-200">
                                    Disabling 2FA will make your account less secure. You will need to enter a code one last time.
                                </div>
                            </div>

                            <div className="space-y-3">
                                <Label className="text-xs">Enter Code</Label>
                                <Input
                                    type="text"
                                    inputMode="numeric"
                                    maxLength={6}
                                    value={totpCode}
                                    onChange={(e: ChangeEvent<HTMLInputElement>) => setTotpCode(e.target.value.replace(/\D/g, "").slice(0, 6))}
                                    className="h-10 text-center tracking-[0.5em] text-lg font-mono bg-zinc-900 border-zinc-800 text-white placeholder:text-zinc-500"
                                    placeholder="000000"
                                />
                                {error && (
                                    <div className="text-xs text-red-400 text-center px-2">{error}</div>
                                )}
                                <Button 
                                    onClick={handleDisable2FA} 
                                    disabled={isLoading || totpCode.length !== 6}
                                    className="w-full bg-red-500/10 text-red-500 hover:bg-red-500/20 hover:text-red-400 border-red-500/20"
                                    variant="outline"
                                >
                                    {isLoading ? "Disabling..." : "Disable 2FA"}
                                </Button>
                            </div>
                        </div>
                    )}
                </div>
            </div>
        );
    }

    return (
        <div className="flex flex-col h-full bg-sidebar-background">
            <div className="px-3 py-2 border-b border-border/40 bg-card/20 shrink-0">
                <div className="flex items-center gap-2">
                    <button
                        onClick={onBack}
                        className={sidebarHeaderButtonClassName}
                        title="Back to sidebar"
                    >
                        <CaretLeft weight="bold" size={14} />
                    </button>
                    <div className={sidebarHeaderTitleClassName}>
                        <Cloud weight="fill" size={14} className="text-primary" />
                        Sync Access
                    </div>
                    <button
                        title="Settings"
                        onClick={() => navigate('/settings?tab=sync')}
                        className={sidebarHeaderButtonClassName}
                    >
                        <Gear weight="bold" size={14} />
                    </button>
                </div>
            </div>

            <ScrollArea className="flex-1 px-3 py-2">
                <div className="space-y-3">
                    <div className={sidebarSectionClassName}>
                        <div className="mb-3 flex items-start gap-2.5">
                            <div className={cn(
                                "flex h-9 w-9 shrink-0 items-center justify-center rounded-none border",
                                syncStatusIconToneClassName
                            )}>
                                {syncStatus === "error" ? (
                                    <Warning weight="fill" size={16} />
                                ) : (
                                    <CheckCircle weight="fill" size={16} />
                                )}
                            </div>
                            <div className="min-w-0 flex-1">
                                <div className="flex flex-wrap items-center gap-1.5">
                                    <h3 className="text-sm font-semibold text-foreground">Sync Status</h3>
                                    <span className={cn(
                                        "rounded-none border px-1.5 py-0.5 text-[9px] font-semibold uppercase tracking-[0.15em]",
                                        syncStatusBadgeClassName
                                    )}>
                                        {syncStatusLabel}
                                    </span>
                                </div>
                                <p className="mt-1 text-xs text-muted-foreground">
                                    {lastSyncTime
                                        ? `Last synced ${new Date(lastSyncTime).toLocaleString()}`
                                        : "No sync has been completed on this device yet."}
                                </p>
                            </div>
                        </div>

                        <div className="flex gap-2">
                            <Button 
                                variant="outline" 
                                className="flex-1 h-8 gap-1.5 rounded-none border-border bg-background/60 text-xs hover:bg-muted/50"
                                onClick={() => handleSync('push')}
                                disabled={syncStatus === 'syncing'}
                            >
                                <CloudArrowUp size={14} />
                                Push
                            </Button>
                            <Button 
                                variant="outline" 
                                className="flex-1 h-8 gap-1.5 rounded-none border-border bg-background/60 text-xs hover:bg-muted/50"
                                onClick={() => handleSync('pull')}
                                disabled={syncStatus === 'syncing'}
                            >
                                <CloudArrowDown size={14} />
                                Pull
                            </Button>
                        </div>

                        {(error || syncError) && (
                            <div className="mt-2 flex items-start gap-2 border border-red-500/20 bg-red-500/10 px-3 py-2 text-xs text-red-400">
                                <Warning weight="fill" size={14} />
                                <span className="min-w-0 break-words">{error || syncError}</span>
                            </div>
                        )}
                    </div>

                    <div className={sidebarSectionClassName}>
                        <div className="mb-2 flex items-start justify-between gap-2">
                            <div>
                                <div className={sidebarSectionEyebrowClassName}>Account</div>
                                <h3 className="mt-1 text-sm font-semibold text-foreground">Connected profile</h3>
                            </div>
                            {!isEditingName && (
                                <Button
                                    variant="ghost"
                                    size="sm"
                                    className="h-7 rounded-none px-2 text-xs text-muted-foreground hover:bg-red-500/10 hover:text-red-400"
                                    onClick={handleLogout}
                                    title="Sign Out"
                                >
                                    <SignOut size={14} className="mr-1.5" />
                                    Sign Out
                                </Button>
                            )}
                        </div>
                        <div className="group flex items-start gap-2.5 rounded-none border border-border bg-background/50 p-2.5 transition-colors hover:bg-accent/30">
                            <div className="flex h-8 w-8 shrink-0 items-center justify-center rounded-none border border-border bg-muted/30 text-muted-foreground">
                                <User weight="bold" size={16} />
                            </div>
                            <div className="flex-1 min-w-0">
                                {isEditingName ? (
                                    <div className="flex items-center gap-1">
                                        <Input
                                            value={editName}
                                            onChange={(e: ChangeEvent<HTMLInputElement>) => setEditName(e.target.value)}
                                            className="h-7 rounded-none border-border bg-background/70 text-sm"
                                            autoFocus
                                            onKeyDown={(e: KeyboardEvent<HTMLInputElement>) => {
                                                if (e.key === 'Enter') handleSaveName();
                                                if (e.key === 'Escape') setIsEditingName(false);
                                            }}
                                            onClick={(e: MouseEvent) => e.stopPropagation()}
                                        />
                                        <Button size="icon" variant="ghost" className="h-7 w-7 shrink-0 rounded-none text-green-500 hover:bg-green-500/10 hover:text-green-400" onClick={(e: MouseEvent) => { e.stopPropagation(); handleSaveName(); }} data-sound-confirm title="Save display name">
                                            <Check size={14} />
                                        </Button>
                                        <Button size="icon" variant="ghost" className="h-7 w-7 shrink-0 rounded-none text-red-400 hover:bg-red-500/10 hover:text-red-300" onClick={(e: MouseEvent) => { e.stopPropagation(); setIsEditingName(false); }} title="Cancel editing">
                                            <X size={14} />
                                        </Button>
                                    </div>
                                ) : (
                                    <>
                                        <div className="flex items-center justify-between gap-2">
                                            <span className="text-sm font-medium truncate text-foreground">
                                                {user.email && user.email !== accountId ? user.email : "Anonymous"}
                                            </span>
                                            <div className="flex items-center gap-1.5 opacity-0 group-hover:opacity-100 group-focus-within:opacity-100 transition-opacity shrink-0">
                                                <button 
                                                    className="text-muted-foreground hover:text-foreground transition-colors"
                                                    onClick={(e: MouseEvent) => { e.stopPropagation(); handleStartEditName(); }}
                                                    title="Edit display name"
                                                >
                                                    <PencilSimple size={13} />
                                                </button>

                                                <div className="w-[1px] h-3 bg-border/40 mx-0.5" />

                                                <button 
                                                    onClick={(e) => { e.stopPropagation(); setIsSyncIdRevealed(!isSyncIdRevealed); }}
                                                    className="text-muted-foreground hover:text-foreground transition-colors"
                                                    title={isSyncIdRevealed ? "Hide ID" : "Reveal ID"}
                                                >
                                                    {isSyncIdRevealed ? <EyeSlash size={13} /> : <Eye size={13} />}
                                                </button>
                                                <button 
                                                    onClick={(e) => { 
                                                        e.stopPropagation(); 
                                                        navigator.clipboard.writeText(accountId || user.id);
                                                    }}
                                                    className="text-muted-foreground hover:text-foreground transition-colors"
                                                    title="Copy ID"
                                                >
                                                    <Copy size={13} />
                                                </button>
                                            </div>
                                        </div>
                                        <div className="mt-1 min-w-0">
                                            <div className="truncate text-[11px] text-muted-foreground group-hover:text-foreground/80 transition-colors font-mono">
                                                {isSyncIdRevealed 
                                                    ? (accountId ? formatAccountId(accountId) : formatAccountId(user.id))
                                                    : "••••-••••-••••-••••"
                                                }
                                            </div>
                                        </div>
                                    </>
                                )}
                            </div>
                        </div>
                    </div>

                    <div className={sidebarSectionClassName}>
                        <div className="mb-2">
                            <div className={sidebarSectionEyebrowClassName}>Security</div>
                            <h3 className="mt-1 text-sm font-semibold text-foreground">Two-factor authentication</h3>
                        </div>
                        <div className="flex items-start justify-between gap-2.5 rounded-none border border-border bg-background/50 p-2.5 transition-colors hover:bg-accent/30">
                            <div className="flex min-w-0 items-center gap-2.5">
                                <div className={cn(
                                    "flex h-8 w-8 shrink-0 items-center justify-center rounded-none border",
                                    totpEnabled
                                        ? "border-green-500/30 bg-green-500/10 text-green-400"
                                        : "border-border bg-muted/30 text-muted-foreground"
                                )}>
                                    <ShieldCheck weight={totpEnabled ? "fill" : "regular"} size={16} />
                                </div>
                                <div className="min-w-0">
                                    <div className="text-sm font-medium text-foreground">Two-Factor Auth</div>
                                    <div className="text-[11px] text-muted-foreground">
                                        {totpEnabled ? "Extra verification is enabled." : "Add another layer of account security."}
                                    </div>
                                </div>
                            </div>
                            {totpEnabled ? (
                                <Button 
                                    variant="ghost" 
                                    size="sm" 
                                    className="h-7 shrink-0 rounded-none px-2 text-xs text-red-400 hover:bg-red-500/10 hover:text-red-300"
                                    onClick={() => {
                                        setSetupMode('disable');
                                        setShowTwoFactorSetup(true);
                                        setError(null);
                                        setTotpCode("");
                                    }}
                                >
                                    Disable
                                </Button>
                            ) : (
                                <Button 
                                    variant="ghost" 
                                    size="sm" 
                                    className="h-7 shrink-0 rounded-none px-2 text-xs text-primary hover:bg-primary/10 hover:text-primary"
                                    onClick={() => {
                                        setSetupMode('enable');
                                        setSetupStep('intro');
                                        setShowTwoFactorSetup(true);
                                        setError(null);
                                        setTotpCode("");
                                    }}
                                >
                                    Enable
                                </Button>
                            )}
                        </div>
                    </div>
                </div>
            </ScrollArea>
        </div>
    );
}

