}

export function SidebarTrash({
  onBack,
  variant = "sidebar",
}: SidebarTrashProps) {
  const {
    files,
    collections,
    graphs,
    docs,
    storages,
    activeProjectId,
    trashClearRange,
    restoreFile,
    permanentDeleteFile,
    restoreCollection,
    permanentDeleteCollection,
    restoreGraph,
    permanentDeleteGraph,
    restoreDoc,
    permanentDeleteDoc,
    restoreStorage,
    permanentDeleteStorage,
    emptyTrash,
    setTrashClearRange,
  } = useStore(
    useShallow((state: AppStore) => ({
      files: state.files,
      collections: state.collections,
      graphs: state.graphs,
      docs: state.docs,
      storages: state.storages,
      activeProjectId: state.activeProjectId,
      trashClearRange: state.trashClearRange ?? "all-time",
      restoreFile: state.restoreFile,
      permanentDeleteFile: state.permanentDeleteFile,
      restoreCollection: state.restoreCollection,
      permanentDeleteCollection: state.permanentDeleteCollection,
      restoreGraph: state.restoreGraph,
      permanentDeleteGraph: state.permanentDeleteGraph,
      restoreDoc: state.restoreDoc,
      permanentDeleteDoc: state.permanentDeleteDoc,
      restoreStorage: state.restoreStorage,
      permanentDeleteStorage: state.permanentDeleteStorage,
      emptyTrash: state.emptyTrash,
      setTrashClearRange: state.setTrashClearRange,
    })),
  );
  const navigate = useNavigate();
  const [trashRangeEvaluationTime, setTrashRangeEvaluationTime] = useState(0);

  const isSidebar = variant === "sidebar";
  const isSettingsPage = variant === "settings-page";
  const isSettingsShell = variant === "settings";

  const trashedFiles = useMemo(
    () =>
      files.filter(
        (file) => file.projectId === activeProjectId && file.deleted,
      ),
    [files, activeProjectId],
  );
  const trashedCollections = useMemo(
    () =>
      collections.filter(
        (collection) =>
          collection.projectId === activeProjectId && collection.deleted,
      ),
    [collections, activeProjectId],
  );
  const trashedStorages = useMemo(
    () =>
      storages.filter(
        (storage) => storage.projectId === activeProjectId && storage.deleted,
      ),
    [storages, activeProjectId],
  );
  const trashedGraphs = useMemo(
    () =>
      graphs.filter(
        (graph) => graph.projectId === activeProjectId && graph.deleted,
      ),
    [graphs, activeProjectId],
  );
  const trashedDocs = useMemo(
    () =>
      docs.filter((doc) => doc.projectId === activeProjectId && doc.deleted),
    [docs, activeProjectId],
  );

  const totalTrashCount =
    trashedStorages.length +
    trashedCollections.length +
    trashedFiles.length +
    trashedDocs.length +
    trashedGraphs.length;

  const deleteRangeCount = useMemo(() => {
    const now = trashRangeEvaluationTime;
    return [
      ...trashedStorages.filter((item) =>
        isTimestampInActivityRange(
          getDeletedTimestamp(item),
          trashClearRange,
          now,
        ),
      ),
      ...trashedCollections.filter((item) =>
        isTimestampInActivityRange(
          getDeletedTimestamp(item),
          trashClearRange,
          now,
        ),
      ),
      ...trashedFiles.filter((item) =>
        isTimestampInActivityRange(
          getDeletedTimestamp(item),
          trashClearRange,
          now,
        ),
      ),
      ...trashedDocs.filter((item) =>
        isTimestampInActivityRange(
          getDeletedTimestamp(item),
          trashClearRange,
          now,
        ),
      ),
      ...trashedGraphs.filter((item) =>
        isTimestampInActivityRange(
          getDeletedTimestamp(item),
          trashClearRange,
          now,
        ),
      ),
    ].length;
  }, [
    trashedStorages,
    trashedCollections,
    trashedFiles,
    trashedDocs,
    trashedGraphs,
    trashClearRange,
    trashRangeEvaluationTime,
  ]);

  const hasTrash = totalTrashCount > 0;
  const rangeLabel = getActivityClearRangeLabel(trashClearRange);
  const clearDescription =
    trashClearRange === "all-time"
      ? "This will permanently delete all items in the trash. This action cannot be undone."
      : `This will permanently delete trash items from ${rangeLabel.toLowerCase()}. This action cannot be undone.`;

  const emptyTrashDialog = hasTrash ? (
    <DestructiveConfirmDialog
      title="Empty trash?"
      description={clearDescription}
      subjectLabel="Delete"
      subjectContent={
        deleteRangeCount > 0
          ? `${deleteRangeCount} ${deleteRangeCount === 1 ? "trashed item" : "trashed items"}`
          : "No trashed items in this range"
      }
      extraContent={
        <RangeField value={trashClearRange} onChange={setTrashClearRange} />
      }
      confirmLabel={
        trashClearRange === "all-time" ? "Delete All" : "Delete Selected"
      }
      confirmDisabled={deleteRangeCount === 0}
      onConfirm={() =>
        emptyTrash({ projectId: activeProjectId, range: trashClearRange })
      }
      trigger={
        isSidebar ? (
          <button
            type="button"
            className={cn(
              sidebarHeaderButtonClassName,
              "text-red-400 hover:text-red-300",
            )}
            title="Empty trash"
            onClick={() => setTrashRangeEvaluationTime(Date.now())}
          >
            <Trash weight="fill" size={14} />
          </button>
        ) : (
          <Button
            variant="destructive"
            size="sm"
            onClick={() => setTrashRangeEvaluationTime(Date.now())}
          >
            Empty Trash
          </Button>
        )
      }
    />
  ) : null;

  const openTrashSettings = () => navigate("/settings?tab=trash");

  const renderHeader = () => {
    if (isSidebar) {
      return (
        <div className="px-3 py-2 border-b border-border/40 bg-card/20 shrink-0">
          <div className="flex items-center gap-2">
            <button
              type="button"
              onClick={onBack}
              className={sidebarHeaderButtonClassName}
              data-sound-back
              title="Back to sidebar"
            >
              <CaretLeft weight="bold" size={14} />
            </button>
            <div className="flex-1 flex items-center justify-center gap-2 text-sm font-semibold text-foreground">
              <Trash weight="fill" size={14} className="text-red-400" />
              Trash
            </div>
            <div className="flex items-center gap-1">
              {emptyTrashDialog}
              <button
                type="button"
                onClick={openTrashSettings}
                className={sidebarHeaderButtonClassName}
                title="Trash settings"
              >
                <Gear weight="bold" size={14} />
              </button>
            </div>
          </div>
        </div>
      );
    }

    const content = (
      <>
        <div>
          <h2 className="text-lg font-semibold flex items-center gap-2">
            <Trash className="text-primary" size={24} />
            Trash
          </h2>
          <p className="mt-1 text-xs text-muted-foreground">
            Review deleted items, restore them, or permanently remove recent
            trash in bulk.
          </p>
        </div>
        {emptyTrashDialog}
      </>
    );

    if (isSettingsShell) {
      return (
        <div className="p-4 border-b border-border flex items-center justify-between gap-3">
          {content}
        </div>
      );
    }

    return (
      <div className="mb-4 flex items-start justify-between gap-3">
        {content}
      </div>
    );
  };

  const Wrapper = isSettingsPage ? "div" : ScrollArea;
  const wrapperClass = isSettingsPage
    ? ""
    : isSidebar
      ? "flex-1 min-h-0 px-3 py-3 overflow-y-auto"
      : "flex-1 min-h-0 p-4 overflow-y-auto";
  const containerClass = cn(
    isSettingsPage ? "space-y-4" : "flex flex-col h-full min-h-0",
    isSidebar ? "bg-sidebar-background" : "bg-transparent",
  );

  const Section = ({
    title,
    count,
    children,
  }: {
    title: string;
    count: number;
    children: ReactNode;
  }) => (
    <section
      className={cn(
        "w-full min-w-0 overflow-hidden rounded-none border border-border bg-card/50",
        isSidebar ? "p-2.5" : "p-5",
      )}
    >
      <div className="mb-3 flex items-center justify-between gap-2">
        <h3
          className={cn(
            "font-semibold text-foreground",
            isSidebar ? "text-xs" : "text-sm",
          )}
        >
          {title}
        </h3>
        <span className="rounded-none border border-border bg-background/70 px-1.5 py-0.5 text-[9px] font-semibold uppercase tracking-[0.15em] text-muted-foreground">
          {count}
        </span>
      </div>
      <div className={isSidebar ? "space-y-1.5" : "space-y-2"}>{children}</div>
    </section>
  );

  return (
    <div className={containerClass}>
      {renderHeader()}

      <Wrapper className={wrapperClass}>
        <div
          className={cn(
            "w-full min-w-0 space-y-4",
            !isSettingsPage && "min-h-full",
          )}
        >
          {!hasTrash ? (
            <div
              className={cn(
                "rounded-none border text-center text-muted-foreground",
                isSidebar
                  ? "border-border bg-card/40 p-4"
                  : "border-dashed border-border bg-card/30 p-8",
              )}
            >
              <div className="inline-flex h-12 w-12 items-center justify-center rounded-none bg-muted/50 mb-4">
                <Trash size={24} className="opacity-50" />
              </div>
              <p className="text-sm font-medium">Trash is empty</p>
              <p className="mt-1 text-xs text-muted-foreground">
                Deleted items will appear here until they are restored or
                permanently removed.
              </p>
            </div>
          ) : (
            <div className={isSidebar ? "space-y-3" : "space-y-4"}>
              {trashedStorages.length > 0 && (
                <Section title="Storages" count={trashedStorages.length}>
                  {trashedStorages.map((storage: Storage) => (
                    <TrashItemRow
                      key={storage.id}
                      icon={HardDrives}
                      name={storage.name}
                      date={getDeletedTimestamp(storage)}
                      color={storage.color}
                      entityLabel="Storage"
                      variant={variant}
                      onRestore={() => restoreStorage(storage.id)}
                      onDelete={() => permanentDeleteStorage(storage.id)}
                    />
                  ))}
                </Section>
              )}

              {trashedCollections.length > 0 && (
                <Section title="Collections" count={trashedCollections.length}>
                  {trashedCollections.map((collection: Collection) => (
                    <TrashItemRow
                      key={collection.id}
                      icon={Folder}
                      name={collection.name}
                      date={getDeletedTimestamp(collection)}
                      color={collection.color}
                      entityLabel={
                        collection.type === "bucket"
                          ? "Bucket"
                          : collection.type === "folder"
                            ? "Folder"
                            : "Collection"
                      }
                      variant={variant}
                      onRestore={() => restoreCollection(collection.id)}
                      onDelete={() => permanentDeleteCollection(collection.id)}
                    />
                  ))}
                </Section>
              )}

              {trashedFiles.length > 0 && (
                <Section title="Files" count={trashedFiles.length}>
                  {trashedFiles.map((file: File) => (
                    <TrashItemRow
                      key={file.id}
                      icon={FileText}
                      name={file.name}
                      date={getDeletedTimestamp(file)}
                      entityLabel="File"
                      variant={variant}
                      onRestore={() => restoreFile(file.id)}
                      onDelete={() => permanentDeleteFile(file.id)}
                    />
                  ))}
                </Section>
              )}

              {trashedDocs.length > 0 && (
                <Section title="Docs" count={trashedDocs.length}>
                  {trashedDocs.map((doc: Doc) => (
                    <TrashItemRow
                      key={doc.id}
                      icon={getIcon(doc.icon)}
                      name={doc.name}
                      date={getDeletedTimestamp(doc)}
                      color={doc.color}
                      entityLabel="Document"
                      variant={variant}
                      onRestore={() => restoreDoc(doc.id)}
                      onDelete={() => permanentDeleteDoc(doc.id)}
                    />
                  ))}
                </Section>
              )}

              {trashedGraphs.length > 0 && (
                <Section title="Graphs" count={trashedGraphs.length}>
                  {trashedGraphs.map((graph: GraphType) => (
                    <TrashItemRow
                      key={graph.id}
                      icon={getIcon(graph.icon)}
                      name={graph.name}
                      date={getDeletedTimestamp(graph)}
                      color={graph.color}
                      entityLabel="Graph"
                      variant={variant}
                      onRestore={() => restoreGraph(graph.id)}
                      onDelete={() => permanentDeleteGraph(graph.id)}
                    />
                  ))}
                </Section>
              )}
            </div>
          )}
        </div>
      </Wrapper>
    </div>
  );
}

/**
 * SlimSidebar.tsx
 *
 * Collapsed icon-only sidebar mode. Renders a vertical strip of icon buttons
 * for quick navigation to Home, Storage, Docs, Graphs, Collections, and
 * utility views (Sync, History, Trash, Settings).
 *
 * Also shows bucket icons from the active project's collection tree.
 *
 * All buttons use squared styling with border/shadow matching the expanded
 * sidebar's search and collapse buttons.
 */

import type { MouseEvent as ReactMouseEvent, ReactNode } from "react";
import { useLocation, useNavigate } from "react-router-dom";
import {
    SidebarSimple,
    HardDrives,
    NotePencil,
    Graph,
    FolderOpen,
    Folder,
    Trash,
    MagnifyingGlass,
    ArrowsClockwise,
    PencilSimple,
    ClockCounterClockwise,
    Gear,
    House,
} from "@phosphor-icons/react";
import { cn } from "@/lib/utils";
import { useStore } from "@/store/useStore";
import { useShallow } from "@/lib/zustand-shallow";
import { getIcon } from "@/utils/iconMap";
import { playSfx } from "@/utils/sound";
import type { Collection } from "@/types";

import {
    ContextMenu,
    ContextMenuContent,
    ContextMenuItem,
    ContextMenuSeparator,
    ContextMenuTrigger,
} from "@/components/ui/context-menu";
import {
    Tooltip,
    TooltipContent,
    TooltipTrigger,
} from "@/components/ui/tooltip";
import { ScrollArea } from "@/components/ui/scroll-area";
import { PiPPlayer } from "@/components/player/PiPPlayer";

const BTN = "h-8 w-8 flex items-center justify-center rounded-none border border-border/60 shadow-sm bg-secondary/40 text-muted-foreground hover:bg-secondary/60 hover:text-foreground transition-all duration-200";
const BTN_ACTIVE = "h-8 w-8 flex items-center justify-center rounded-none border shadow-sm transition-all duration-200 bg-primary/20 text-primary border-primary/30";
const NAV_BTN = "h-9 w-9 flex items-center justify-center rounded-none border border-border/60 shadow-sm bg-secondary/40 text-muted-foreground hover:bg-secondary/60 hover:text-foreground transition-all duration-200";
const NAV_BTN_ACTIVE = "h-9 w-9 flex items-center justify-center rounded-none border shadow-sm transition-all duration-200 bg-primary/20 text-primary border-primary/30";

interface SlimSidebarProps {
    handleSelectCollection: (id: string) => void;
    onEditCollection: (collection: Collection) => void;
    onCreateStorage: () => void;
    onCreateDoc: () => void;
    onCreateGraph: () => void;
    onCreateBucket: () => void;
}

interface SidebarIconButtonProps {
    tooltip: string;
    buttonClassName: string;
    onClick: () => void;
    menuItems: ReactNode;
    children: ReactNode;
}

function SidebarIconButton({ tooltip, buttonClassName, onClick, menuItems, children }: SidebarIconButtonProps) {
    return (
        <ContextMenu>
            <ContextMenuTrigger className="flex w-full justify-center">
                <Tooltip>
                    <TooltipTrigger asChild>
                        <button type="button" onClick={onClick} className={buttonClassName}>
                            {children}
                        </button>
                    </TooltipTrigger>
                    <TooltipContent side="right">{tooltip}</TooltipContent>
                </Tooltip>
            </ContextMenuTrigger>
            <ContextMenuContent side="right" align="start" sideOffset={8} className="min-w-[10rem]">
                {menuItems}
            </ContextMenuContent>
        </ContextMenu>
    );
}

export function SlimSidebar({
    handleSelectCollection,
    onEditCollection,
    onCreateStorage,
    onCreateDoc,
    onCreateGraph,
    onCreateBucket,
}: SlimSidebarProps) {
    const navigate = useNavigate();
    const location = useLocation();

    const {
        collections,
        activeCollectionId,
        activeProjectId,
        toggleSidebarCollapse,
        setSidebarView,
        syncStatus,
        trashCollection,
        isPipOpen,
        pipFileId,
    } = useStore(useShallow((state) => ({
        collections: state.collections,
        activeCollectionId: state.activeCollectionId,
        activeProjectId: state.activeProjectId,
        toggleSidebarCollapse: state.toggleSidebarCollapse,
        setSidebarView: state.setSidebarView,
        syncStatus: state.syncStatus,
        trashCollection: state.trashCollection,
        isPipOpen: state.isPipOpen,
        pipFileId: state.pipFileId,
    })));

    const isHome = location.pathname === "/";
    const isStorage = location.pathname === "/storage";
    const isDocs = location.pathname.startsWith("/docs");
    const isGraphs = location.pathname.startsWith("/graphs");
    const isCollectionsRoot = location.pathname.startsWith("/collections");
    const isSettings = location.pathname === "/settings";
    const projectBuckets = collections.filter(
        (c: Collection) => c.projectId === activeProjectId && c.parentId === null && c.type === "bucket" && !c.deleted
    );
    const activeBucket = projectBuckets.find((b) => b.id === activeCollectionId) || projectBuckets[0] || null;
    const ActiveBucketIcon = activeBucket?.icon ? getIcon(activeBucket.icon) : Folder;
    const recentCollections = collections
        .filter((c: Collection) => c.projectId === activeProjectId && c.type === "collection" && !c.deleted)
        .sort((a: Collection, b: Collection) => {
            const aTime = Math.max(a.lastViewed || 0, a.lastModified || 0, a.created || 0);
            const bTime = Math.max(b.lastViewed || 0, b.lastModified || 0, b.created || 0);
            return bTime - aTime;
        })
        .slice(0, 12);

    const handleOpenCollections = () => {
        if (isCollectionsRoot) {
            toggleSidebarCollapse();
            setSidebarView("collections");
            return;
        }

        if (!activeCollectionId && projectBuckets.length > 0) {
            handleSelectCollection(projectBuckets[0].id);
        }
        navigate("/collections");
    };

    const handleExpandSidebar = () => {
        playSfx("cursor");
        toggleSidebarCollapse();
    };

    const handleCreateStorageAction = () => {
        playSfx("cursor");
        onCreateStorage();
    };

    const handleCreateDocAction = () => {
        playSfx("cursor");
        onCreateDoc();
    };

    const handleCreateGraphAction = () => {
        playSfx("cursor");
        onCreateGraph();
    };

    const handleCreateBucketAction = () => {
        playSfx("cursor");
        onCreateBucket();
    };

    const handleOpenHome = () => {
        playSfx("cursor");
        navigate("/");
        setSidebarView("main");
    };

    const handleOpenSearch = () => {
        playSfx("cursor");
        useStore.getState().setSpotlightOpen(true);
    };

    const handleOpenStorage = () => {
        playSfx("cursor");
        if (isStorage) {
            toggleSidebarCollapse();
            setSidebarView("storage");
            return;
        }
        navigate("/storage");
    };

    const handleOpenDocs = () => {
        playSfx("cursor");
        if (isDocs) {
            toggleSidebarCollapse();
            setSidebarView("docs");
            return;
        }
        navigate("/docs");
    };

    const handleOpenGraphs = () => {
        playSfx("cursor");
        if (isGraphs) {
            toggleSidebarCollapse();
            setSidebarView("graphs");
            return;
        }
        navigate("/graphs");
    };

    const handleOpenCollectionsAction = () => {
        playSfx("cursor");
        handleOpenCollections();
    };

    const handleOpenBucketManager = () => {
        playSfx("cursor");
        setSidebarView("collections");
        toggleSidebarCollapse();
    };

    const handleOpenSync = () => {
        playSfx("cursor");
        setSidebarView("sync");
        toggleSidebarCollapse();
    };

    const handleOpenHistory = () => {
        playSfx("cursor");
        setSidebarView("history");
        toggleSidebarCollapse();
    };

    const handleOpenTrash = () => {
        playSfx("cursor");
        setSidebarView("trash");
        toggleSidebarCollapse();
    };

    const handleOpenSettings = () => {
        playSfx("cursor");
        navigate("/settings");
    };

    return (
        <div className="flex h-full min-h-0 w-full flex-col items-center gap-1.5 py-2">
            <SidebarIconButton
                tooltip="Expand Sidebar"
                buttonClassName={BTN}
                onClick={handleExpandSidebar}
                menuItems={
                    <ContextMenuItem onClick={handleExpandSidebar}>
                        <SidebarSimple weight="bold" size={16} />
                        Expand Sidebar
                    </ContextMenuItem>
                }
            >
                <SidebarSimple weight="bold" size={18} />
            </SidebarIconButton>

            <SidebarIconButton
                tooltip="Home"
                buttonClassName={isHome ? NAV_BTN_ACTIVE : NAV_BTN}
                onClick={handleOpenHome}
                menuItems={
                    <>
                        <ContextMenuItem onClick={handleOpenHome}>
                            <House weight="bold" size={16} />
                            Go Home
                        </ContextMenuItem>
                        <ContextMenuSeparator />
                        <ContextMenuItem onClick={handleExpandSidebar}>
                            <SidebarSimple weight="bold" size={16} />
                            Expand Sidebar
                        </ContextMenuItem>
                    </>
                }
            >
                <House weight={isHome ? "fill" : "bold"} size={20} />
            </SidebarIconButton>

            <SidebarIconButton
                tooltip="Search"
                buttonClassName={BTN}
                onClick={handleOpenSearch}
                menuItems={
                    <>
                        <ContextMenuItem onClick={handleOpenSearch}>
                            <MagnifyingGlass weight="bold" size={16} />
                            Open Search
                        </ContextMenuItem>
                        <ContextMenuSeparator />
                        <ContextMenuItem onClick={handleExpandSidebar}>
                            <SidebarSimple weight="bold" size={16} />
                            Expand Sidebar
                        </ContextMenuItem>
                    </>
                }
            >
                <MagnifyingGlass weight="bold" size={18} />
            </SidebarIconButton>

            <div className="my-0.5 h-px w-6 bg-border/40" />

            <div className="flex w-full flex-col items-center gap-1.5">
                <SidebarIconButton
                    tooltip="Storage"
                    buttonClassName={isStorage ? NAV_BTN_ACTIVE : NAV_BTN}
                    onClick={handleOpenStorage}
                    menuItems={
                        <>
                            <ContextMenuItem onClick={handleOpenStorage}>
                                <HardDrives weight="bold" size={16} />
                                Open Storage
                            </ContextMenuItem>
                            <ContextMenuItem onClick={handleCreateStorageAction} disabled={!activeProjectId}>
                                <HardDrives weight="bold" size={16} />
                                Create Storage
                            </ContextMenuItem>
                            <ContextMenuSeparator />
                            <ContextMenuItem onClick={handleExpandSidebar}>
                                <SidebarSimple weight="bold" size={16} />
                                Expand Sidebar
                            </ContextMenuItem>
                        </>
                    }
                >
                    <HardDrives weight={isStorage ? "fill" : "bold"} size={20} />
                </SidebarIconButton>

                <SidebarIconButton
                    tooltip="Docs"
                    buttonClassName={isDocs ? NAV_BTN_ACTIVE : NAV_BTN}
                    onClick={handleOpenDocs}
                    menuItems={
                        <>
                            <ContextMenuItem onClick={handleOpenDocs}>
                                <NotePencil weight="bold" size={16} />
                                Open Docs
                            </ContextMenuItem>
                            <ContextMenuItem onClick={handleCreateDocAction} disabled={!activeProjectId}>
                                <NotePencil weight="bold" size={16} />
                                Create Document
                            </ContextMenuItem>
                            <ContextMenuSeparator />
                            <ContextMenuItem onClick={handleExpandSidebar}>
                                <SidebarSimple weight="bold" size={16} />
                                Expand Sidebar
                            </ContextMenuItem>
                        </>
                    }
                >
                    <NotePencil weight={isDocs ? "fill" : "bold"} size={20} />
                </SidebarIconButton>

                <SidebarIconButton
                    tooltip="Graphs"
                    buttonClassName={isGraphs ? NAV_BTN_ACTIVE : NAV_BTN}
                    onClick={handleOpenGraphs}
                    menuItems={
                        <>
                            <ContextMenuItem onClick={handleOpenGraphs}>
                                <Graph weight="bold" size={16} />
                                Open Graphs
                            </ContextMenuItem>
                            <ContextMenuItem onClick={handleCreateGraphAction} disabled={!activeProjectId}>
                                <Graph weight="bold" size={16} />
                                Create Graph
                            </ContextMenuItem>
                            <ContextMenuSeparator />
                            <ContextMenuItem onClick={handleExpandSidebar}>
                                <SidebarSimple weight="bold" size={16} />
                                Expand Sidebar
                            </ContextMenuItem>
                        </>
                    }
                >
                    <Graph weight={isGraphs ? "fill" : "bold"} size={20} />
                </SidebarIconButton>
            </div>

            <div className="my-0.5 h-px w-6 bg-border/40" />

            <ScrollArea className="flex-1 min-h-0 w-full px-1">
                <div className="flex w-full flex-col items-center gap-1.5 py-1">
                    <SidebarIconButton
                        tooltip={activeBucket ? activeBucket.name : "Collections Root"}
                        buttonClassName={isCollectionsRoot ? NAV_BTN_ACTIVE : NAV_BTN}
                        onClick={handleOpenCollectionsAction}
                        menuItems={
                            <>
                                <ContextMenuItem onClick={handleOpenCollectionsAction}>
                                    <FolderOpen weight="bold" size={16} />
                                    Open Collections
                                </ContextMenuItem>
                                <ContextMenuItem onClick={handleOpenBucketManager}>
                                    <Folder weight="bold" size={16} />
                                    Manage Buckets
                                </ContextMenuItem>
                                <ContextMenuItem onClick={handleCreateBucketAction} disabled={!activeProjectId}>
                                    <FolderOpen weight="bold" size={16} />
                                    Create Bucket
                                </ContextMenuItem>
                                <ContextMenuSeparator />
                                <ContextMenuItem onClick={handleExpandSidebar}>
                                    <SidebarSimple weight="bold" size={16} />
                                    Expand Sidebar
                                </ContextMenuItem>
                            </>
                        }
                    >
                        {activeBucket ? (
                            <div style={{ color: activeBucket.color }}>
                                <ActiveBucketIcon weight="fill" size={20} />
                            </div>
                        ) : (
                            <FolderOpen weight={isCollectionsRoot ? "fill" : "bold"} size={20} />
                        )}
                    </SidebarIconButton>

                    {recentCollections.map((collection: Collection) => {
                        const Icon = getIcon(collection.icon);
                        const isActive = location.pathname === `/collection/${collection.id}`;

                        return (
                            <ContextMenu key={collection.id}>
                                <ContextMenuTrigger className="flex w-full justify-center">
                                    <Tooltip>
                                        <TooltipTrigger asChild>
                                            <button
                                                type="button"
                                                onClick={() => {
                                                    playSfx("cursor");
                                                    handleSelectCollection(collection.id);
                                                    navigate(`/collection/${collection.id}`);
                                                }}
                                                className={cn(
                                                    isActive ? NAV_BTN_ACTIVE : NAV_BTN,
                                                    "relative"
                                                )}
                                            >
                                                <div style={{ color: collection.color }}>
                                                    <Icon className="text-lg" weight="fill" />
                                                </div>
                                            </button>
                                        </TooltipTrigger>
                                        <TooltipContent side="right">{collection.name}</TooltipContent>
                                    </Tooltip>
                                </ContextMenuTrigger>
                                <ContextMenuContent side="bottom" align="start" sideOffset={4} className="min-w-[8rem]">
                                    <ContextMenuItem
                                        onClick={(e: ReactMouseEvent) => {
                                            e.preventDefault();
                                            e.stopPropagation();
                                            onEditCollection(collection);
                                        }}
                                    >
                                        <PencilSimple className="mr-2 h-4 w-4" />
                                        Rename Collection
                                    </ContextMenuItem>
                                    <ContextMenuItem
                                        onClick={(e: ReactMouseEvent) => {
                                            e.preventDefault();
                                            e.stopPropagation();
                                            trashCollection(collection.id);
                                        }}
                                        className="text-red-500 focus:text-red-500"
                                    >
                                        <Trash className="mr-2 h-4 w-4" />
                                        Delete Collection
                                    </ContextMenuItem>
                                </ContextMenuContent>
                            </ContextMenu>
                        );
                    })}
                </div>
            </ScrollArea>

            <div className="my-0.5 h-px w-6 bg-border/40" />

            {isPipOpen && pipFileId && (
                <div className="w-full px-1 pb-1">
                    <PiPPlayer isCollapsed={true} />
                </div>
            )}

            <div className="flex w-full flex-col items-center gap-1.5 pb-1">
                <SidebarIconButton
                    tooltip="Sync Status"
                    buttonClassName={BTN}
                    onClick={handleOpenSync}
                    menuItems={
                        <>
                            <ContextMenuItem onClick={handleOpenSync}>
                                <ArrowsClockwise weight="bold" size={16} className={cn(syncStatus === "syncing" && "animate-spin text-primary")} />
                                Open Sync
                            </ContextMenuItem>
                            <ContextMenuSeparator />
                            <ContextMenuItem onClick={handleExpandSidebar}>
                                <SidebarSimple weight="bold" size={16} />
                                Expand Sidebar
                            </ContextMenuItem>
                        </>
                    }
                >
                    <ArrowsClockwise
                        weight="bold"
                        size={18}
                        className={cn(syncStatus === "syncing" && "animate-spin text-primary")}
                    />
                </SidebarIconButton>

                <SidebarIconButton
                    tooltip="History"
                    buttonClassName={BTN}
                    onClick={handleOpenHistory}
                    menuItems={
                        <>
                            <ContextMenuItem onClick={handleOpenHistory}>
                                <ClockCounterClockwise weight="bold" size={16} />
                                Open History
                            </ContextMenuItem>
                            <ContextMenuSeparator />
                            <ContextMenuItem onClick={handleExpandSidebar}>
                                <SidebarSimple weight="bold" size={16} />
                                Expand Sidebar
                            </ContextMenuItem>
                        </>
                    }
                >
                    <ClockCounterClockwise weight="bold" size={18} />
                </SidebarIconButton>

                <SidebarIconButton
                    tooltip="Trash"
                    buttonClassName={BTN}
                    onClick={handleOpenTrash}
                    menuItems={
                        <>
                            <ContextMenuItem onClick={handleOpenTrash}>
                                <Trash weight="bold" size={16} />
                                Open Trash
                            </ContextMenuItem>
                            <ContextMenuSeparator />
                            <ContextMenuItem onClick={handleExpandSidebar}>
                                <SidebarSimple weight="bold" size={16} />
                                Expand Sidebar
                            </ContextMenuItem>
                        </>
                    }
                >
                    <Trash weight="bold" size={18} />
                </SidebarIconButton>

                <SidebarIconButton
                    tooltip="Settings"
                    buttonClassName={isSettings ? BTN_ACTIVE : BTN}
                    onClick={handleOpenSettings}
                    menuItems={
                        <>
                            <ContextMenuItem onClick={handleOpenSettings}>
                                <Gear weight="bold" size={16} />
                                Open Settings
                            </ContextMenuItem>
                            <ContextMenuSeparator />
                            <ContextMenuItem onClick={handleExpandSidebar}>
                                <SidebarSimple weight="bold" size={16} />
                                Expand Sidebar
                            </ContextMenuItem>
                        </>
                    }
                >
                    <Gear weight="fill" size={18} />
                </SidebarIconButton>
            </div>
        </div>
    );
}

/**
 * ============================================================================
 * SORTABLE COLLECTION ITEM
 * ============================================================================
 *
 * A drag-sortable collection/bucket item displayed in the sidebar tree.
 * Shows the collection icon (colored), name, and hover-reveal edit/delete
 * buttons. Active/selected state uses primary theme colors.
 *
 * Features:
 *  - Drag-and-drop reordering via @dnd-kit
 *  - Right-click context menu for rename/delete
 *  - Active state detection via URL path and folder context
 *  - Bucket vs collection distinction in context menu labels
 *
 * Used by: ProjectSidebar collection tree (main view + buckets view)
 * ============================================================================
 */

import type { MouseEvent as ReactMouseEvent } from "react";
import { useNavigate } from "react-router-dom";
import { PencilSimple, Trash } from "@phosphor-icons/react";
import { useSortable } from '@dnd-kit/sortable';
import { CSS } from '@dnd-kit/utilities';
import { cn } from "@/lib/utils";
import { useStore } from "@/store/useStore";
import { useShallow } from "@/lib/zustand-shallow";
import { getIcon } from "@/utils/iconMap";
import { playSfx } from "@/utils/sound";
import {
    ContextMenu,
    ContextMenuContent,
    ContextMenuItem,
    ContextMenuTrigger,
} from "@/components/ui/context-menu";
import { CollectionContextMenu } from "@/components/views/CollectionsView";
import type { Collection } from "@/types";

/** Props for the sortable collection item */
interface SortableCollectionItemProps {
    /** The collection data object */
    collection: Collection;
    /** Current react-router location object */
    location: { pathname: string };
    /** Whether the sidebar is in slim/collapsed mode */
    isSlim: boolean;
    /** Handler to set the active collection (navigates to its root bucket) */
    handleSelectCollection: (id: string) => void;
    /** Handler for the edit button click */
    handleEditCollectionClick: (e: ReactMouseEvent, collection: Collection) => void;
    /** Handler for the delete button click */
    handleDeleteCollection: (e: ReactMouseEvent, id: string) => void;
    /** Setter for the collection being edited (used by context menu) */
    setCollectionToEdit: (c: Collection) => void;
    /** Setter to open the edit collection dialog (used by context menu) */
    setEditCollectionOpen: (open: boolean) => void;
    /** Store action to soft-delete a collection (used by context menu) */
    trashCollection: (id: string) => void;
    /** Handler called when user chooses "Move to" from context menu */
    onMove?: (collection: Collection) => void;
    /** Context menu content for create actions (unused in this component's own menu) */
    createMenuContent: React.ReactNode;
    /** Currently active folder ID from URL search params, for active state detection */
    currentFolderId?: string | null;
}

export function SortableCollectionItem({
    collection,
    location,
    isSlim,
    handleSelectCollection,
    handleEditCollectionClick,
    handleDeleteCollection,
    setCollectionToEdit,
    setEditCollectionOpen,
    trashCollection,
    onMove,
    currentFolderId = null,
}: SortableCollectionItemProps) {
    const navigate = useNavigate();

    const { activeCollectionId } = useStore(useShallow((state) => ({
        activeCollectionId: state.activeCollectionId
    })));

    const {
        attributes,
        listeners,
        setNodeRef,
        transform,
        transition,
        isDragging
    } = useSortable({ id: collection.id });

    const style = {
        transform: CSS.Transform.toString(transform),
        transition,
        opacity: isDragging ? 0.5 : 1,
        zIndex: isDragging ? 50 : "auto",
        position: "relative" as const,
    };

    const Icon = getIcon(collection.icon);

    // Determine if this collection is currently active
    const isActive = (() => {
        if (collection.type === 'bucket') {
            return location.pathname === `/collections` && activeCollectionId === collection.id;
        }
        return (
            location.pathname === `/collection/${collection.id}` ||
            (location.pathname === `/collections` && currentFolderId === collection.id)
        );
    })();

    return (
        <div ref={setNodeRef} style={style}>
            <ContextMenu>
                <ContextMenuTrigger className="block w-full" asChild>
                    <div
                        onClick={(e: ReactMouseEvent) => {
                            playSfx('cursor');
                            handleSelectCollection(collection.id);
                            if (collection.type === 'bucket') {
                                navigate(`/collections`);
                            } else {
                                navigate(`/collection/${collection.id}`);
                            }
                        }}
                        {...attributes}
                        {...listeners}
                        role="button"
                        tabIndex={0}
                        data-no-sfx
                        onKeyDown={(e) => {
                            if (e.key === 'Enter' || e.key === ' ') {
                                e.preventDefault();
                                handleSelectCollection(collection.id);
                                if (collection.type === 'bucket') {
                                    navigate(`/collections`);
                                } else {
                                    navigate(`/collection/${collection.id}`);
                                }
                            }
                        }}
                        className="block w-full group/item cursor-pointer outline-none focus-visible:ring-1 focus-visible:ring-ring"
                        title={isSlim ? collection.name : undefined}
                    >
                        <div className={cn(
                            "flex items-center gap-3 pl-3 pr-0 py-0 rounded-none text-sm transition-all relative border shadow-sm h-7 overflow-hidden",
                            isSlim && "justify-center px-1",
                            isActive
                                ? "bg-primary/20 text-primary border-primary/30"
                                : "bg-secondary/10 text-muted-foreground border-border/20 hover:bg-secondary/30 hover:text-foreground hover:border-border/40"
                        )}>
                            {/* Collection icon (always filled, colored) */}
                            <div style={{ color: collection.color }}>
                                <Icon className="text-lg transition-colors" weight="fill" />
                            </div>

                            {/* Collection name (hidden in slim mode) */}
                            {!isSlim && (
                                <span
                                    className="truncate w-0 flex-1 py-2 max-w-[calc(100%-50px)] group-hover/item:max-w-[calc(100%-95px)]"
                                >
                                    {collection.name}
                                </span>
                            )}

                            {/* Hover-reveal action buttons (hidden in slim mode) */}
                            {!isSlim && (
                                <div className="absolute inset-y-0 right-0 flex items-center h-full gap-1 opacity-0 group-hover/item:opacity-100 transition-opacity pr-1">
                                    <button
                                        onPointerDown={(e: ReactMouseEvent) => e.stopPropagation()}
                                        onClick={(e: ReactMouseEvent) => {
                                            playSfx('cursor');
                                            handleEditCollectionClick(e, collection);
                                        }}
                                        className="h-5 w-5 flex items-center justify-center rounded-none border border-border/60 shadow-sm bg-secondary/40 text-muted-foreground hover:bg-secondary/60 hover:text-foreground transition-all duration-200"
                                        title="Edit Collection"
                                    >
                                        <PencilSimple weight="bold" size={12} />
                                    </button>
                                    <button
                                        onPointerDown={(e: ReactMouseEvent) => e.stopPropagation()}
                                        onClick={(e: ReactMouseEvent) => {
                                            playSfx('cursor');
                                            handleDeleteCollection(e, collection.id);
                                        }}
                                        className="h-5 w-5 flex items-center justify-center rounded-none border border-border/60 shadow-sm bg-secondary/40 text-muted-foreground hover:bg-secondary/60 hover:text-foreground transition-all duration-200"
                                        title="Delete Collection"
                                    >
                                        <Trash weight="bold" size={12} />
                                    </button>
                                </div>
                            )}
                        </div>
                    </div>
                </ContextMenuTrigger>

                {/* Right-click context menu */}
                <CollectionContextMenu
                    collection={collection}
                    onNavigate={(id) => {
                        handleSelectCollection(id);
                        if (collection.type === 'bucket') {
                            navigate('/collections');
                        } else {
                            navigate(`/collection/${id}`);
                        }
                    }}
                    onRename={(c) => {
                        setCollectionToEdit(c);
                        setEditCollectionOpen(true);
                    }}
                    onDelete={(id) => trashCollection(id)}
                    onColorChange={(c, color) => {
                        useStore.getState().updateCollection(c.id, { color, lastModified: Date.now() });
                    }}
                    onIconChange={(c, icon) => {
                        useStore.getState().updateCollection(c.id, { icon, lastModified: Date.now() });
                    }}
                    onMove={onMove}
                />
            </ContextMenu>
        </div>
    );
}

/**
 * ============================================================================
 * SORTABLE ENTITY ITEM — Generic drag-sortable sidebar list item
 * ============================================================================
 *
 * A reusable sortable list item used for Storages, Docs, and Graphs in the
 * sidebar sub-views. Each entity type uses the same draggable layout pattern
 * with an icon, name, and hover-reveal edit/delete action buttons.
 *
 * Props:
 *  - entity:    The data object (must have id, name; optionally icon, color)
 *  - isActive:  Whether this item is the currently selected entity
 *  - onSelect:  Called when the item row is clicked
 *  - onEdit:    Called when the pencil button is clicked (receives MouseEvent)
 *  - onDelete:  Called when the trash button is clicked (receives MouseEvent)
 *  - dataAttrs: Optional data attributes to spread on the root element
 *
 * Used by: SidebarStorageView, SidebarDocView, SidebarGraphView
 * ============================================================================
 */

import type { MouseEvent as ReactMouseEvent } from "react";
import { PencilSimple, Trash } from "@phosphor-icons/react";
import { useSortable } from '@dnd-kit/sortable';
import { CSS } from '@dnd-kit/utilities';
import { cn } from "@/lib/utils";
import { getIcon } from "@/utils/iconMap";

/** Props for the generic sortable entity item */
interface SortableEntityItemProps {
    /** The entity data (storage, doc, or graph) */
    entity: {
        id: string;
        name: string;
        icon?: string;
        color?: string;
    };
    /** Whether this entity is currently active/selected */
    isActive: boolean;
    /** Called when the item row is clicked to select it */
    onSelect: () => void;
    /** Called when the edit (pencil) button is clicked */
    onEdit: (e: ReactMouseEvent) => void;
    /** Called when the delete (trash) button is clicked */
    onDelete: (e: ReactMouseEvent) => void;
    /** Optional data attributes to attach to the root element (e.g. data-doc-id) */
    dataAttrs?: Record<string, string>;
}

export function SortableEntityItem({
    entity,
    isActive,
    onSelect,
    onEdit,
    onDelete,
    dataAttrs = {},
}: SortableEntityItemProps) {
    const {
        attributes,
        listeners,
        setNodeRef,
        transform,
        transition,
        isDragging,
    } = useSortable({ id: entity.id });

    const style = {
        transform: CSS.Transform.toString(transform),
        transition,
        opacity: isDragging ? 0.5 : 1,
    };

    const Icon = getIcon(entity.icon);

    return (
        <div
            ref={setNodeRef}
            style={style}
            {...attributes}
            {...listeners}
            {...dataAttrs}
            onClick={onSelect}
            className={cn(
                "w-full flex items-center gap-2 pl-2 pr-0 py-0 text-[11px] font-semibold tracking-wider rounded-none transition-all group border shadow-sm relative h-7 cursor-pointer outline-none focus-visible:ring-1 focus-visible:ring-ring",
                isActive
                    ? "bg-primary/20 border-primary/30 text-primary"
                    : "bg-secondary/40 border-border/60 text-muted-foreground hover:text-foreground hover:bg-secondary/60"
            )}
        >
            {/* Entity icon — filled when active, colored when inactive */}
            <Icon
                weight="fill"
                className="flex-shrink-0 size-4 transition-colors"
                style={{ color: isActive ? undefined : entity.color }}
            />

            {/* Entity name */}
            <span className="truncate w-0 flex-1 min-w-0 text-left py-0.5">
                {entity.name}
            </span>

            {/* Hover-reveal action buttons */}
            <div className="h-full flex-shrink-0 flex items-center transition-opacity opacity-0 group-hover:opacity-100 pointer-events-none group-hover:pointer-events-auto">
                <button
                    onPointerDown={(e: ReactMouseEvent) => e.stopPropagation()}
                    onClick={(e: ReactMouseEvent) => { e.stopPropagation(); onEdit(e); }}
                    className="h-6 w-6 flex items-center justify-center rounded-none border border-border/60 shadow-sm bg-secondary/40 text-muted-foreground hover:bg-secondary/60 hover:text-foreground transition-all duration-200"
                    title="Edit"
                >
                    <PencilSimple weight="bold" size={14} />
                </button>
                <button
                    onPointerDown={(e: ReactMouseEvent) => e.stopPropagation()}
                    onClick={(e: ReactMouseEvent) => { e.stopPropagation(); onDelete(e); }}
                    className="h-6 w-6 flex items-center justify-center rounded-none border border-border/60 shadow-sm bg-secondary/40 text-muted-foreground hover:bg-secondary/60 hover:text-foreground transition-all duration-200"
                    title="Delete"
                >
                    <Trash weight="bold" size={14} />
                </button>
            </div>
        </div>
    );
}

