                                className="text-zinc-400 hover:text-white flex flex-col items-center gap-0.5 h-auto py-1"
                                title="Skip 10s"
                            >
                                <ArrowClockwise size={20} weight="bold" />
                                <span className="text-[10px] font-medium leading-none">10</span>
                            </Button>
                        </div>

