/**
 * ─── PDFPlayer.tsx ───────────────────────────────────────────────────────────
 *
 * PDF document viewer using react-pdf.
 *
 * Features:
 *   - Page-by-page navigation (prev/next buttons + keyboard)
 *   - Zoom in/out with mouse wheel support
 *   - Fullscreen mode
 *   - Text selection highlights: select text on a PDF page to create
 *     text-based Highlight annotations (stored as pdfRange + text)
 *   - Sidebar toggle: shows/hides the highlight list panel in FileView
 *   - Debounced rendering to avoid excessive re-renders during zoom
 *
 * Uses forwardRef + useImperativeHandle to expose control methods
 * (jumpToPage, prevPage, nextPage, zoomIn, zoomOut, addHighlightFromSelection)
 * to the parent FileView component.
 *
 * PDF.js worker is configured globally in src/pdf-worker.ts.
 * ─────────────────────────────────────────────────────────────────────────────
 */

import React, { useState, useRef, useEffect, useMemo, useImperativeHandle, forwardRef, useCallback, type MouseEvent } from 'react';
import { Document, Page, pdfjs } from 'react-pdf';
import { useNavigate } from 'react-router-dom';
import { Button } from '@/components/ui/button';
import { motion, AnimatePresence } from "framer-motion";
import { 
    CaretLeft, 
    CaretRight, 
    MagnifyingGlassPlus, 
    MagnifyingGlassMinus, 
    SidebarSimple,
    EyeSlash,
    CornersIn,
    CornersOut,
    Trash
} from '@phosphor-icons/react';
import 'react-pdf/dist/Page/AnnotationLayer.css';
import 'react-pdf/dist/Page/TextLayer.css';
import { useStore } from '@/store/useStore';
import { useShallow } from '@/lib/zustand-shallow';
import type { Highlight } from "@/types";
import { cn, clamp } from '@/lib/utils';
import { useDebounceValue } from 'usehooks-ts';
import { ErrorBoundary } from '@/components/ui/error-boundary';
import { globalWorker } from '@/pdf-worker';
import { getPdfDocumentOptions } from '@/constants';
import { playSfx } from '@/utils/sound';

// Note: Worker is configured globally in src/pdf-worker.ts

export interface PDFPlayerHandle {
    jumpToPage: (page: number) => void;
    prevPage: () => void;
    nextPage: () => void;
    addHighlightFromSelection: () => void;
    zoomIn: () => void;
    zoomOut: () => void;
}

interface PDFPlayerProps {
    url: string;
    fileId: string;
    highlightId?: string; // If provided, only this highlight will be shown
    initialPage?: number;
    lockedPage?: number; // If set, user cannot change page (for single-page view)
    readonly?: boolean; // If true, selection is disabled
    onPageChange?: (page: number) => void;
    onSelectionChange?: (hasSelection: boolean) => void;
    onToggleSidebar?: () => void;
    isSidebarOpen?: boolean;
    showSidebarToggle?: boolean;
    showControls?: boolean;
    onHideControls?: () => void;
    onToggleFullscreen?: () => void;
    isFullscreen?: boolean;
    className?: string;
}

export const PDFPlayer = forwardRef<PDFPlayerHandle, PDFPlayerProps>(({ 
    url, 
    fileId, 
    highlightId,
    initialPage = 1, 
    lockedPage,  
    readonly = false,
    onPageChange, 
    onSelectionChange, 
    onToggleSidebar,
    isSidebarOpen,
    showSidebarToggle = true,
    showControls = true,
    onHideControls,
    onToggleFullscreen,
    isFullscreen = false,
    className 
}, ref) => {
    // --- State ---
    const [numPages, setNumPages] = useState<number>(0);
    const [pageNumber, setPageNumber] = useState<number>(initialPage);
    const [direction, setDirection] = useState<number>(0);
    const [scale, setScale] = useState<number>(1.0);
    const [hasError, setHasError] = useState(false);
    const [loadedUrl, setLoadedUrl] = useState<string | null>(null);
    const [containerWidth, setContainerWidth] = useState<number>(0);
    const [pageAspectRatio, setPageAspectRatio] = useState<number | null>(null);
    const [selectedText, setSelectedText] = useState<string>("");
    
    // Use debounce for resizing to prevent flickering and excessive re-renders
    // Reduced to 50ms to ensure responsive layout when sidebar toggles
    const [debouncedWidth] = useDebounceValue(containerWidth, 50);

    const containerRef = useRef<HTMLDivElement>(null);
    const scrollContainerRef = useRef<HTMLDivElement>(null);
    const pageWrapperRef = useRef<HTMLDivElement>(null);
    const wheelRafRef = useRef<number>(0);

    // --- Store Access ---
    const { addHighlight, activeCollectionId, highlights } = useStore(useShallow((state) => ({
        addHighlight: state.addHighlight,
        activeCollectionId: state.activeCollectionId,
        highlights: state.highlights,
    })));

    // --- Derived State ---
    const options = useMemo(() => getPdfDocumentOptions(pdfjs.version), []);

    // Filter highlights for the current page
    const pageHighlights = useMemo(() => 
        highlights.filter((h: Highlight) => 
            h.fileId === fileId && 
            h.start === pageNumber &&
            (!highlightId || h.id === highlightId)
        ),
        [highlights, fileId, pageNumber, highlightId]
    );

    const [highlightRects, setHighlightRects] = useState<{ x: number, y: number, width: number, height: number }[]>([]);

    // Robust URL handling to prevent worker race conditions
    const [safeUrl, setSafeUrl] = useState<string | null>(null);

    useEffect(() => {
        // Immediate cleanup
        setLoadedUrl(null);
        setNumPages(0);
        setHasError(false);
        setSafeUrl(null);

        // Small delay to ensure previous worker is cleaned up before starting new one
        const timer = setTimeout(() => {
            setSafeUrl(url);
        }, 100);

        return () => clearTimeout(timer);
    }, [url]);

    const handleLoadSuccess = useCallback(({ numPages }: { numPages: number }) => { 
        setNumPages(numPages); 
        setHasError(false); 
        setLoadedUrl(safeUrl);
    }, [safeUrl]);

    const handleLoadError = useCallback((err: Error) => {
        if (err.message.includes('Worker was terminated')) {
            // Ignore worker termination errors (race condition)
            return;
        }
        console.error("PDF Load Error:", err);
        setHasError(true);
        playSfx('error');
    }, []);

    // --- Effects ---

    // 1. Resize Observer
    useEffect(() => {
        if (!containerRef.current) return;
        
        const observer = new ResizeObserver((entries) => {
            for (const entry of entries) {
                if (entry.contentRect.width > 0) {
                    setContainerWidth(entry.contentRect.width);
                }
            }
        });
        
        observer.observe(containerRef.current);
        return () => observer.disconnect();
    }, [safeUrl]);

    // 2. Initial Page Sync and URL change reset
    useEffect(() => {
        if (lockedPage) {
            setPageNumber(lockedPage);
        } else if (initialPage) {
            setPageNumber(initialPage);
        }
    }, [initialPage, lockedPage]);

    // 3. Selection Listener (Only if not readonly)
    const [selectionRect, setSelectionRect] = useState<{ top: number; left: number; width: number; height: number } | null>(null);

    useEffect(() => {
        if (readonly) return;

        const handleSelectionChange = () => {
            const sel = window.getSelection();
            const text = sel ? sel.toString().trim() : "";
            
            // Only update if selection is inside our container
            if (sel && sel.rangeCount > 0 && containerRef.current?.contains(sel.anchorNode)) {
                setSelectedText(text);
                onSelectionChange?.(!!text);

                if (text) {
                    const range = sel.getRangeAt(0);
                    const rect = range.getBoundingClientRect();
                    const containerRect = containerRef.current?.getBoundingClientRect();
                    
                    if (containerRect) {
                        setSelectionRect({
                            top: rect.top - containerRect.top,
                            left: rect.left - containerRect.left,
                            width: rect.width,
                            height: rect.height
                        });
                    }
                } else {
                    setSelectionRect(null);
                }
            } else {
                setSelectedText("");
                onSelectionChange?.(false);
                setSelectionRect(null);
            }
        };
        
        document.addEventListener("selectionchange", handleSelectionChange);
        // Handle scroll to update position
        const handleScroll = () => {
            if (selectedText) handleSelectionChange();
        };
        window.addEventListener("scroll", handleScroll, true);

        return () => {
            document.removeEventListener("selectionchange", handleSelectionChange);
            window.removeEventListener("scroll", handleScroll, true);
        };
    }, [onSelectionChange, readonly, selectedText]);

    // 4. Update Highlights Visuals
    useEffect(() => {
        setHighlightRects([]);
    }, [pageNumber]);

    useEffect(() => {
        // Wait for text layer to render
        const timer = setTimeout(updateHighlights, 300); // Small delay to ensure DOM is ready
        return () => clearTimeout(timer);
    }, [pageNumber, scale, pageHighlights, debouncedWidth]);

    // --- Logic ---
    
    // Wrap updateHighlights in useCallback to prevent re-creation on every render
    const updateHighlights = useCallback(() => {
        if (!pageWrapperRef.current) return;
        const textLayer = pageWrapperRef.current.querySelector('.react-pdf__Page__textContent');
        if (!textLayer) return; // Not ready yet

        const newRects: { x: number, y: number, width: number, height: number }[] = [];
        const wrapperRect = pageWrapperRef.current.getBoundingClientRect();

        // Build text nodes map
        const textNodes: { node: Node, start: number, end: number }[] = [];
        let fullText = "";
        const walker = document.createTreeWalker(textLayer, NodeFilter.SHOW_TEXT, null);
        let currentNode: Node | null;
        
        while (currentNode = walker.nextNode()) {
            const val = currentNode.textContent || "";
            textNodes.push({
                node: currentNode,
                start: fullText.length,
                end: fullText.length + val.length
            });
            fullText += val;
        }

        if (!fullText) return;

        const addRectsForRange = (start: number, end: number) => {
            try {
                const range = document.createRange();
                const startNodeInfo = textNodes.find(n => start >= n.start && start < n.end);
                const endNodeInfo = textNodes.find(n => end > n.start && end <= n.end);
                
                if (startNodeInfo && endNodeInfo) {
                    range.setStart(startNodeInfo.node, start - startNodeInfo.start);
                    range.setEnd(endNodeInfo.node, end - endNodeInfo.start);
                    
                    const clientRects = range.getClientRects();
                    for (const rect of clientRects) {
                        newRects.push({
                            x: (rect.left - wrapperRect.left) / scale,
                            y: (rect.top - wrapperRect.top) / scale,
                            width: rect.width / scale,
                            height: rect.height / scale
                        });
                    }
                }
            } catch (e) {
                // Ignore range errors
            }
        };

        const escapeRegExp = (string: string) => string.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');

        pageHighlights.forEach((h: Highlight) => {
            if (h.pdfRange) {
                addRectsForRange(h.pdfRange.start, h.pdfRange.end);
            } else if (h.text) {
                // Fallback for legacy highlights without range
                const pattern = escapeRegExp(h.text.trim()).replace(/\s+/g, '\\s+');
                const regex = new RegExp(pattern, 'gi');
                let match;
                while ((match = regex.exec(fullText)) !== null) {
                    addRectsForRange(match.index, match.index + match[0].length);
                }
            }
        });

        setHighlightRects(newRects);
    }, [pageHighlights, scale]);

    const handlePageLoadSuccess = useCallback((page: { getViewport: (options: { scale: number }) => { width: number; height: number } }) => {
        const viewport = page.getViewport({ scale: 1 });
        if (viewport.width > 0) {
            setPageAspectRatio(viewport.height / viewport.width);
        }
        updateHighlights();
    }, [updateHighlights]);

    const handleAddHighlight = () => {
        if (!selectedText || readonly) return;

        let pdfRange: { start: number, end: number } | null = null;
        let visualRect: { x: number, y: number, width: number, height: number } | null = null;
        const sel = window.getSelection();
        
        if (sel && sel.rangeCount > 0 && pageWrapperRef.current) {
            const range = sel.getRangeAt(0);
            
            // Calculate visual rect
            const boundingRect = range.getBoundingClientRect();
            const pageRect = pageWrapperRef.current.getBoundingClientRect();
            
            if (boundingRect.width > 0 && boundingRect.height > 0 && pageRect.width > 0 && pageRect.height > 0) {
                 visualRect = {
                    x: (boundingRect.left - pageRect.left) / pageRect.width,
                    y: (boundingRect.top - pageRect.top) / pageRect.height,
                    width: boundingRect.width / pageRect.width,
                    height: boundingRect.height / pageRect.height
                };
            }

            const textLayer = pageWrapperRef.current.querySelector('.react-pdf__Page__textContent');
            
            if (textLayer && textLayer.contains(range.commonAncestorContainer)) {
                // Calculate absolute offsets
                const walker = document.createTreeWalker(textLayer, NodeFilter.SHOW_TEXT, null);
                let currentIndex = 0;
                let start = -1;
                let end = -1;
                let currentNode: Node | null;
                
                while (currentNode = walker.nextNode()) {
                    const nodeLen = currentNode.textContent?.length || 0;
                    if (currentNode === range.startContainer) {
                        start = currentIndex + range.startOffset;
                    }
                    if (currentNode === range.endContainer) {
                        end = currentIndex + range.endOffset;
                    }
                    currentIndex += nodeLen;
                }
                
                if (start !== -1 && end !== -1) {
                    pdfRange = { start, end };
                }
            }
        }

        addHighlight(fileId, pageNumber, selectedText, activeCollectionId ?? null, pdfRange, visualRect);
        setSelectedText("");
        onSelectionChange?.(false);
        if (sel) sel.removeAllRanges();
    };

    const changePage = (offset: number) => {
        if (lockedPage) return;
        setDirection(offset > 0 ? 1 : -1);
        setPageNumber((prev: number) => {
            const newPage = clamp(prev + offset, 1, numPages);
            onPageChange?.(newPage);
            return newPage;
        });
    };

    // 5. Wheel Event Listener for Zoom/Pan
    useEffect(() => {
        const el = scrollContainerRef.current;
        if (!el) return;

        const handleWheel = (e: WheelEvent) => {
            if (e.shiftKey) {
                e.preventDefault();
                // Zoom (Shift + Scroll)
                const isTrackpad = Math.abs(e.deltaY) < 50;
                const delta = isTrackpad ? -e.deltaY * 0.01 : -Math.sign(e.deltaY) * 0.2;

                cancelAnimationFrame(wheelRafRef.current);
                wheelRafRef.current = requestAnimationFrame(() => {
                    setScale(s => {
                        const newScale = s + delta;
                        return clamp(newScale, 0.5, 5.0);
                    });
                });
            } else if (e.ctrlKey) {
                e.preventDefault();
                // Heuristic: Trackpad pinch usually sends small deltas with Ctrl key.
                // Mouse wheel usually sends large deltas (100+).
                const isLikelyPinch = Math.abs(e.deltaY) < 60;

                if (isLikelyPinch) {
                    // Pinch -> Zoom
                    const delta = -e.deltaY * 0.01;
                    cancelAnimationFrame(wheelRafRef.current);
                    wheelRafRef.current = requestAnimationFrame(() => {
                        setScale(s => {
                            const newScale = s + delta;
                            return clamp(newScale, 0.5, 5.0);
                        });
                    });
                } else {
                    // Ctrl + Mouse Wheel -> Pan Horizontal
                    el.scrollLeft += e.deltaY;
                }
            }
        };

        el.addEventListener('wheel', handleWheel, { passive: false });
        return () => el.removeEventListener('wheel', handleWheel);
    }, []);

    // --- Exposed Methods ---
    useImperativeHandle(ref, () => ({
        jumpToPage: (page: number) => {
            if (page >= 1 && page <= (numPages || Infinity)) {
                setDirection(page > pageNumber ? 1 : -1);
                setPageNumber(page);
            }
        },
        prevPage: () => changePage(-1),
        nextPage: () => changePage(1),
        addHighlightFromSelection: handleAddHighlight,
        zoomIn: () => setScale((s: number) => Math.min(s + 0.2, 3.0)),
        zoomOut: () => setScale((s: number) => Math.max(s - 0.2, 0.5))
    }));

    // --- Render Helpers ---
    const baseWidth = debouncedWidth ? debouncedWidth - 48 : 600;
    const effectiveWidth = baseWidth;

    const variants = {
        enter: (direction: number) => ({
            x: direction > 0 ? 20 : -20,
            opacity: 0
        }),
        center: {
            zIndex: 1,
            x: 0,
            opacity: 1
        },
        exit: (direction: number) => ({
            zIndex: 0,
            x: direction < 0 ? 20 : -20,
            opacity: 0
        })
    };

    if (!safeUrl) {
        return <div className="flex items-center justify-center h-full text-muted-foreground">
            <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-primary mr-2"></div>
            Loading...
        </div>;
    }

    return (
        <div className={cn("flex flex-col h-full bg-transparent relative selection:bg-primary/30", className)} ref={containerRef}>
            <style>{`
                .react-pdf__Page__textContent {
                    user-select: text !important;
                    cursor: text !important;
                }
                .react-pdf__Page__annotations {
                    pointer-events: none;
                }
                .annotationLayer .linkAnnotation > a {
                    pointer-events: auto;
                }
            `}</style>
            {/* Floating Highlight Button */}
            {selectionRect && !readonly && selectedText && (
                <div 
                    className="absolute z-50 animate-in fade-in zoom-in duration-200"
                    style={{
                        top: selectionRect.top - 40,
                        left: selectionRect.left + (selectionRect.width / 2) - 50,
                    }}
                >
                    <Button
                        size="sm"
                        onClick={(e: MouseEvent) => {
                            e.stopPropagation();
                            handleAddHighlight();
                            setSelectionRect(null);
                        }}
                        className="shadow-xl bg-primary hover:bg-primary/90 text-primary-foreground h-8 px-3 rounded-full flex items-center gap-2"
                    >
                        <span className="text-xs font-semibold">Highlight</span>
                    </Button>
                </div>
            )}

            {/* Main Document Area */}
            <div className="flex-1 overflow-auto flex justify-center p-4 custom-scrollbar" ref={scrollContainerRef}>
                {hasError ? (
                    <div className="flex flex-col items-center justify-center text-red-400 gap-2 h-full">
                        <span className="text-lg font-medium">Unable to load PDF</span>
                        <span className="text-sm text-white/50">The worker may have been terminated or the file is corrupted.</span>
                        <Button variant="outline" size="sm" onClick={() => { setHasError(false); setSafeUrl(null); setTimeout(() => setSafeUrl(url), 100); }}>
                            Retry
                        </Button>
                    </div>
                ) : (
                    <ErrorBoundary fallback={
                        <div className="flex flex-col items-center justify-center text-red-400 gap-2 h-full">
                            <span className="text-lg font-medium">Render Error</span>
                            <span className="text-sm text-white/50">The PDF viewer encountered an error.</span>
                            <Button variant="outline" size="sm" onClick={() => window.location.reload()}>
                                Reload
                            </Button>
                        </div>
                    }>
                        <Document
                            key={safeUrl}
                            file={safeUrl}
                            onLoadSuccess={handleLoadSuccess}
                            onLoadError={handleLoadError}
                            options={options}
                        loading={
                            <div className="flex items-center justify-center h-64 text-muted-foreground">
                                <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-primary mr-2"></div>
                                Loading PDF...
                            </div>
                        }
                        className="flex justify-center shadow-2xl"
                    >
                        {loadedUrl === safeUrl && (
                            <div 
                                className="transition-all duration-200 ease-out"
                                style={{ 
                                    width: effectiveWidth * scale, 
                                    height: (pageAspectRatio ? effectiveWidth * pageAspectRatio : effectiveWidth * 1.414) * scale,
                                    position: 'relative'
                                }}
                            >
                                <div 
                                    className="absolute top-0 left-0 transition-transform duration-200 ease-out origin-top-left" 
                                    ref={pageWrapperRef}
                                    style={{ transform: `scale(${scale})`, width: effectiveWidth }}
                                >
                                    <AnimatePresence initial={false} custom={direction}>
                                        <motion.div
                                            key={pageNumber}
                                            custom={direction}
                                            variants={variants}
                                            initial="enter"
                                            animate="center"
                                            exit="exit"
                                            transition={{ duration: 0.2 }}
                                            className="absolute top-0 left-0 w-full"
                                        >
                                            <Page
                                                pageNumber={pageNumber}
                                                width={effectiveWidth}
                                                renderTextLayer={true}
                                                renderAnnotationLayer={true}
                                                className="bg-white shadow-sm"
                                                onLoadSuccess={handlePageLoadSuccess}
                                                onRenderTextLayerSuccess={updateHighlights}
                                                onRenderError={() => setHasError(true)}
                                                onGetTextError={(e: Error) => { if (!e.message?.includes('terminated')) setHasError(true) }}
                                                onGetAnnotationsError={(e: Error) => { if (!e.message?.includes('terminated')) setHasError(true) }}
                                                onGetStructTreeError={(e: Error) => { if (!e.message?.includes('terminated')) setHasError(true) }}
                                                loading={
                                                    <div 
                                                        style={{ width: effectiveWidth, height: effectiveWidth * 1.4 }} 
                                                        className="bg-white/5 animate-pulse" 
                                                    />
                                                }
                                                error={
                                                    <div className="flex items-center justify-center h-64 text-red-400">
                                                        Error rendering page {pageNumber}
                                                    </div>
                                                }
                                            />
                                            
                                            {/* Highlight Overlay Layer */}
                                            <div className="absolute inset-0 pointer-events-none z-10">
                                                {highlightRects.map((rect, i) => (
                                                    <div
                                                        key={i}
                                                        className="absolute bg-yellow-400/30 mix-blend-multiply border-b-2 border-yellow-500/50"
                                                        style={{
                                                            left: rect.x,
                                                            top: rect.y,
                                                            width: rect.width,
                                                            height: rect.height,
                                                        }}
                                                    />
                                                ))}
                                            </div>
                                        </motion.div>
                                    </AnimatePresence>
                                </div>
                        </div>
                        )}
                    </Document>
                    </ErrorBoundary>
                )}
            </div>

            {/* Floating Controls (Bottom Center) */}
            <div className={cn(
                "absolute bottom-6 left-1/2 -translate-x-1/2 flex items-center gap-1 bg-zinc-900/90 backdrop-blur-md px-2 py-1.5 rounded-full border border-white/10 shadow-2xl z-[60] transition-all duration-300",
                showControls ? "opacity-100 translate-y-0" : "opacity-0 translate-y-4 pointer-events-none"
            )}>
                {/* Page Navigation */}
                <div className="flex items-center gap-1 mr-2">
                    <Button
                        variant="ghost"
                        size="icon"
                        className="h-7 w-7 text-zinc-400 hover:text-white hover:bg-white/10 rounded-full"
                        onClick={() => changePage(-1)}
                        disabled={pageNumber <= 1 || !!lockedPage || !loadedUrl}
                        data-sound-back
                    >
                        <CaretLeft size={14} weight="bold" />
                    </Button>
                    
                    <span className="text-zinc-200 text-xs font-mono min-w-[50px] text-center select-none">
                        {pageNumber} <span className="text-zinc-500">/</span> {numPages || '-'}
                    </span>

                    <Button
                        variant="ghost"
                        size="icon"
                        className="h-7 w-7 text-zinc-400 hover:text-white hover:bg-white/10 rounded-full"
                        onClick={(e: MouseEvent) => { e.stopPropagation(); changePage(1); }}
                        disabled={pageNumber >= numPages || !!lockedPage || !loadedUrl}
                    >
                        <CaretRight size={14} weight="bold" />
                    </Button>
                </div>

                <div className="w-px h-4 bg-white/10 mx-1" />

                {/* Zoom Controls */}
                <div className="flex items-center gap-1">
                    <Button
                        variant="ghost"
                        size="icon"
                        className="h-7 w-7 text-zinc-400 hover:text-white hover:bg-white/10 rounded-full"
                        onClick={(e: MouseEvent) => { 
                            e.stopPropagation(); 
                            playSfx('cursor');
                            setScale((s: number) => Math.max(s - 0.1, 0.5)); 
                        }}
                        disabled={!loadedUrl}
                    >
                        <MagnifyingGlassMinus size={14} weight="bold" />
                    </Button>
                    
                    <span className="text-zinc-400 text-[10px] w-8 text-center select-none">
                        {Math.round(scale * 100)}%
                    </span>

                    <Button
                        variant="ghost"
                        size="icon"
                        className="h-7 w-7 text-zinc-400 hover:text-white hover:bg-white/10 rounded-full"
                        onClick={(e: MouseEvent) => { 
                            e.stopPropagation(); 
                            playSfx('cursor');
                            setScale((s: number) => Math.min(s + 0.1, 3.0)); 
                        }}
                        disabled={!loadedUrl}
                    >
                        <MagnifyingGlassPlus size={14} weight="bold" />
                    </Button>
                </div>

                {onToggleSidebar && showSidebarToggle && (
                    <>
                        <div className="w-px h-4 bg-white/10 mx-1" />
                        <Button
                            variant="ghost"
                            size="icon"
                            className={cn(
                                "h-7 w-7 text-zinc-400 hover:text-white hover:bg-white/10 rounded-full",
                                isSidebarOpen && "text-primary hover:text-primary"
                            )}
                            onClick={() => {
                                playSfx('cursor');
                                onToggleSidebar();
                            }}
                        >
                            <SidebarSimple size={14} weight="bold" />
                        </Button>
                    </>
                )}

                {onToggleFullscreen && (
                    <>
                        <div className="w-px h-4 bg-white/10 mx-1" />
                        <Button
                            variant="ghost"
                            size="icon"
                            className="h-7 w-7 text-zinc-400 hover:text-white hover:bg-white/10 rounded-full"
                            onClick={(e: MouseEvent) => {
                                e.stopPropagation();
                                playSfx('cursor');
                                onToggleFullscreen();
                            }}
                            title={isFullscreen ? "Exit Fullscreen" : "Enter Fullscreen"}
                        >
                            {isFullscreen ? <CornersIn size={14} weight="bold" /> : <CornersOut size={14} weight="bold" />}
                        </Button>
                    </>
                )}

                {onHideControls && (
                    <>
                        <div className="w-px h-4 bg-white/10 mx-1" />
                        <Button
                            variant="ghost"
                            size="icon"
                            className="h-7 w-7 text-zinc-400 hover:text-white hover:bg-white/10 rounded-full"
                            onClick={(e: MouseEvent) => {
                                e.stopPropagation();
                                playSfx('cursor');
                                onHideControls();
                            }}
                            title="Hide Controls"
                        >
                            <EyeSlash size={14} weight="bold" />
                        </Button>
                    </>
                )}
            </div>
        </div>
    );
});

PDFPlayer.displayName = 'PDFPlayer';

/**
 * ─── PiPPlayer.tsx ─────────────────────────────────────────────────
 *
 * Picture-in-Picture mini video player that appears as a compact
 * overlay, allowing playback to continue while browsing other views.
 *
 * Features:
 *   - Compact video overlay with play/pause and mute toggles
 *   - Progress restoration from saved file progress state
 *   - Expand to full file view or close PiP
 *   - Sidebar-collapse-aware positioning
 *   - Continuous progress tracking via timeupdate events
 *
 * Props: isCollapsed (sidebar state for layout adjustment)
 * Exports: PiPPlayer component
 * Related: useStore (pipFileId, isPipOpen), VideoPlayer
 * ───────────────────────────────────────────────────────────────────
 */
import { useRef, useEffect, useState } from "react";
import { useStore } from "@/store/useStore";
import { useShallow } from "@/lib/zustand-shallow";
import { Link, useNavigate } from "react-router-dom";
import { Button } from "@/components/ui/button";
import { Play, Pause, X, ArrowsOutSimple, SpeakerSimpleHigh, SpeakerSimpleSlash } from "@phosphor-icons/react";
import { cn } from "@/lib/utils";
import { useResolvedFileUrl } from "@/hooks/useResolvedFileUrl";

interface PiPPlayerProps {
    isCollapsed: boolean;
}

export function PiPPlayer({ isCollapsed }: PiPPlayerProps) {
    const navigate = useNavigate();
    const { pipFileId, isPipOpen, setPipFile, togglePip, files, fileProgress, setFileProgress } = useStore(useShallow((state) => ({
        pipFileId: state.pipFileId,
        isPipOpen: state.isPipOpen,
        setPipFile: state.setPipFile,
        togglePip: state.togglePip,
        files: state.files,
        fileProgress: state.fileProgress,
        setFileProgress: state.setFileProgress,
    })));
    const videoRef = useRef<HTMLVideoElement>(null);
    const [isPlaying, setIsPlaying] = useState(true);
    const [isMuted, setIsMuted] = useState(false);

    const file = pipFileId ? files.find(f => f.id === pipFileId) : null;
    const { resolvedUrl } = useResolvedFileUrl(file);

    useEffect(() => {
        if (videoRef.current) {
            // Restore progress
            if (file && fileProgress[file.id] && Math.abs(videoRef.current.currentTime - fileProgress[file.id]) > 1) {
                videoRef.current.currentTime = fileProgress[file.id];
            }

            if (isPlaying) {
                videoRef.current.play().catch(() => setIsPlaying(false));
            } else {
                videoRef.current.pause();
            }
        }
    }, [isPlaying, file?.id]); // Re-run when file changes


    if (!isPipOpen || !file || !resolvedUrl) return null;

    const togglePlay = (e: React.MouseEvent) => {
        e.stopPropagation();
        setIsPlaying(!isPlaying);
    };

    const toggleMute = (e: React.MouseEvent) => {
        e.stopPropagation();
        setIsMuted(!isMuted);
    };

    const handleExpand = (e: React.MouseEvent) => {
        e.stopPropagation();
        if (videoRef.current && file) {
            setFileProgress(file.id, videoRef.current.currentTime);
        }
        setPipFile(null); // Close PiP
        navigate(`/file/${file.id}`);
    };

    const handleClose = (e: React.MouseEvent) => {
        e.stopPropagation();
        if (videoRef.current && file) {
            setFileProgress(file.id, videoRef.current.currentTime);
        }
        togglePip(false);
        setPipFile(null);
    };

    const handleTimeUpdate = () => {
        if (videoRef.current && file) {
            const time = videoRef.current.currentTime;
            if (Math.abs(time - (fileProgress[file.id] || 0)) > 2) {
                setFileProgress(file.id, time);
            }
        }
    };

    return (
        <div className="relative group">
            {/* Main Container */}
            <div className={cn(
                "relative bg-transparent overflow-hidden flex items-center justify-center",
                isCollapsed ? "h-10 w-10 mx-auto rounded-md" : "h-[120px] w-full rounded-md" // Aspect ratio placeholder
            )}>
                {/* Video */}
                <video
                    ref={videoRef}
                    src={resolvedUrl}
                    className="w-full h-full object-cover"
                    muted={isMuted}
                    loop
                    onTimeUpdate={handleTimeUpdate}
                />

                {/* Overlays (Only visible when not collapsed) */}
                {!isCollapsed && (
                    <div className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 transition-opacity flex flex-col justify-between p-2">
                        <div className="flex justify-between items-start">
                            <span className="text-[10px] text-white font-medium truncate flex-1 drop-shadow-md">
                                {file.name}
                            </span>
                            <button onClick={handleClose} className="text-white/80 hover:text-white">
                                <X size={14} weight="bold" />
                            </button>
                        </div>

                        <div className="flex justify-center gap-3 items-center">
                            <button onClick={handleExpand} className="text-white/80 hover:text-white" title="Expand">
                                <ArrowsOutSimple size={16} weight="bold" />
                            </button>
                            <button onClick={togglePlay} className="w-8 h-8 rounded-full bg-white/20 hover:bg-white/30 flex items-center justify-center text-white backdrop-blur-sm transition-colors">
                                {isPlaying ? <Pause weight="fill" /> : <Play weight="fill" />}
                            </button>
                            <button onClick={toggleMute} className="text-white/80 hover:text-white" title={isMuted ? "Unmute" : "Mute"}>
                                {isMuted ? <SpeakerSimpleSlash size={16} weight="bold" /> : <SpeakerSimpleHigh size={16} weight="bold" />}
                            </button>
                        </div>
                    </div>
                )}

                {/* Collapsed State Overlay */}
                {isCollapsed && (
                    <div className="absolute inset-0 bg-black/20 flex items-center justify-center group-hover:bg-black/40 transition-colors cursor-pointer" onClick={handleExpand}>
                        <div className="w-2 h-2 rounded-full bg-primary animate-pulse absolute top-1 right-1" />
                        {isPlaying ? (
                            <div className="flex gap-0.5 items-end h-3">
                                <div className="w-0.5 bg-white h-2 animate-[bounce_1s_infinite]" />
                                <div className="w-0.5 bg-white h-3 animate-[bounce_1.2s_infinite]" />
                                <div className="w-0.5 bg-white h-1.5 animate-[bounce_0.8s_infinite]" />
                            </div>
                        ) : (
                            <Play weight="fill" className="text-white text-xs" />
                        )}
                    </div>
                )}
            </div>

        </div>
    );
}

/**
 * ─── VideoPlayer.tsx ─────────────────────────────────────────────────────────
 *
 * Full-featured video player component with custom UI controls.
 *
 * Features:
 *   - Custom play/pause, seek bar, volume, fullscreen controls
 *   - Highlight/timestamp system: create, edit, delete time-range annotations
 *   - Seek preview thumbnails on hover over the progress bar
 *   - Picture-in-Picture (PiP) support
 *   - Per-file zoom level (manual or auto-fit)
 *   - Playback speed control (0.25x–4x)
 *   - Looping with optional A–B loop range
 *   - Keyboard shortcuts (space, arrows, etc.)
 *   - Collection association for highlights
 *   - Per-file volume + mute state persistence
 *   - Auto-resume from last playback position
 *   - Ambient music suppression while video plays
 *
 * Props pattern:
 *   Receives url, fileId, optional highlight list and callbacks.
 *   Uses forwardRef + useImperativeHandle to expose control methods
 *   (play, pause, seek, zoom, addHighlight) to parent FileView.
 *
 * Largest component in the app (~1,700 lines).
 * Consider extracting: HighlightPanel, ControlBar, SeekBar as sub-components
 * if this file becomes difficult to edit.
 * ─────────────────────────────────────────────────────────────────────────────
 */

