                }
                if (scope === 'both' || scope === 'base') {
                    if (data.baseTheme) setBaseTheme(data.baseTheme as BaseTheme);
                    if (data.baseThemeMode) setBaseThemeMode(data.baseThemeMode);
                    if (data.customBaseThemes) {
