                        },
                        {
                            label: "Data & Account",
                            items: [
                                { tab: 'sync' as SettingsTab, icon: Cloud, label: 'Sync & Backup' },
                                { tab: 'google-drive' as SettingsTab, icon: GoogleDriveLogo, label: 'Google Drive' },
                                { tab: 'system' as SettingsTab, icon: Gear, label: 'System' },
