import { useCallback, useRef } from 'react';

/**
 * Wraps a ref callback in a stable function reference that persists across renders.
 * 
 * In React 19, callback refs are detached/reattached when their identity changes
 * between renders. If the callback ref triggers setState (as dnd-kit's setNodeRef does),
 * this creates an infinite update loop:
 *   new ref → detach(null) → attach(node) → setState → re-render → new ref → ∞
 * 
 * This hook wraps the ref setter in a stable useCallback so its identity never changes,
 * preventing the detach/reattach cycle.
 */
export function useStableRef<T = HTMLElement | null>(
    setter: ((node: T) => void) | null | undefined
) {
    const setterRef = useRef(setter);
    setterRef.current = setter;
    return useCallback((node: T) => {
        setterRef.current?.(node);
    }, []);
}

/**
 * ─── useSync.ts ──────────────────────────────────────────────────────────────
 *
 * Cloud sync hook for Whistler.
 *
 * Handles bidirectional synchronization with a Cloudflare Workers backend
 * at SYNC_API_URL. Supports push (upload local state) and pull (download
 * remote state).
 *
 * Architecture:
 *   - Auth is token-based: session token + account ID stored in localStorage
 *   - Push: fetches current server data, merges locally-enabled categories
 *     on top, and writes back. Categories this device has disabled are
 *     preserved on the server untouched.
 *   - Pull: downloads remote state and applies enabled categories to the
 *     local store. Uses `!== undefined` checks so falsy values (false, 0,
 *     empty string) are correctly synced.
 *
 * Sync options (from store.syncOptions):
 *   - projects, files, collections, highlights, graphs, graphNodes,
 *     graphEdges, docs, storages, history, trash
 *   - Each can be toggled on/off independently
 *
 * Used by:
 *   - App.tsx (mounted once at app root)
 *   - SidebarSync.tsx (manual push/pull buttons + status display)
 *   - SettingsSync.tsx (sync configuration UI)
 * ─────────────────────────────────────────────────────────────────────────────
 */

import { useState, useCallback, useEffect, useRef } from 'react';
import { authStorage } from "@/utils/authStorage";
import { useStore } from '@/store/useStore';
import { useShallow } from '@/lib/zustand-shallow';
import { sanitizeFilesForPersistence } from '@/utils/localFiles';
import { normalizeServerDataPayload } from '@/utils/syncPayload';
import { SYNC_API_URL } from '@/constants';

// Module-level abort controller shared across all useSync instances so that
// concurrent push/pull calls from different components properly cancel each other.
let activeAbortController: AbortController | null = null;

export function useSync() {
    const {
        setLastSyncTime,
        setState,
        setSyncStatus,
        syncStatus,
        logout,
    } = useStore(useShallow((state) => ({
        setLastSyncTime: state.setLastSyncTime,
        setState: state.setState,
        setSyncStatus: state.setSyncStatus,
        syncStatus: state.syncStatus,
        logout: state.logout,
    })));
    const [error, setError] = useState<string | null>(null);
    const mountedRef = useRef(true);

    useEffect(() => {
        mountedRef.current = true;
        return () => {
            mountedRef.current = false;
        };
    }, []);

    const handleSync = useCallback(async (type: 'push' | 'pull') => {
        const storedToken = authStorage.getToken();
        const storedAccountId = authStorage.getAccountId();

        if (!storedAccountId || !storedToken) {
            setError("Connect with your Sync ID first");
            return;
        }

        setSyncStatus("syncing");
        setError(null);

        // Abort any in-flight sync request
        activeAbortController?.abort();
        const controller = new AbortController();
        activeAbortController = controller;

        try {
            if (type === "push") {
                const state = useStore.getState();
                const { syncOptions } = state;
                const trashEnabled = syncOptions.trash ?? true;
                const historyEnabled = syncOptions.history ?? true;

                // ── Fetch current server data so we can preserve disabled categories ──
                let serverData: Record<string, any> = {};
                const getResponse = await fetch(`${SYNC_API_URL}/data`, {
                    method: "GET",
                    headers: { Authorization: `Bearer ${storedToken}` },
                    signal: controller.signal,
                });
                if (getResponse.ok) {
                    const json = await getResponse.json();
                    console.log('[Sync Push] Server GET raw response:', JSON.stringify(json).slice(0, 500));
                    serverData = normalizeServerDataPayload(json) ?? {};
                    console.log('[Sync Push] Normalized server data keys:', Object.keys(serverData));
                } else if (getResponse.status === 401) {
                    logout();
                    setError("Session expired. Please sign in again.");
                    setSyncStatus("error");
                    return;
                }
                // Non-401 errors on the GET are fine — we just push a full payload.

                // Start from server data (preserves categories this device has disabled)
                // then overwrite with local data for enabled categories.
                const data: Record<string, unknown> = {
                    ...serverData,
                    lastModified: Date.now(),
                };

                if (syncOptions.projects) {
                    data.projects = trashEnabled
                        ? state.projects
                        : state.projects.filter(p => !p.deleted);
                }
                if (syncOptions.files) {
                    data.files = trashEnabled
                        ? sanitizeFilesForPersistence(state.files)
                        : sanitizeFilesForPersistence(state.files.filter(f => !f.deleted));
                }
                if (syncOptions.collections) {
                    data.collections = trashEnabled
                        ? state.collections
                        : state.collections.filter(c => !c.deleted);
                }
                if (syncOptions.highlights) data.highlights = state.highlights;
                if (syncOptions.graphs) {
                    data.graphs = trashEnabled
                        ? state.graphs
                        : state.graphs.filter(g => !g.deleted);
                    data.graphNodes = state.graphNodes;
                    data.graphEdges = state.graphEdges;
                }
                if (syncOptions.docs) {
                    data.docs = trashEnabled
                        ? state.docs
                        : state.docs.filter(d => !d.deleted);
                }
                if (syncOptions.storages) {
                    data.storages = trashEnabled
                        ? state.storages
                        : state.storages.filter(s => !s.deleted);
                }

                if (historyEnabled) data.history = state.history;

                if (syncOptions.settings) {
                    const adv = syncOptions.advancedSettings || {};

                    if (adv.appearance) {
                        data.accentTheme = state.accentTheme;
                        data.accentThemeMode = state.accentThemeMode;
                        data.customAccentThemes = state.customAccentThemes;
                        data.baseTheme = state.baseTheme;
                        data.baseThemeMode = state.baseThemeMode;
                        data.customBaseThemes = state.customBaseThemes;
                        data.enableDefaultColorControls = state.enableDefaultColorControls;
                        data.defaultColors = state.defaultColors;
                        data.backgroundImageUrl = state.backgroundImageUrl;
                        data.backgroundImageOpacity = state.backgroundImageOpacity;
                        data.backgroundColor = state.backgroundColor;
                        data.backgroundOverlayOpacity = state.backgroundOverlayOpacity;
                        data.backgroundGradient = state.backgroundGradient;
                        data.backgroundIsGradient = state.backgroundIsGradient;
                        data.windowOutlineEnabled = state.windowOutlineEnabled;
                    }

                    if (adv.music) {
                        data.ambientMusicUrl = state.ambientMusicUrl;
                        data.ambientMusicName = state.ambientMusicName;
                        data.ambientMusicType = state.ambientMusicType;
                        data.ambientMusicPaused = state.ambientMusicPaused;
                        data.ambientMusicVolume = state.ambientMusicVolume;
                        data.ambientMusicStorageKey = state.ambientMusicStorageKey;
                    }

                    if (adv.playback) {
                        data.muteNewVideosUntilUnmuted = state.muteNewVideosUntilUnmuted;
                        data.muteHighlightsUntilUnmuted = state.muteHighlightsUntilUnmuted;
                        data.alwaysShowMuteOverlay = state.alwaysShowMuteOverlay;
                        data.rememberMediaVolume = state.rememberMediaVolume;
                        data.disableMediaAutoplay = state.disableMediaAutoplay;
                        data.videoVolumeByFile = state.videoVolumeByFile;
                        data.audioVolumeByFile = state.audioVolumeByFile;
                        data.videoUnmutedByFile = state.videoUnmutedByFile;
                    }

                    if (adv.cache) {
                        data.useMiddleFrameForPreviews = state.useMiddleFrameForPreviews;
                        data.cacheFiles = state.cacheFiles;
                        data.cacheCollections = state.cacheCollections;
                        data.cacheHighlights = state.cacheHighlights;
                    }

                    if (adv.sounds) {
                        data.sfxEnabled = state.sfxEnabled;
                        data.enabledSounds = state.enabledSounds;
                        data.replaceSearchWithConfirm = state.replaceSearchWithConfirm;
                        data.replaceAllSoundsWithCursor = state.replaceAllSoundsWithCursor;
                        data.soundConfigs = state.soundConfigs;
                    }

                    if (adv.keybinds) {
                        data.customKeybinds = state.customKeybinds;
                        data.disabledKeybinds = state.disabledKeybinds;
                    }
                }

                if (syncOptions.googleDrive) {
                    data.googleDriveApiKey = state.googleDriveApiKey;
                }

                const payload = JSON.stringify({
                    key: "whistler_data",
                    value: data,
                });

                console.log('[Sync Push] Payload keys being sent:', Object.keys(data));

                const response = await fetch(`${SYNC_API_URL}/data`, {
                    method: "PUT",
                    headers: {
                        "Content-Type": "application/json",
                        Authorization: `Bearer ${storedToken}`,
                    },
                    body: payload,
                    signal: controller.signal,
                });

                if (response.status === 401) {
                    logout();
                    setError("Session expired. Please sign in again.");
                    setSyncStatus("error");
                    return;
                }

                if (!response.ok) {
                    const body = await response.json().catch(() => null);
                    setError(body?.error || "Push failed");
                    setSyncStatus("error");
                    return;
                }
            } else {

                const response = await fetch(`${SYNC_API_URL}/data`, {
                    method: "GET",
                    headers: {
                        Authorization: `Bearer ${storedToken}`,
                    },
                    signal: controller.signal,
                });

                if (response.status === 401) {
                    logout();
                    setError("Session expired. Please sign in again.");
                    setSyncStatus("error");
                    return;
                }

                if (!response.ok) {
                    const body = await response.json().catch(() => null);
                    setError(body?.error || "Pull failed");
                    setSyncStatus("error");
                    return;
                }

                const json = await response.json();
                console.log('[Sync Pull] Server GET raw response:', JSON.stringify(json).slice(0, 500));
                const serverData = normalizeServerDataPayload(json);
                console.log('[Sync Pull] Normalized result:', serverData ? Object.keys(serverData) : null);
                if (serverData) {
                    const state = useStore.getState();
                    const { syncOptions } = state;
                    console.log('[Sync Pull] syncOptions:', JSON.stringify(syncOptions));
                    const trashEnabled = syncOptions.trash ?? true;
                    const historyEnabled = syncOptions.history ?? true;
                    const updates: Record<string, unknown> = {};

                    if (syncOptions.projects && serverData.projects !== undefined) {
                        if (trashEnabled) {
                            updates.projects = serverData.projects;
                        } else {
                            const localDeleted = state.projects.filter(p => p.deleted);
                            const serverIds = new Set(serverData.projects.map((p: { id: string }) => p.id));
                            updates.projects = [...serverData.projects, ...localDeleted.filter(p => !serverIds.has(p.id))];
                        }
                    }
                    if (syncOptions.files && serverData.files !== undefined) {
                        if (trashEnabled) {
                            updates.files = sanitizeFilesForPersistence(serverData.files);
                        } else {
                            const localDeleted = state.files.filter(f => f.deleted);
                            const serverIds = new Set(serverData.files.map((f: { id: string }) => f.id));
                            updates.files = [
                                ...sanitizeFilesForPersistence(serverData.files),
                                ...sanitizeFilesForPersistence(localDeleted.filter(f => !serverIds.has(f.id))),
                            ];
                        }
                    }
                    if (syncOptions.collections && serverData.collections !== undefined) {
                        if (trashEnabled) {
                            updates.collections = serverData.collections;
                        } else {
                            const localDeleted = state.collections.filter(c => c.deleted);
                            const serverIds = new Set(serverData.collections.map((c: { id: string }) => c.id));
                            updates.collections = [...serverData.collections, ...localDeleted.filter(c => !serverIds.has(c.id))];
                        }
                    }
                    if (syncOptions.highlights && serverData.highlights !== undefined) updates.highlights = serverData.highlights;
                    if (syncOptions.graphs) {
                        if (serverData.graphs !== undefined) {
                            if (trashEnabled) {
                                updates.graphs = serverData.graphs;
                            } else {
                                const localDeleted = state.graphs.filter(g => g.deleted);
                                const serverIds = new Set(serverData.graphs.map((g: { id: string }) => g.id));
                                updates.graphs = [...serverData.graphs, ...localDeleted.filter(g => !serverIds.has(g.id))];
                            }
                        }
                        if (serverData.graphNodes !== undefined) updates.graphNodes = serverData.graphNodes;
                        if (serverData.graphEdges !== undefined) updates.graphEdges = serverData.graphEdges;
                    }
                    if (syncOptions.docs && serverData.docs !== undefined) {
                        if (trashEnabled) {
                            updates.docs = serverData.docs;
                        } else {
                            const localDeleted = state.docs.filter(d => d.deleted);
                            const serverIds = new Set(serverData.docs.map((d: { id: string }) => d.id));
                            updates.docs = [...serverData.docs, ...localDeleted.filter(d => !serverIds.has(d.id))];
                        }
                    }
                    if (syncOptions.storages && serverData.storages !== undefined) {
                        if (trashEnabled) {
                            updates.storages = serverData.storages;
                        } else {
                            const localDeleted = state.storages.filter(s => s.deleted);
                            const serverIds = new Set(serverData.storages.map((s: { id: string }) => s.id));
                            updates.storages = [...serverData.storages, ...localDeleted.filter(s => !serverIds.has(s.id))];
                        }
                    }

                    if (historyEnabled && serverData.history !== undefined) updates.history = serverData.history;

                    if (syncOptions.settings) {
                        const adv = syncOptions.advancedSettings || {};

                        if (adv.appearance) {
                            if (serverData.accentTheme !== undefined) updates.accentTheme = serverData.accentTheme;
                            if (serverData.accentThemeMode !== undefined) updates.accentThemeMode = serverData.accentThemeMode;
                            if (serverData.customAccentThemes !== undefined) updates.customAccentThemes = serverData.customAccentThemes;
                            if (serverData.baseTheme !== undefined) updates.baseTheme = serverData.baseTheme;
                            if (serverData.baseThemeMode !== undefined) updates.baseThemeMode = serverData.baseThemeMode;
                            if (serverData.customBaseThemes !== undefined) updates.customBaseThemes = serverData.customBaseThemes;
                            if (serverData.enableDefaultColorControls !== undefined) updates.enableDefaultColorControls = serverData.enableDefaultColorControls;
                            if (serverData.defaultColors !== undefined) updates.defaultColors = serverData.defaultColors;
                            if (serverData.backgroundImageUrl !== undefined) updates.backgroundImageUrl = serverData.backgroundImageUrl;
                            if (serverData.backgroundImageOpacity !== undefined) updates.backgroundImageOpacity = serverData.backgroundImageOpacity;
                            if (serverData.backgroundColor !== undefined) updates.backgroundColor = serverData.backgroundColor;
                            if (serverData.backgroundOverlayOpacity !== undefined) updates.backgroundOverlayOpacity = serverData.backgroundOverlayOpacity;
                            if (serverData.backgroundGradient !== undefined) updates.backgroundGradient = serverData.backgroundGradient;
                            if (serverData.backgroundIsGradient !== undefined) updates.backgroundIsGradient = serverData.backgroundIsGradient;
                            if (serverData.windowOutlineEnabled !== undefined) updates.windowOutlineEnabled = serverData.windowOutlineEnabled;
                        }

                        if (adv.music) {
                            if (serverData.ambientMusicUrl !== undefined) updates.ambientMusicUrl = serverData.ambientMusicUrl;
                            if (serverData.ambientMusicName !== undefined) updates.ambientMusicName = serverData.ambientMusicName;
                            if (serverData.ambientMusicType !== undefined) updates.ambientMusicType = serverData.ambientMusicType;
                            if (serverData.ambientMusicPaused !== undefined) updates.ambientMusicPaused = serverData.ambientMusicPaused;
                            if (serverData.ambientMusicVolume !== undefined) updates.ambientMusicVolume = serverData.ambientMusicVolume;
                            if (serverData.ambientMusicStorageKey !== undefined) updates.ambientMusicStorageKey = serverData.ambientMusicStorageKey;
                        }

                        if (adv.playback) {
                            if (serverData.muteNewVideosUntilUnmuted !== undefined) updates.muteNewVideosUntilUnmuted = serverData.muteNewVideosUntilUnmuted;
                            if (serverData.muteHighlightsUntilUnmuted !== undefined) updates.muteHighlightsUntilUnmuted = serverData.muteHighlightsUntilUnmuted;
                            if (serverData.alwaysShowMuteOverlay !== undefined) updates.alwaysShowMuteOverlay = serverData.alwaysShowMuteOverlay;
                            if (serverData.rememberMediaVolume !== undefined) updates.rememberMediaVolume = serverData.rememberMediaVolume;
                            if (serverData.disableMediaAutoplay !== undefined) updates.disableMediaAutoplay = serverData.disableMediaAutoplay;
                            if (serverData.videoVolumeByFile !== undefined) updates.videoVolumeByFile = serverData.videoVolumeByFile;
                            if (serverData.audioVolumeByFile !== undefined) updates.audioVolumeByFile = serverData.audioVolumeByFile;
                            if (serverData.videoUnmutedByFile !== undefined) updates.videoUnmutedByFile = serverData.videoUnmutedByFile;
                        }

                        if (adv.cache) {
                            if (serverData.useMiddleFrameForPreviews !== undefined) updates.useMiddleFrameForPreviews = serverData.useMiddleFrameForPreviews;
                            if (serverData.cacheFiles !== undefined) updates.cacheFiles = serverData.cacheFiles;
                            if (serverData.cacheCollections !== undefined) updates.cacheCollections = serverData.cacheCollections;
                            if (serverData.cacheHighlights !== undefined) updates.cacheHighlights = serverData.cacheHighlights;
                        }

                        if (adv.sounds) {
                            if (serverData.sfxEnabled !== undefined) updates.sfxEnabled = serverData.sfxEnabled;
                            if (serverData.enabledSounds !== undefined) updates.enabledSounds = serverData.enabledSounds;
                            if (serverData.replaceSearchWithConfirm !== undefined) updates.replaceSearchWithConfirm = serverData.replaceSearchWithConfirm;
                            if (serverData.replaceAllSoundsWithCursor !== undefined) updates.replaceAllSoundsWithCursor = serverData.replaceAllSoundsWithCursor;
                            if (serverData.soundConfigs !== undefined) updates.soundConfigs = serverData.soundConfigs;
                        }

                        if (adv.keybinds) {
                            if (serverData.customKeybinds !== undefined) updates.customKeybinds = serverData.customKeybinds;
                            if (serverData.disabledKeybinds !== undefined) updates.disabledKeybinds = serverData.disabledKeybinds;
                        }
                    }

                    if (syncOptions.googleDrive && serverData.googleDriveApiKey !== undefined) {
                        updates.googleDriveApiKey = serverData.googleDriveApiKey;
                    }

                    if (Object.keys(updates).length > 0) {
                        console.log('[Sync Pull] Applying updates for keys:', Object.keys(updates));
                        setState(updates);

                        // If activeProjectId is no longer valid after update, switch to the first available project
                        const finalProjects = (updates.projects ?? state.projects) as Array<{ id: string; projectId?: string }>;
                        if (Array.isArray(finalProjects) && finalProjects.length > 0) {
                            const currentActiveId = useStore.getState().activeProjectId;
                            const isStillValid = finalProjects.some(p => p.id === currentActiveId);

                            if (!isStillValid) {
                                const firstProject = finalProjects[0];
                                useStore.getState().setActiveProject(firstProject.id);

                                const finalStorages = (updates.storages ?? state.storages) as Array<{ id: string; projectId?: string }>;
                                if (Array.isArray(finalStorages)) {
                                    const projectStorage = finalStorages.find(s => s.projectId === firstProject.id);
                                    if (projectStorage) {
                                        useStore.getState().setState({ activeStorageId: projectStorage.id });
                                    }
                                }
                            }
                        }
                    }
                }
            }

            const now = Date.now();
            setLastSyncTime(now);
            authStorage.setLastSync(now.toString());
            setSyncStatus("success");
        } catch (err) {
            if (err instanceof DOMException && err.name === 'AbortError') {
                // Another sync request superseded this one — don't touch status.
                return;
            }
            console.error("Sync Error:", err);
            setError("Network error");
            setSyncStatus("error");
        }
    }, [setLastSyncTime, setState, setSyncStatus, logout]);

    // Clean up on unmount
    useEffect(() => {
        return () => {
            activeAbortController?.abort();
        };
    }, []);

    return { handleSync, error, syncStatus };
}

/**
 * ============================================================================
 * APPEARANCE SLICE
 * ============================================================================
 *
 * Manages all visual customization: accent/base themes, custom theme editing,
 * background images/gradients, ambient music, default entity colors,
 * window outline, and toggle theming.
 * ============================================================================
 */

import type { StoreSet, StoreGet } from '../types';
import type { AccentTheme, BaseTheme, CustomAccentTheme, CustomBaseTheme } from '@/types';
import { DEFAULT_CUSTOM_THEMES, DEFAULT_CUSTOM_ACCENT_THEMES } from '../helpers/themeDefaults';

export const createAppearanceSlice = (set: StoreSet, _get: StoreGet) => ({
  /* ── Theme State ──────────────────────────────────────────────────────── */

  /** Active accent theme preset name or custom slot ID */
  accentTheme: 'orange' as AccentTheme,
  /** Whether using preset or custom accent themes */
  accentThemeMode: 'presets' as 'presets' | 'custom',
  /** User-customized accent theme slots */
  customAccentThemes: DEFAULT_CUSTOM_ACCENT_THEMES as Record<string, CustomAccentTheme>,

  /** Active base theme preset name or custom slot ID */
  baseTheme: 'zinc' as BaseTheme,
  /** Whether using preset or custom base themes */
  baseThemeMode: 'presets' as 'presets' | 'custom',
  /** User-customized base theme slots */
  customBaseThemes: DEFAULT_CUSTOM_THEMES as Record<string, CustomBaseTheme>,

  /** Whether per-entity default color controls are visible in settings */
  enableDefaultColorControls: false,
  /** Default colors for new entities (used when creating files, collections, etc.) */
  defaultColors: {
    file: '#f59e0b',
    collection: '#f59e0b',
    storage: '#f59e0b',
    graph: '#f59e0b',
    node: '#f59e0b',
  },

  /* ── Background State ─────────────────────────────────────────────────── */

  /** URL of custom background image (null = no image) */
  backgroundImageUrl: null as string | null,
  /** Opacity of background image (0-1) */
  backgroundImageOpacity: 0.2,
  /** Solid background color (used when no gradient) */
  backgroundColor: '#000000',
  /** CSS gradient string for background */
  backgroundGradient: null as string | null,
  /** Whether to use gradient instead of solid color */
  backgroundIsGradient: false,
  /** Opacity of the dark overlay on top of background (0-1) */
  backgroundOverlayOpacity: 0.5,

  /* ── Ambient Music State ──────────────────────────────────────────────── */

  /** URL of currently playing ambient music (null = none, excluded from persist) */
  ambientMusicUrl: null as string | null,
  /** Display name of ambient music track */
  ambientMusicName: null as string | null,
  /** MIME type of ambient music */
  ambientMusicType: null as string | null,
  /** Whether ambient music is paused */
  ambientMusicPaused: false,
  /** Ambient music volume (0-1) */
  ambientMusicVolume: 0.4,
  /** Array of source IDs currently suppressing ambient music (excluded from persist) */
  ambientMusicSuppressedBy: [] as string[],
  /** IndexedDB key for persisted ambient music blob */
  ambientMusicStorageKey: null as string | null,

  /* ── Display Settings ─────────────────────────────────────────────────── */

  /** Whether to show a thin outline around the app window */
  windowOutlineEnabled: false,
  /** Whether toggle switches use theme accent color */
  toggleThemingEnabled: true,
  /** Whether large toggle buttons use theme accent color */
  largeTogglesThemingEnabled: true,
  /** Whether hover tooltips are shown across the interface */
  tooltipsEnabled: true,
  /** Whether to hide the played-color trail behind media seekbars */
  hideSeekbarProgressTrail: false,

  /* ── Theme Actions ────────────────────────────────────────────────────── */

  setAccentTheme: (theme: AccentTheme) => set({ accentTheme: theme }),
  setAccentThemeMode: (mode: 'presets' | 'custom') => set({ accentThemeMode: mode }),

  /** Update a custom accent theme slot. Merges colors partially. */
  setCustomAccentTheme: (id: string, theme: Partial<CustomAccentTheme>) =>
    set((state) => ({
      customAccentThemes: {
        ...(state.customAccentThemes || DEFAULT_CUSTOM_ACCENT_THEMES),
        [id]: {
          ...(state.customAccentThemes?.[id] || DEFAULT_CUSTOM_ACCENT_THEMES[id]),
          ...theme,
          colors: {
            ...(state.customAccentThemes?.[id]?.colors || DEFAULT_CUSTOM_ACCENT_THEMES[id].colors),
            ...(theme.colors || {}),
          },
        },
      },
    })),

  setBaseTheme: (theme: BaseTheme) => set({ baseTheme: theme }),
  setBaseThemeMode: (mode: 'presets' | 'custom') => set({ baseThemeMode: mode }),

  /** Update a custom base theme slot. Merges colors partially. */
  setCustomBaseTheme: (id: string, theme: Partial<CustomBaseTheme>) =>
    set((state) => ({
      customBaseThemes: {
        ...(state.customBaseThemes || DEFAULT_CUSTOM_THEMES),
        [id]: {
          ...(state.customBaseThemes?.[id] || DEFAULT_CUSTOM_THEMES[id]),
          ...theme,
          colors: {
            ...(state.customBaseThemes?.[id]?.colors || DEFAULT_CUSTOM_THEMES[id].colors),
            ...(theme.colors || {}),
          },
        },
      },
    })),

  setEnableDefaultColorControls: (enabled: boolean) => set({ enableDefaultColorControls: enabled }),

  /** Set the default color for a specific entity type */
  setDefaultColor: (entity: 'file' | 'collection' | 'storage' | 'graph' | 'node', color: string) =>
    set((state) => ({
      defaultColors: { ...(state.defaultColors || {}), [entity]: color },
    })),

  /* ── Background Actions ───────────────────────────────────────────────── */

  setBackgroundImageUrl: (url: string | null) => set({ backgroundImageUrl: url }),
  setBackgroundImageOpacity: (opacity: number) =>
    set({ backgroundImageOpacity: Math.max(0, Math.min(1, opacity)) }),
  setBackgroundColor: (color: string) => set({ backgroundColor: color }),
  setBackgroundGradient: (gradient: string) => set({ backgroundGradient: gradient }),
  setBackgroundIsGradient: (isGradient: boolean) => set({ backgroundIsGradient: isGradient }),
  setBackgroundOverlayOpacity: (opacity: number) => set({ backgroundOverlayOpacity: opacity }),

  /* ── Ambient Music Actions ────────────────────────────────────────────── */

  setAmbientMusicPaused: (paused: boolean) => set({ ambientMusicPaused: paused }),

  /** Set ambient music URL + metadata. Automatically unpauses. */
  setAmbientMusicUrl: (url: string | null, name: string | null = null, type: string | null = null) =>
    set({ ambientMusicUrl: url, ambientMusicName: name, ambientMusicType: type, ambientMusicPaused: false }),

  setAmbientMusicVolume: (volume: number) =>
    set({ ambientMusicVolume: Math.max(0, Math.min(1, volume)) }),

  /** Register a source that's suppressing ambient music (e.g., video playback) */
  addAmbientMusicSuppression: (source: string) =>
    set((state) => ({
      ambientMusicSuppressedBy: state.ambientMusicSuppressedBy.includes(source)
        ? state.ambientMusicSuppressedBy
        : [...state.ambientMusicSuppressedBy, source],
    })),

  /** Remove a suppression source (ambient music resumes when all sources removed) */
  removeAmbientMusicSuppression: (source: string) =>
    set((state) => ({
      ambientMusicSuppressedBy: state.ambientMusicSuppressedBy.filter((s) => s !== source),
    })),

  setAmbientMusicStorageKey: (key: string | null) => set({ ambientMusicStorageKey: key }),

  /* ── Display Setting Actions ──────────────────────────────────────────── */

  setWindowOutlineEnabled: (enabled: boolean) => set({ windowOutlineEnabled: enabled }),
  setToggleThemingEnabled: (enabled: boolean) => set({ toggleThemingEnabled: enabled }),
  setLargeTogglesThemingEnabled: (enabled: boolean) => set({ largeTogglesThemingEnabled: enabled }),
  setTooltipsEnabled: (enabled: boolean) => set({ tooltipsEnabled: enabled }),
  setHideSeekbarProgressTrail: (enabled: boolean) => set({ hideSeekbarProgressTrail: enabled }),
});

/**
 * ============================================================================
 * AUTH SLICE
 * ============================================================================
 *
 * Manages authentication state and sync configuration.
 * Handles user login/logout, sync timing, status, and per-entity sync options.
 * ============================================================================
 */

import type { StoreSet, StoreGet, AppStore, User, SyncStatus } from '../types';

export const createAuthSlice = (set: StoreSet, _get: StoreGet) => ({
  /* ── State ────────────────────────────────────────────────────────────── */

  /** Currently authenticated user (null = not logged in) */
  user: null as User | null,
  /** Timestamp of last successful sync */
  lastSyncTime: null as number | null,
  /** Current sync operation status */
  syncStatus: 'idle' as SyncStatus,

  /** Granular control over what data gets synced */
  syncOptions: {
    projects: true,
    files: true,
    collections: true,
    highlights: true,
    docs: true,
    graphs: true,
    storages: true,
    history: true,
    trash: true,
    settings: true,
    googleDrive: true,
    advancedSettings: {
      appearance: true,
      music: true,
      playback: true,
      cache: true,
      sounds: true,
      keybinds: true,
    },
  },

  /* ── Actions ──────────────────────────────────────────────────────────── */

  login: (user: User) => set({ user }),
  logout: () => set({ user: null }),
  updateUser: (updates: Partial<User>) =>
    set((state) => ({ user: state.user ? { ...state.user, ...updates } : null })),

  setLastSyncTime: (time: number) => set({ lastSyncTime: time }),
  setSyncStatus: (status: SyncStatus) => set({ syncStatus: status }),

  /** Merge partial sync options (supports nested advancedSettings) */
  setSyncOptions: (options: Partial<AppStore['syncOptions']>) =>
    set((state) => {
      const newOptions = { ...state.syncOptions, ...options };
      if (options.advancedSettings) {
        newOptions.advancedSettings = {
          ...state.syncOptions.advancedSettings,
          ...options.advancedSettings,
        };
      }
      return { syncOptions: newOptions };
    }),
});

/**
 * ============================================================================
 * DATA SLICE
 * ============================================================================
 *
 * Manages core data arrays and active entity IDs.
 * Provides bulk setters (for sync/migration) and individual active-entity
 * setters that also update `lastViewed` timestamps.
 *
 * NOTE: Entity CRUD (add/update/delete) is in entitySlice, projectSlice,
 *       highlightSlice, and graphEditSlice. This slice only handles
 *       the raw array state and selection.
 * ============================================================================
 */

import type { StoreSet, StoreGet } from '../types';
import type { Project, File, Collection, Highlight, Graph, GraphNode, GraphEdge, Doc, Storage, HistoryEntry } from '@/types';
import { sanitizeHighlightCollectionIds } from '@/utils/collectionUtils';

export const createDataSlice = (set: StoreSet, _get: StoreGet) => ({
  /* ── Core Data Arrays ─────────────────────────────────────────────────── */
  /** All projects in the store */
  projects: [] as Project[],
  /** All files across all projects/storages */
  files: [] as File[],
  /** All collections (buckets, folders, collections) */
  collections: [] as Collection[],
  /** All highlights (video timestamps, image regions, PDF selections) */
  highlights: [] as Highlight[],
  /** All graphs */
  graphs: [] as Graph[],
  /** All graph nodes */
  graphNodes: [] as GraphNode[],
  /** All graph edges */
  graphEdges: [] as GraphEdge[],
  /** All documents */
  docs: [] as Doc[],
  /** All storages (file containers within projects) */
  storages: [] as Storage[],

  /* ── Active Entity IDs ────────────────────────────────────────────────── */
  /** Currently selected project */
  activeProjectId: null as string | null,
  /** Currently selected storage within the project */
  activeStorageId: null as string | null,
  /** Currently selected collection (bucket) */
  activeCollectionId: null as string | null,
  /** Currently selected graph */
  activeGraphId: null as string | null,
  /** Currently selected document */
  activeDocId: null as string | null,
  /** Currently selected file */
  activeFileId: null as string | null,
  /** Currently selected highlight */
  activeHighlightId: null as string | null,

  /* ── History ──────────────────────────────────────────────────────────── */
  /** Action history log (newest first) */
  history: [] as HistoryEntry[],
  historyEnabled: true,
  historyClearRange: 'all-time' as const,
  trashClearRange: 'all-time' as const,

  /* ── Bulk Setters (used by sync/migration to replace entire arrays) ──── */

  setProjects: (projects: Project[]) => set({ projects }),
  setFiles: (files: File[]) => set({ files }),
  setCollections: (collections: Collection[]) =>
    set((state) => ({
      collections,
      highlights: sanitizeHighlightCollectionIds(collections, state.highlights),
    })),
  setHighlights: (highlights: Highlight[]) =>
    set((state) => ({
      highlights: sanitizeHighlightCollectionIds(state.collections, highlights),
    })),

  /* ── Active Entity Setters ────────────────────────────────────────────── */

  setActiveProject: (id: string | null) => set({ activeProjectId: id }),

  /** Set active file and update its lastViewed timestamp */
  setActiveFile: (id: string | null) =>
    set((state) => ({
      activeFileId: id,
      files: id
        ? state.files.map((f) => (f.id === id ? { ...f, lastViewed: Date.now() } : f))
        : state.files,
    })),

  setActiveHighlight: (id: string | null) => set({ activeHighlightId: id }),

  /** Set active collection and update its lastViewed timestamp */
  setActiveCollection: (id: string | null) =>
    set((state) => ({
      activeCollectionId: id,
      collections: id
        ? state.collections.map((c) => (c.id === id ? { ...c, lastViewed: Date.now() } : c))
        : state.collections,
    })),

  /** Set active doc and update its lastViewed timestamp */
  setActiveDoc: (id: string | null) =>
    set((state) => ({
      activeDocId: id,
      docs: id
        ? state.docs.map((d) => (d.id === id ? { ...d, lastViewed: Date.now() } : d))
        : state.docs,
    })),

  /** Set active graph and update its lastViewed timestamp */
  setActiveGraph: (id: string | null) =>
    set((state) => ({
      activeGraphId: id,
      graphs: id
        ? state.graphs.map((g) => (g.id === id ? { ...g, lastViewed: Date.now() } : g))
        : state.graphs,
    })),
});

/**
 * ============================================================================
 * ENTITY SLICE
 * ============================================================================
 *
 * CRUD operations for storages, docs, graphs, files, and collections.
 * Each add/update/delete operation also logs to history.
 *
 * NOTE: Project CRUD is in projectSlice.ts.
 * NOTE: Trash operations (soft delete) are in trashSlice.ts.
 * NOTE: deleteStorage here is a SOFT delete (marks deleted: true).
 * ============================================================================
 */

import type { StoreSet, StoreGet } from '../types';
import type { Storage, Doc, Graph, File, Collection } from '@/types';
import { appendHistoryEntriesIfEnabled } from '../helpers/historyTracking';

export const createEntitySlice = (set: StoreSet, _get: StoreGet) => ({
  /* ── Storage CRUD ─────────────────────────────────────────────────────── */

  /** Create a new storage container within a project */
  addStorage: (name: string, projectId: string, color?: string, icon?: string) =>
    set((state) => {
      const newStorage: Storage = {
        id: crypto.randomUUID(),
        projectId,
        name,
        color,
        icon,
        created: Date.now(),
        lastModified: Date.now(),
      };
      return {
        storages: [...state.storages, newStorage],
        activeStorageId: newStorage.id,
        history: appendHistoryEntriesIfEnabled(state, [
          {
            projectId: state.activeProjectId || 'global',
            action: 'create',
            entityType: 'storage',
            entityId: newStorage.id,
            entityName: name,
          },
        ]),
      };
    }),

  /** Update storage metadata (name, color, icon) */
  updateStorage: (id: string, updates: Partial<Storage>) =>
    set((state) => ({
      storages: state.storages.map((s) =>
        s.id === id ? { ...s, ...updates, lastModified: Date.now() } : s
      ),
      history: appendHistoryEntriesIfEnabled(state, [
        {
          projectId: state.activeProjectId || 'global',
          action: 'update',
          entityType: 'storage',
          entityId: id,
          entityName: state.storages.find((s) => s.id === id)?.name,
        },
      ]),
    })),

  /**
   * Soft-delete a storage (marks deleted: true).
   * Files within the storage are preserved for potential restore.
   * If the deleted storage was active, switches to next available.
   */
  deleteStorage: (id: string) =>
    set((state) => {
      const storage = state.storages.find((s) => s.id === id) || null;
      let nextActiveStorageId = state.activeStorageId;

      // If deleting the active storage, find a replacement
      if (state.activeStorageId === id) {
        const projectId = storage?.projectId || state.activeProjectId;
        if (projectId) {
          const projectStorages = state.storages.filter(
            (s) => s.projectId === projectId && s.id !== id && !s.deleted
          );
          nextActiveStorageId = projectStorages.length > 0 ? projectStorages[0].id : null;
        } else {
          nextActiveStorageId = null;
        }
      }

      return {
        storages: state.storages.map((s) =>
          s.id === id ? { ...s, deleted: true, lastModified: Date.now() } : s
        ),
        activeStorageId: nextActiveStorageId,
        history: appendHistoryEntriesIfEnabled(state, [
          {
            projectId: storage?.projectId ?? (state.activeProjectId || 'global'),
            action: 'delete',
            entityType: 'storage',
            entityId: id,
            entityName: storage?.name,
            details: 'Moved to Trash',
          },
        ]),
      };
    }),

  /* ── Doc CRUD ─────────────────────────────────────────────────────────── */

  /** Create a new document within a project */
  addDoc: (name: string, projectId: string, color?: string, icon?: string) =>
    set((state) => {
      const newDoc: Doc = {
        id: crypto.randomUUID(),
        projectId,
        name,
        content: '<p>Start writing...</p>',
        color,
        icon,
        created: Date.now(),
        lastModified: Date.now(),
      };
      return {
        docs: [...state.docs, newDoc],
        activeDocId: newDoc.id,
        history: appendHistoryEntriesIfEnabled(state, [
          {
            projectId: state.activeProjectId || 'global',
            action: 'create',
            entityType: 'doc',
            entityId: newDoc.id,
            entityName: name,
          },
        ]),
      };
    }),

  /** Update document metadata or content */
  updateDoc: (id: string, updates: Partial<Doc>) =>
    set((state) => ({
      docs: state.docs.map((d) =>
        d.id === id ? { ...d, ...updates, lastModified: Date.now() } : d
      ),
      history: appendHistoryEntriesIfEnabled(state, [
        {
          projectId: state.activeProjectId || 'global',
          action: 'update',
          entityType: 'doc',
          entityId: id,
          entityName: state.docs.find((d) => d.id === id)?.name,
        },
      ]),
    })),

  /* ── Graph CRUD ───────────────────────────────────────────────────────── */

  /** Create a new graph within a project */
  addGraph: (name: string, projectId: string, color?: string, icon?: string) =>
    set((state) => {
      const newGraph: Graph = {
        id: crypto.randomUUID(),
        projectId,
        name,
        color,
        icon,
        created: Date.now(),
        lastModified: Date.now(),
      };
      return {
        graphs: [...state.graphs, newGraph],
        activeGraphId: newGraph.id,
        history: appendHistoryEntriesIfEnabled(state, [
          {
            projectId: state.activeProjectId || 'global',
            action: 'create',
            entityType: 'graph',
            entityId: newGraph.id,
            entityName: name,
          },
        ]),
      };
    }),

  /** Update graph metadata (name, color, icon). Also used for graph content updates. */
  updateGraph: (id: string, updates: Partial<Graph>) =>
    set((state) => ({
      graphs: state.graphs.map((g) =>
        g.id === id ? { ...g, ...updates, lastModified: Date.now() } : g
      ),
      history: appendHistoryEntriesIfEnabled(state, [
        {
          projectId: state.activeProjectId || 'global',
          action: 'update',
          entityType: 'graph',
          entityId: id,
          entityName: state.graphs.find((g) => g.id === id)?.name,
        },
      ]),
    })),

  /* ── File Update ──────────────────────────────────────────────────────── */

  /** Update file metadata (name, color, icon, description, etc.) */
  updateFile: (id: string, updates: Partial<File>) =>
    set((state) => ({
      files: state.files.map((f) => {
        if (f.id !== id) return f;
        return { ...f, ...updates, lastModified: Date.now() } as File;
      }),
      history: appendHistoryEntriesIfEnabled(state, [
        {
          projectId: state.activeProjectId || 'global',
          action: 'update',
          entityType: 'file',
          entityId: id,
          entityName: state.files.find((f) => f.id === id)?.name,
        },
      ]),
    })),

  /* ── Collection Update ────────────────────────────────────────────────── */

  /** Update collection metadata (name, color, icon, order, parentId, etc.) */
  updateCollection: (id: string, updates: Partial<Collection>) =>
    set((state) => ({
      collections: state.collections.map((c) =>
        c.id === id ? { ...c, ...updates, lastModified: Date.now() } : c
      ),
      history: appendHistoryEntriesIfEnabled(state, [
        {
          projectId: state.activeProjectId || 'global',
          action: 'update',
          entityType: 'collection',
          entityId: id,
          entityName: state.collections.find((c) => c.id === id)?.name,
        },
      ]),
    })),
});

/**
 * ============================================================================
 * GRAPH EDIT SLICE
 * ============================================================================
 *
 * CRUD for graph nodes and edges (the internal elements of a graph).
 * Graph-level CRUD (add/update/delete graph) is in entitySlice.
 * ============================================================================
 */

import type { StoreSet, StoreGet } from '../types';
import type { GraphNode, GraphEdge } from '@/types';
import { appendHistoryEntriesIfEnabled } from '../helpers/historyTracking';

export const createGraphEditSlice = (set: StoreSet, _get: StoreGet) => ({
  /** Add a new node to a graph */
  addNode: (node: GraphNode) =>
    set((state) => ({
      graphNodes: [...state.graphNodes, node],
      history: appendHistoryEntriesIfEnabled(state, [
        {
          projectId: state.activeProjectId || 'global',
          action: 'create',
          entityType: 'node',
          entityId: node.id,
          entityName: node.title,
        },
      ]),
    })),

  /**
   * Update node properties.
   * Position updates (x/y only) skip history logging to avoid spam during dragging.
   */
  updateNode: (id: string, updates: Partial<GraphNode>) =>
    set((state) => ({
      graphNodes: state.graphNodes.map((n) => (n.id === id ? { ...n, ...updates } : n)),
      // Skip history for position-only updates (drag operations)
      history:
        updates.x !== undefined || updates.y !== undefined
          ? state.history
          : appendHistoryEntriesIfEnabled(state, [
              {
                projectId: state.activeProjectId || 'global',
                action: 'update',
                entityType: 'node',
                entityId: id,
                entityName: state.graphNodes.find((n) => n.id === id)?.title,
              },
            ]),
    })),

  /** Remove a node and all edges connected to it */
  removeNode: (id: string) =>
    set((state) => ({
      graphNodes: state.graphNodes.filter((n) => n.id !== id),
      graphEdges: state.graphEdges.filter((e) => e.fromId !== id && e.toId !== id),
      history: appendHistoryEntriesIfEnabled(state, [
        {
          projectId: state.activeProjectId || 'global',
          action: 'delete',
          entityType: 'node',
          entityId: id,
          entityName: state.graphNodes.find((n) => n.id === id)?.title,
        },
      ]),
    })),

  /** Add an edge (connection) between two nodes */
  addEdge: (edge: GraphEdge) =>
    set((state) => ({
      graphEdges: [...state.graphEdges, edge],
      history: appendHistoryEntriesIfEnabled(state, [
        {
          projectId: state.activeProjectId || 'global',
          action: 'create',
          entityType: 'edge',
          entityId: edge.id,
          entityName: 'Connection',
        },
      ]),
    })),

  /** Remove an edge */
  removeEdge: (id: string) =>
    set((state) => ({
      graphEdges: state.graphEdges.filter((e) => e.id !== id),
      history: appendHistoryEntriesIfEnabled(state, [
        {
          projectId: state.activeProjectId || 'global',
          action: 'delete',
          entityType: 'edge',
          entityId: id,
          entityName: 'Connection',
        },
      ]),
    })),
});

/**
 * ============================================================================
 * HIGHLIGHT SLICE
 * ============================================================================
 *
 * CRUD for highlights: video timestamps, image regions, PDF text selections.
 * Highlights are linked to files and optionally to collections.
 * ============================================================================
 */

import type { StoreSet, StoreGet } from '../types';
import type { Highlight } from '@/types';
import { normalizeLeafCollectionId } from '@/utils/collectionUtils';
import { appendHistoryEntriesIfEnabled } from '../helpers/historyTracking';

export const createHighlightSlice = (set: StoreSet, _get: StoreGet) => ({
  /** Create a video timestamp highlight (start/end in seconds) */
  addVideoHighlight: (fileId: string, start: number, end: number, collectionId?: string) =>
    set((state) => {
      const resolvedCollectionId = normalizeLeafCollectionId(
        state.collections,
        collectionId ?? state.activeCollectionId ?? null
      );
      const highlight: Highlight = {
        id: crypto.randomUUID(),
        fileId,
        start,
        end,
        text: `Timestamp: ${start} - ${end}`,
        note: '',
        created: Date.now(),
        collectionId: resolvedCollectionId,
        color: state.defaultColors?.node,
      };
      return {
        highlights: [...state.highlights, highlight],
        history: appendHistoryEntriesIfEnabled(state, [
          {
            projectId: state.activeProjectId || 'global',
            action: 'create',
            entityType: 'highlight',
            entityId: highlight.id,
            entityName: 'Video Highlight',
          },
        ]),
      };
    }),

  /** Create an image region highlight (rect in percentage coordinates 0-1) */
  addImageHighlight: (
    fileId: string,
    rect: { x: number; y: number; width: number; height: number },
    collectionId?: string
  ) =>
    set((state) => {
      const resolvedCollectionId = normalizeLeafCollectionId(
        state.collections,
        collectionId ?? state.activeCollectionId ?? null
      );
      const highlight: Highlight = {
        id: crypto.randomUUID(),
        fileId,
        rect,
        start: 0,
        end: 0,
        text: 'Image Highlight',
        note: '',
        created: Date.now(),
        collectionId: resolvedCollectionId,
        color: state.defaultColors?.node,
      };
      return {
        highlights: [...state.highlights, highlight],
        history: appendHistoryEntriesIfEnabled(state, [
          {
            projectId: state.activeProjectId || 'global',
            action: 'create',
            entityType: 'highlight',
            entityId: highlight.id,
            entityName: 'Image Highlight',
          },
        ]),
      };
    }),

  /** Create a PDF/generic text highlight */
  addHighlight: (
    fileId: string,
    page: number,
    text: string,
    collectionIdOverride?: string | null,
    pdfRange?: { start: number; end: number } | null,
    rect?: { x: number; y: number; width: number; height: number } | null
  ) =>
    set((state) => {
      const collectionId = normalizeLeafCollectionId(
        state.collections,
        collectionIdOverride ?? state.activeCollectionId ?? null
      );
      const newHighlight: Highlight = {
        id: crypto.randomUUID(),
        fileId,
        collectionId,
        start: page,
        end: page,
        note: '',
        text,
        pdfRange,
        rect: rect ?? undefined,
        created: Date.now(),
      };
      return {
        highlights: [...state.highlights, newHighlight],
        history: appendHistoryEntriesIfEnabled(state, [
          {
            projectId: state.activeProjectId || 'global',
            action: 'create',
            entityType: 'highlight',
            entityId: newHighlight.id,
            entityName: 'Highlight',
          },
        ]),
      };
    }),

  /** Permanently remove a highlight */
  removeHighlight: (id: string) =>
    set((state) => ({
      highlights: state.highlights.filter((t) => t.id !== id),
      history: appendHistoryEntriesIfEnabled(state, [
        {
          projectId: state.activeProjectId || 'global',
          action: 'delete',
          entityType: 'highlight',
          entityId: id,
          entityName: state.highlights.find((t) => t.id === id)?.text || 'Highlight',
        },
      ]),
    })),

  /** Update highlight properties (note, color, collection assignment, etc.) */
  updateHighlight: (id: string, updates: Partial<Highlight>) =>
    set((state) => {
      const normalizedUpdates = Object.prototype.hasOwnProperty.call(updates, 'collectionId')
        ? {
            ...updates,
            collectionId: normalizeLeafCollectionId(state.collections, updates.collectionId),
          }
        : updates;

      return {
      highlights: state.highlights.map((t) => (t.id === id ? { ...t, ...normalizedUpdates } : t)),
      history: appendHistoryEntriesIfEnabled(state, [
        {
          projectId: state.activeProjectId || 'global',
          action: 'update',
          entityType: 'highlight',
          entityId: id,
          entityName: state.highlights.find((t) => t.id === id)?.text || 'Highlight',
        },
      ]),
    };
    }),
});

/**
 * ============================================================================
 * HISTORY SLICE
 * ============================================================================
 *
 * Manages the action history log. All entity CRUD operations prepend
 * entries to history[] from their own slices. This slice provides
 * the explicit logAction() and clearHistory() actions.
 * ============================================================================
 */

import type { StoreSet, StoreGet } from '../types';
import type { ActivityClearRange, HistoryEntry } from '@/types';
import { isTimestampInActivityRange } from '@/lib/activityRanges';
import { appendHistoryEntriesIfEnabled } from '../helpers/historyTracking';

export const createHistorySlice = (set: StoreSet, _get: StoreGet) => ({
  /** Manually log an action to history (auto-generated id + timestamp) */
  logAction: (entry: Omit<HistoryEntry, 'id' | 'timestamp'>) =>
    set((state) => ({
      history: appendHistoryEntriesIfEnabled(state, [entry]),
    })),

  /** Clear history using the remembered or explicitly provided range */
  clearHistory: (range?: ActivityClearRange) =>
    set((state) => {
      const activeRange = range ?? state.historyClearRange ?? 'all-time';
      const now = Date.now();

      if (activeRange === 'all-time') {
        return { history: [] };
      }

      return {
        history: state.history.filter(
          (entry) => !isTimestampInActivityRange(entry.timestamp, activeRange, now)
        ),
      };
    }),

  /** Remove a single history row without affecting the rest of the log */
  removeHistoryEntry: (id: string) =>
    set((state) => ({
      history: state.history.filter((entry) => entry.id !== id),
    })),

  /** Toggle whether future history entries should be recorded */
  setHistoryEnabled: (enabled: boolean) => set({ historyEnabled: enabled }),

  /** Remember the last-used history clear range */
  setHistoryClearRange: (range: ActivityClearRange) => set({ historyClearRange: range }),

  /** Remember the last-used trash clear range */
  setTrashClearRange: (range: ActivityClearRange) => set({ trashClearRange: range }),
});

/**
 * ============================================================================
 * KEYBIND SLICE
 * ============================================================================
 *
 * Manages custom keybind overrides and disabled keybinds.
 * Users can remap any action to a different key combo or disable it entirely.
 *
 * State:
 *  - customKeybinds: Record mapping actionId → custom key string
 *  - disabledKeybinds: Array of actionIds that are turned off
 *
 * Actions:
 *  - setKeybind: Assign a new key to an action
 *  - toggleKeybind: Enable/disable an action's keybind
 *  - resetKeybinds: Clear all customizations back to defaults
 * ============================================================================
 */

import type { StoreSet, StoreGet } from '../types';

export const createKeybindSlice = (set: StoreSet, _get: StoreGet) => ({
  /* ── State ────────────────────────────────────────────────────────────── */
  customKeybinds: {} as Record<string, string>,
  disabledKeybinds: [] as string[],

  /* ── Actions ──────────────────────────────────────────────────────────── */

  /** Override the key binding for a specific action */
  setKeybind: (actionId: string, key: string) =>
    set((state) => ({
      customKeybinds: { ...state.customKeybinds, [actionId]: key },
    })),

  /** Enable or disable a keybind without removing the custom mapping */
  toggleKeybind: (actionId: string, enabled: boolean) =>
    set((state) => {
      const disabled = new Set(state.disabledKeybinds);
      if (enabled) {
        disabled.delete(actionId);
      } else {
        disabled.add(actionId);
      }
      return { disabledKeybinds: Array.from(disabled) };
    }),

  /** Reset all keybinds to default (clear custom mappings and re-enable all) */
  resetKeybinds: () => set({ customKeybinds: {}, disabledKeybinds: [] }),
});

/**
 * ============================================================================
 * PLAYBACK SLICE
 * ============================================================================
 *
 * Manages media playback state: PiP (Picture-in-Picture), floating player
 * windows, per-file video/audio settings, zoom levels, volume, and cache.
 * ============================================================================
 */

import type { StoreSet, StoreGet } from '../types';
import type { FloatingPlayerWindow } from '@/types';

export const createPlaybackSlice = (set: StoreSet, _get: StoreGet) => ({
  /* ── PiP State ────────────────────────────────────────────────────────── */

  /** File ID currently shown in PiP */
  pipFileId: null as string | null,
  /** Whether PiP overlay is visible */
  isPipOpen: false,
  /** Per-file playback position in seconds (fileId → seconds) */
  fileProgress: {} as Record<string, number>,

  /* ── Floating Player Windows ──────────────────────────────────────────── */

  /** Array of floating player window instances */
  floatingPlayerWindows: [] as FloatingPlayerWindow[],

  /* ── Video/Audio Settings ─────────────────────────────────────────────── */

  /** Per-file zoom level (fileId → zoom multiplier) */
  videoZoomByFile: {} as Record<string, number>,
  /** Whether zoom was set manually (vs auto-fit) per file */
  videoZoomManualByFile: {} as Record<string, boolean>,
  /** Mute new videos by default until user explicitly unmutes */
  muteNewVideosUntilUnmuted: true,
  /** Mute highlights by default until user unmutes */
  muteHighlightsUntilUnmuted: false,
  /** Always show the mute indicator overlay on videos */
  alwaysShowMuteOverlay: false,
  /** Browser-restricted Google Drive API key for native Drive playback */
  googleDriveApiKey: '',
  /** Cache Google Drive file blobs in IndexedDB to reduce API quota usage */
  googleDriveCacheEnabled: true,
  /** Remember per-file volume across sessions */
  rememberMediaVolume: false,
  /** Disable auto-play when opening media files */
  disableMediaAutoplay: false,
  /** Per-file video volume (fileId → 0.0-1.0) */
  videoVolumeByFile: {} as Record<string, number>,
  /** Per-file audio volume (fileId → 0.0-1.0) */
  audioVolumeByFile: {} as Record<string, number>,
  /** Per-file unmuted state (fileId → boolean) */
  videoUnmutedByFile: {} as Record<string, boolean>,
  /** Use middle frame for video preview thumbnails instead of first frame */
  useMiddleFrameForPreviews: true,
  /** Preferred highlight viewer list scope in the highlight playback dialog */
  highlightViewerListMode: 'video' as 'video' | 'collection',

  /* ── Cache Settings ───────────────────────────────────────────────────── */

  /** Cache file data for faster loading */
  cacheFiles: true,
  /** Cache collection metadata */
  cacheCollections: true,
  /** Cache highlight data */
  cacheHighlights: true,

  /* ── PiP Actions ──────────────────────────────────────────────────────── */

  setPipFile: (id: string | null) => set({ pipFileId: id, isPipOpen: !!id }),
  togglePip: (isOpen: boolean) => set({ isPipOpen: isOpen }),
  setFileProgress: (fileId: string, time: number) =>
    set((state) => ({
      fileProgress: { ...state.fileProgress, [fileId]: time },
    })),

  /* ── Floating Player Actions ──────────────────────────────────────────── */

  /** Open a new floating player window for a file. Returns the window ID. */
  addFloatingPlayer: (id: string) => {
    const windowId = crypto.randomUUID();
    set((state) => ({
      floatingPlayerWindows: [
        ...state.floatingPlayerWindows,
        { id: windowId, fileId: id, minimized: false },
      ],
    }));
    return windowId;
  },

  removeFloatingPlayer: (id: string) =>
    set((state) => ({
      floatingPlayerWindows: state.floatingPlayerWindows.filter((w) => w.id !== id),
    })),

  setFloatingPlayerMinimized: (id: string, minimized: boolean) =>
    set((state) => ({
      floatingPlayerWindows: state.floatingPlayerWindows.map((w) =>
        w.id === id ? { ...w, minimized } : w
      ),
    })),

  setFloatingPlayerFile: (id: string, fileId: string) =>
    set((state) => ({
      floatingPlayerWindows: state.floatingPlayerWindows.map((w) =>
        w.id === id ? { ...w, fileId } : w
      ),
    })),

  /** Move a floating player to the top of the z-order stack */
  bringFloatingPlayerToFront: (id: string) =>
    set((state) => {
      const target = state.floatingPlayerWindows.find((w) => w.id === id);
      if (!target) return state;
      return {
        floatingPlayerWindows: [
          ...state.floatingPlayerWindows.filter((w) => w.id !== id),
          target,
        ],
      };
    }),

  /* ── Video/Audio Setting Actions ──────────────────────────────────────── */

  setVideoZoomForFile: (fileId: string, zoom: number) =>
    set((state) => ({
      videoZoomByFile: { ...(state.videoZoomByFile || {}), [fileId]: zoom },
    })),

  setVideoZoomManualForFile: (fileId: string, manual: boolean) =>
    set((state) => ({
      videoZoomManualByFile: { ...(state.videoZoomManualByFile || {}), [fileId]: manual },
    })),

  setMuteNewVideosUntilUnmuted: (enabled: boolean) => set({ muteNewVideosUntilUnmuted: enabled }),
  setMuteHighlightsUntilUnmuted: (enabled: boolean) => set({ muteHighlightsUntilUnmuted: enabled }),
  setAlwaysShowMuteOverlay: (enabled: boolean) => set({ alwaysShowMuteOverlay: enabled }),
  setGoogleDriveApiKey: (apiKey: string) => set({ googleDriveApiKey: apiKey.trim() }),
  setGoogleDriveCacheEnabled: (enabled: boolean) => set({ googleDriveCacheEnabled: enabled }),
  setRememberMediaVolume: (enabled: boolean) => set({ rememberMediaVolume: enabled }),
  setDisableMediaAutoplay: (enabled: boolean) => set({ disableMediaAutoplay: enabled }),

  setVideoVolumeForFile: (fileId: string, volume: number) =>
    set((state) => ({
      videoVolumeByFile: { ...(state.videoVolumeByFile || {}), [fileId]: volume },
    })),

  setAudioVolumeForFile: (fileId: string, volume: number) =>
    set((state) => ({
      audioVolumeByFile: { ...(state.audioVolumeByFile || {}), [fileId]: volume },
    })),

  setVideoUnmutedForFile: (fileId: string, unmuted: boolean) =>
    set((state) => ({
      videoUnmutedByFile: { ...(state.videoUnmutedByFile || {}), [fileId]: unmuted },
    })),

  setUseMiddleFrameForPreviews: (enabled: boolean) => set({ useMiddleFrameForPreviews: enabled }),
  setHighlightViewerListMode: (mode: 'video' | 'collection') => set({ highlightViewerListMode: mode }),
  setCacheFiles: (enabled: boolean) => set({ cacheFiles: enabled }),
  setCacheCollections: (enabled: boolean) => set({ cacheCollections: enabled }),
  setCacheHighlights: (enabled: boolean) => set({ cacheHighlights: enabled }),

  /** Clear all saved per-file volume settings */
  clearMediaVolumes: () => set({ videoVolumeByFile: {}, audioVolumeByFile: {} }),
});

/**
 * ============================================================================
 * PROJECT SLICE
 * ============================================================================
 *
 * Handles project-level CRUD: creating projects (with default storage + bucket),
 * updating project metadata, and deleting projects (cascading cleanup).
 * ============================================================================
 */

import type { StoreSet, StoreGet } from '../types';
import type { Project, Collection, File } from '@/types';
import { appendHistoryEntriesIfEnabled } from '../helpers/historyTracking';

export const createProjectSlice = (set: StoreSet, _get: StoreGet) => ({
  /**
   * Create a new project with a default storage and "Collections" bucket.
   * If this is the first project, it becomes the active project automatically.
   */
  addProject: (name: string) => {
    const newProject: Project = {
      id: crypto.randomUUID(),
      name,
      created: Date.now(),
      lastModified: Date.now(),
    };

    // Create default storage container for the project
    const defaultStorage = {
      id: crypto.randomUUID(),
      projectId: newProject.id,
      name: 'Main Storage',
      created: Date.now(),
      lastModified: Date.now(),
    };

    // Create default "Collections" bucket (root collection container)
    const defaultBucket: Collection = {
      id: crypto.randomUUID(),
      projectId: newProject.id,
      parentId: null,
      name: 'Collections',
      color: '#71717a', // grey (zinc-500)
      icon: 'FolderOpen',
      type: 'bucket',
      order: 0,
      created: Date.now(),
      lastModified: Date.now(),
    };

    set((state) => ({
      projects: [...state.projects, newProject],
      storages: [...state.storages, defaultStorage],
      collections: [...state.collections, defaultBucket],
      // Auto-select if this is the first project
      activeProjectId: state.projects.length === 0 ? newProject.id : state.activeProjectId,
      activeStorageId: state.projects.length === 0 ? defaultStorage.id : state.activeStorageId,
      activeCollectionId: state.projects.length === 0 ? defaultBucket.id : state.activeCollectionId,
      // Log history
      history: appendHistoryEntriesIfEnabled(state, [
        {
          projectId: newProject.id,
          action: 'create',
          entityType: 'project',
          entityId: newProject.id,
          entityName: name,
        },
      ]),
    }));
    return newProject;
  },

  /** Update project metadata (name, etc.) */
  updateProject: (id: string, updates: Partial<Project>) =>
    set((state) => ({
      projects: state.projects.map((p) =>
        p.id === id ? { ...p, ...updates, lastModified: Date.now() } : p
      ),
      history: appendHistoryEntriesIfEnabled(state, [
        {
          projectId: id,
          action: 'update',
          entityType: 'project',
          entityId: id,
          entityName: state.projects.find((p) => p.id === id)?.name,
        },
      ]),
    })),

  /**
   * Permanently delete a project and ALL its associated data:
   * files, collections, graphs, docs, storages, highlights, nodes, edges.
   * Switches active project to next available project.
   */
  deleteProject: (id: string) =>
    set((state) => {
      const remainingProjects = state.projects.filter((p) => p.id !== id);
      const deletedProject = state.projects.find((p) => p.id === id) || null;
      const remainingProjectId = remainingProjects[0]?.id || null;

      // Collect IDs of all entities that belong to this project
      const projectFileIds = new Set(
        state.files.filter((f: File) => f.projectId === id).map((f: File) => f.id)
      );
      const projectCollectionIds = new Set(
        state.collections.filter((c: Collection) => c.projectId === id).map((c: Collection) => c.id)
      );
      const projectGraphIds = new Set(
        state.graphs.filter((g) => g.projectId === id).map((g) => g.id)
      );

      return {
        projects: remainingProjects,
        files: state.files.filter((f: File) => f.projectId !== id),
        collections: state.collections.filter((c: Collection) => c.projectId !== id),
        graphs: state.graphs.filter((g) => g.projectId !== id),
        docs: state.docs.filter((d) => d.projectId !== id),
        storages: state.storages.filter((s) => s.projectId !== id),
        highlights: state.highlights.filter(
          (h) =>
            !projectFileIds.has(h.fileId) &&
            !(h.collectionId && projectCollectionIds.has(h.collectionId))
        ),
        graphNodes: state.graphNodes.filter((n) => !projectGraphIds.has(n.graphId)),
        graphEdges: state.graphEdges.filter((e) => !projectGraphIds.has(e.graphId)),
        // Switch to next available project
        activeProjectId: remainingProjectId,
        activeStorageId: remainingProjectId
          ? state.storages.find((s) => s.projectId === remainingProjectId)?.id || null
          : null,
        activeCollectionId: null,
        activeGraphId: null,
        activeDocId: null,
        history: appendHistoryEntriesIfEnabled(state, [
          {
            projectId: id,
            action: 'delete',
            entityType: 'project',
            entityId: id,
            entityName: deletedProject?.name,
            details: 'Delete Project',
          },
        ]),
      };
    }),
});

/**
 * ============================================================================
 * SOUND SLICE
 * ============================================================================
 *
 * Manages sound effects (SFX) settings: which sounds are enabled,
 * custom sound configurations, and global SFX toggles.
 * ============================================================================
 */

import type { StoreSet, StoreGet, SoundKey, SoundConfig } from '../types';

export const createSoundSlice = (set: StoreSet, _get: StoreGet) => ({
  /* ── State ────────────────────────────────────────────────────────────── */

  /** Master toggle for all sound effects */
  sfxEnabled: true,

  /** Per-sound-type enable/disable toggles */
  enabledSounds: {
    cursor: true,
    confirm: true,
    error: true,
    back: true,
    search: true,
  },

  /** When true, the "search" sound plays the "confirm" sound instead */
  replaceSearchWithConfirm: false,
  /** When true, all sounds use the "cursor" sound */
  replaceAllSoundsWithCursor: false,

  /** Per-sound configuration (preset name or custom audio URL) */
  soundConfigs: {
    cursor: { source: 'preset' as const, value: 'cursor' },
    confirm: { source: 'preset' as const, value: 'confirm' },
    error: { source: 'preset' as const, value: 'error' },
    back: { source: 'preset' as const, value: 'back' },
    search: { source: 'preset' as const, value: 'search' },
  } as Record<SoundKey, SoundConfig>,

  /* ── Actions ──────────────────────────────────────────────────────────── */

  setSfxEnabled: (enabled: boolean) => set({ sfxEnabled: enabled }),

  setReplaceSearchWithConfirm: (enabled: boolean) => set({ replaceSearchWithConfirm: enabled }),
  setReplaceAllSoundsWithCursor: (enabled: boolean) => set({ replaceAllSoundsWithCursor: enabled }),

  /** Update the configuration for a specific sound type */
  setSoundConfig: (key: SoundKey, config: SoundConfig) =>
    set((state) => ({
      soundConfigs: { ...state.soundConfigs, [key]: config },
    })),

  /** Toggle a specific sound type on/off */
  toggleSound: (type: SoundKey) =>
    set((state) => {
      const currentSounds = state.enabledSounds || {
        cursor: true, confirm: true, error: true, back: true, search: true,
      };
      return {
        enabledSounds: { ...currentSounds, [type]: !currentSounds[type] },
      };
    }),
});

/**
 * ============================================================================
 * TRASH SLICE
 * ============================================================================
 *
 * Handles soft-delete (trash), restore, and permanent delete for all
 * entity types: files, collections, storages, graphs, and docs.
 *
 * Pattern for each entity:
 *  - trash{Entity}: sets deleted: true (soft delete)
 *  - restore{Entity}: sets deleted: false
 *  - permanentDelete{Entity}: removes from array entirely + cascading cleanup
 *
 * Also provides emptyTrash() to permanently delete ALL trashed items at once.
 * ============================================================================
 */

import type { StoreSet, StoreGet } from '../types';
import type { ActivityClearRange, Collection, Doc, File, Graph, Storage } from '@/types';
import { getActivityClearRangeLabel, isTimestampInActivityRange } from '@/lib/activityRanges';
import { appendHistoryEntriesIfEnabled } from '../helpers/historyTracking';

function getTrashTimestamp(item: Pick<File | Collection | Storage | Graph | Doc, 'created'> & { lastModified?: number }) {
  return item.lastModified ?? item.created;
}

export const createTrashSlice = (set: StoreSet, get: StoreGet) => ({
  /* ── File Trash ───────────────────────────────────────────────────────── */

  trashFile: (id: string) =>
    set((state) => ({
      files: state.files.map((f) =>
        f.id === id ? { ...f, deleted: true, lastModified: Date.now() } : f
      ),
      history: appendHistoryEntriesIfEnabled(state, [
        {
          projectId: state.activeProjectId || 'global',
          action: 'delete',
          entityType: 'file',
          entityId: id,
          entityName: state.files.find((f) => f.id === id)?.name,
        },
      ]),
    })),

  restoreFile: (id: string) =>
    set((state) => ({
      files: state.files.map((f) =>
        f.id === id ? { ...f, deleted: false, lastModified: Date.now() } : f
      ),
      history: appendHistoryEntriesIfEnabled(state, [
        {
          projectId: state.activeProjectId || 'global',
          action: 'restore',
          entityType: 'file',
          entityId: id,
          entityName: state.files.find((f) => f.id === id)?.name,
        },
      ]),
    })),

  /** Permanently remove file + all its highlights */
  permanentDeleteFile: (id: string) =>
    set((state) => ({
      files: state.files.filter((f) => f.id !== id),
      highlights: state.highlights.filter((t) => t.fileId !== id),
      history: appendHistoryEntriesIfEnabled(state, [
        {
          projectId: state.activeProjectId || 'global',
          action: 'delete',
          entityType: 'file',
          entityId: id,
          entityName: state.files.find((f) => f.id === id)?.name,
          details: 'Permanent Delete',
        },
      ]),
    })),

  /* ── Collection Trash ─────────────────────────────────────────────────── */

  trashCollection: (id: string) =>
    set((state) => {
      const collection = state.collections.find((c) => c.id === id);
      const isBucket = collection?.type === 'bucket';
      return {
        collections: state.collections.map((c) =>
          c.id === id ? { ...c, deleted: true, lastModified: Date.now() } : c
        ),
        // Clear active collection if trashing the active bucket
        activeCollectionId:
          isBucket && state.activeCollectionId === id ? null : state.activeCollectionId,
        history: appendHistoryEntriesIfEnabled(state, [
          {
            projectId: state.activeProjectId || 'global',
            action: 'delete',
            entityType: 'collection',
            entityId: id,
            entityName: collection?.name,
          },
        ]),
      };
    }),

  restoreCollection: (id: string) =>
    set((state) => ({
      collections: state.collections.map((c) =>
        c.id === id ? { ...c, deleted: false, lastModified: Date.now() } : c
      ),
      history: appendHistoryEntriesIfEnabled(state, [
        {
          projectId: state.activeProjectId || 'global',
          action: 'restore',
          entityType: 'collection',
          entityId: id,
          entityName: state.collections.find((c) => c.id === id)?.name,
        },
      ]),
    })),

  /** Permanently remove collection + all its highlights */
  permanentDeleteCollection: (id: string) =>
    set((state) => ({
      collections: state.collections.filter((c) => c.id !== id),
      highlights: state.highlights.filter((h) => h.collectionId !== id),
      history: appendHistoryEntriesIfEnabled(state, [
        {
          projectId: state.activeProjectId || 'global',
          action: 'delete',
          entityType: 'collection',
          entityId: id,
          entityName: state.collections.find((c) => c.id === id)?.name,
          details: 'Permanent Delete',
        },
      ]),
    })),

  /* ── Storage Trash ────────────────────────────────────────────────────── */

  /** Soft-delete a storage (alias for deleteStorage action in entity slice) */
  trashStorage: (id: string) => {
    // Delegate to deleteStorage which handles active storage switching
    get().deleteStorage(id);
  },

  restoreStorage: (id: string) =>
    set((state) => ({
      storages: state.storages.map((s) =>
        s.id === id ? { ...s, deleted: false, lastModified: Date.now() } : s
      ),
      history: appendHistoryEntriesIfEnabled(state, [
        {
          projectId: state.activeProjectId || 'global',
          action: 'restore',
          entityType: 'storage',
          entityId: id,
          entityName: state.storages.find((s) => s.id === id)?.name,
        },
      ]),
    })),

  /** Permanently remove storage + all its files */
  permanentDeleteStorage: (id: string) =>
    set((state) => {
      const storageFileIds = new Set(
        state.files.filter((f) => f.storageId === id).map((f) => f.id)
      );
      return {
        storages: state.storages.filter((s) => s.id !== id),
        files: state.files.filter((f) => !storageFileIds.has(f.id)),
        history: appendHistoryEntriesIfEnabled(state, [
          {
            projectId: state.activeProjectId || 'global',
            action: 'delete',
            entityType: 'storage',
            entityId: id,
            entityName: state.storages.find((s) => s.id === id)?.name,
            details: 'Permanently Deleted',
          },
        ]),
      };
    }),

  /* ── Graph Trash ──────────────────────────────────────────────────────── */

  trashGraph: (id: string) =>
    set((state) => ({
      graphs: state.graphs.map((g) =>
        g.id === id ? { ...g, deleted: true, lastModified: Date.now() } : g
      ),
      activeGraphId: state.activeGraphId === id ? null : state.activeGraphId,
      history: appendHistoryEntriesIfEnabled(state, [
        {
          projectId: state.activeProjectId || 'global',
          action: 'delete',
          entityType: 'graph',
          entityId: id,
          entityName: state.graphs.find((g) => g.id === id)?.name,
        },
      ]),
    })),

  restoreGraph: (id: string) =>
    set((state) => ({
      graphs: state.graphs.map((g) =>
        g.id === id ? { ...g, deleted: false, lastModified: Date.now() } : g
      ),
      history: appendHistoryEntriesIfEnabled(state, [
        {
          projectId: state.activeProjectId || 'global',
          action: 'restore',
          entityType: 'graph',
          entityId: id,
          entityName: state.graphs.find((g) => g.id === id)?.name,
        },
      ]),
    })),

  /** Permanently remove graph + all its nodes and edges */
  permanentDeleteGraph: (id: string) =>
    set((state) => ({
      graphs: state.graphs.filter((g) => g.id !== id),
      graphNodes: state.graphNodes.filter((n) => n.graphId !== id),
      graphEdges: state.graphEdges.filter((e) => e.graphId !== id),
      history: appendHistoryEntriesIfEnabled(state, [
        {
          projectId: state.activeProjectId || 'global',
          action: 'delete',
          entityType: 'graph',
          entityId: id,
          entityName: state.graphs.find((g) => g.id === id)?.name,
          details: 'Permanent Delete',
        },
      ]),
    })),

  /* ── Doc Trash ────────────────────────────────────────────────────────── */

  trashDoc: (id: string) =>
    set((state) => ({
      docs: state.docs.map((d) =>
        d.id === id ? { ...d, deleted: true, lastModified: Date.now() } : d
      ),
      activeDocId: state.activeDocId === id ? null : state.activeDocId,
      history: appendHistoryEntriesIfEnabled(state, [
        {
          projectId: state.activeProjectId || 'global',
          action: 'delete',
          entityType: 'doc',
          entityId: id,
          entityName: state.docs.find((d) => d.id === id)?.name,
